--
-- Name: build_embedding_generation_index(uuid); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.build_embedding_generation_index(requested_generation_id uuid) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $_$
DECLARE row_data embedding_index_generations%ROWTYPE; dims integer; metric text; opclass text; sql_text text;
BEGIN
  SELECT * INTO row_data FROM embedding_index_generations WHERE id=requested_generation_id FOR UPDATE;
  IF row_data.status NOT IN ('building','verifying') OR row_data.index_name !~ '^nd_hnsw_[a-f0-9]{32}$' THEN RAISE EXCEPTION 'generation is not buildable' USING ERRCODE='23514'; END IF;
  SELECT dimensions,distance_metric INTO dims,metric FROM embedding_profile_versions WHERE id=row_data.profile_version_id;
  opclass:=CASE metric WHEN 'cosine' THEN 'vector_cosine_ops' WHEN 'l2' THEN 'vector_l2_ops' WHEN 'inner_product' THEN 'vector_ip_ops' ELSE NULL END;
  IF opclass IS NULL THEN RAISE EXCEPTION 'unsupported vector metric' USING ERRCODE='23514'; END IF;
  sql_text:=format('CREATE INDEX %I ON new_design.embedding_vectors USING hnsw ((embedding::vector(%s)) %s) WHERE generation_id=%L::uuid AND status=''eligible''',row_data.index_name,dims,opclass,row_data.id::text);
  EXECUTE sql_text;
  UPDATE embedding_index_generations SET status='verifying' WHERE id=requested_generation_id;
END $_$;


--
-- Name: card_kernel_compat_write(); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.card_kernel_compat_write() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $$
DECLARE
  table_name text:=TG_ARGV[0];
  pk_columns text[]:=string_to_array(TG_ARGV[1],',');
  old_values jsonb;
  new_values jsonb;
  identity_values jsonb;
  target_card_id uuid;
  target_version_id uuid:=gen_random_uuid();
  target_type_id uuid;
  target_type_version_id uuid;
  next_revision integer;
  target_title text;
BEGIN
  IF TG_OP<>'INSERT' THEN old_values:=to_jsonb(OLD); END IF;
  IF TG_OP<>'DELETE' THEN new_values:=to_jsonb(NEW); END IF;
  SELECT id,current_version_id INTO STRICT target_type_id,target_type_version_id
  FROM card_types WHERE space_id='00000000-0000-4000-8000-000000000001' AND type_key='legacy.'||table_name;
  IF TG_OP='INSERT' THEN
    SELECT jsonb_object_agg(key,new_values->key ORDER BY key) INTO identity_values FROM unnest(pk_columns) key;
    target_card_id:=md5('card-kernel-v2:record:'||table_name||':'||identity_values::text)::uuid;
    target_title:=coalesce(nullif(new_values->>'title',''),nullif(new_values->>'name',''),nullif(new_values->>'label',''),table_name||' · '||left(identity_values::text,80));
    new_values:=new_values||jsonb_build_object('__legacy_table',table_name,'__legacy_identity',identity_values,'__convergence_category','compat_write');
    INSERT INTO cards(id,space_id,card_type_id,title,status,revision,type_version_id,current_version_id,values)
    VALUES(target_card_id,'00000000-0000-4000-8000-000000000001',target_type_id,target_title,'active',1,target_type_version_id,target_version_id,new_values);
    INSERT INTO card_versions(id,card_id,revision,type_version_id,title,values,source)
    VALUES(target_version_id,target_card_id,1,target_type_version_id,target_title,new_values,'create');
    INSERT INTO card_version_actions(id,card_id,card_version_id,action_key,payload)
    VALUES(gen_random_uuid(),target_card_id,target_version_id,'compat.insert',jsonb_build_object('legacyTable',table_name));
    RETURN NEW;
  END IF;
  SELECT jsonb_object_agg(key,old_values->key ORDER BY key) INTO identity_values FROM unnest(pk_columns) key;
  target_card_id:=md5('card-kernel-v2:record:'||table_name||':'||identity_values::text)::uuid;
  SELECT coalesce(max(revision),0)+1 INTO next_revision FROM card_versions WHERE card_id=target_card_id;
  IF TG_OP='DELETE' THEN
    target_title:=coalesce(nullif(old_values->>'title',''),nullif(old_values->>'name',''),nullif(old_values->>'label',''),table_name||' · '||left(identity_values::text,80));
    old_values:=old_values||jsonb_build_object('__legacy_table',table_name,'__legacy_identity',identity_values,'__convergence_category','compat_delete');
    INSERT INTO card_versions(id,card_id,revision,type_version_id,title,values,source)
    VALUES(target_version_id,target_card_id,next_revision,target_type_version_id,target_title,old_values,'archive');
    UPDATE cards SET status='archived',revision=revision+1,current_version_id=target_version_id,values=old_values,updated_at=now(),archived_at=now() WHERE id=target_card_id;
    INSERT INTO card_version_actions(id,card_id,card_version_id,action_key,payload)
    VALUES(gen_random_uuid(),target_card_id,target_version_id,'compat.archive',jsonb_build_object('legacyTable',table_name));
    RETURN OLD;
  END IF;
  target_title:=coalesce(nullif(new_values->>'title',''),nullif(new_values->>'name',''),nullif(new_values->>'label',''),table_name||' · '||left(identity_values::text,80));
  new_values:=new_values||jsonb_build_object('__legacy_table',table_name,'__legacy_identity',identity_values,'__convergence_category','compat_update');
  INSERT INTO card_versions(id,card_id,revision,type_version_id,title,values,source)
  VALUES(target_version_id,target_card_id,next_revision,target_type_version_id,target_title,new_values,'edit');
  UPDATE cards SET title=target_title,revision=revision+1,current_version_id=target_version_id,values=new_values,updated_at=now() WHERE id=target_card_id;
  INSERT INTO card_version_actions(id,card_id,card_version_id,action_key,payload)
  VALUES(gen_random_uuid(),target_card_id,target_version_id,'compat.update',jsonb_build_object('legacyTable',table_name));
  RETURN NEW;
END $$;


--
-- Name: cascade_embedding_profile_archive(); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.cascade_embedding_profile_archive() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $$
BEGIN
  IF OLD.status='active' AND NEW.status='archived' THEN
    UPDATE embedding_source_snapshots source SET status='stale',stale_at=now() WHERE source.status='current' AND source.profile_version_id IN(SELECT id FROM embedding_profile_versions WHERE profile_id=NEW.id);
    UPDATE embedding_chunks chunk SET status='stale',stale_at=now() WHERE chunk.status='current' AND chunk.profile_version_id IN(SELECT id FROM embedding_profile_versions WHERE profile_id=NEW.id);
    UPDATE embedding_vectors item SET status='stale' WHERE item.status='eligible' AND item.profile_version_id IN(SELECT id FROM embedding_profile_versions WHERE profile_id=NEW.id);
    UPDATE embedding_requests request SET status='stale',updated_at=now() WHERE request.status IN ('pending','running','retry_scheduled','succeeded') AND request.profile_version_id IN(SELECT id FROM embedding_profile_versions WHERE profile_id=NEW.id);
    UPDATE embedding_index_generations generation SET status='stale' WHERE generation.status IN ('ready','active') AND generation.profile_version_id IN(SELECT id FROM embedding_profile_versions WHERE profile_id=NEW.id);
    UPDATE embedding_index_states SET status='stale',revision=revision+1,updated_at=now() WHERE profile_id=NEW.id;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: check_world_package_complete_refs(); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.check_world_package_complete_refs() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $$
BEGIN
 IF TG_TABLE_NAME='world_package_versions' THEN
  IF (SELECT count(*) FROM world_package_card_refs WHERE package_id=NEW.id)<>jsonb_array_length(NEW.frame->'cards') OR (SELECT count(*) FROM world_package_relation_refs WHERE package_id=NEW.id)<>jsonb_array_length(NEW.frame->'relations') THEN RAISE EXCEPTION 'incomplete frozen world reference set' USING ERRCODE='23514'; END IF;
 ELSE
  IF (SELECT count(*) FROM world_package_install_card_refs WHERE installation_id=NEW.id)<>jsonb_array_length(NEW.receipt->'cards') OR (SELECT count(*) FROM world_package_install_relation_refs WHERE installation_id=NEW.id)<>jsonb_array_length(NEW.receipt->'relations') THEN RAISE EXCEPTION 'incomplete world installation mapping' USING ERRCODE='23514'; END IF;
 END IF;
 RETURN NEW;
END $$;


--
-- Name: check_world_sync_complete_children(); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.check_world_sync_complete_children() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $$
DECLARE selected jsonb; fields integer; relations integer;
BEGIN
 selected:=world_sync_selected_input(NEW);
 IF NEW.operation='push' THEN
  IF (SELECT count(*) FROM world_package_push_candidates WHERE command_id=NEW.id)<>1 THEN RAISE EXCEPTION 'world push requires original candidate' USING ERRCODE='23514'; END IF;
 ELSIF NEW.operation IN ('pull','publish') THEN
  fields:=jsonb_array_length(selected->'choices')+coalesce((SELECT sum(jsonb_array_length(card->'mapping')) FROM jsonb_array_elements(coalesce(selected->'newCards','[]'::jsonb)) card),0);
  relations:=jsonb_array_length(coalesce(selected->'relationChoices','[]'::jsonb));
  IF selected IS NULL OR (SELECT count(*) FROM world_package_field_baselines WHERE command_id=NEW.id)<>fields
   OR (SELECT count(*) FROM world_package_relation_baselines WHERE command_id=NEW.id)<>relations
   OR (NEW.operation='pull' AND (SELECT count(*) FROM world_package_added_card_refs WHERE command_id=NEW.id)<>jsonb_array_length(coalesce(selected->'newCards','[]'::jsonb)))
  THEN RAISE EXCEPTION 'world sync requires complete selected mappings and baselines' USING ERRCODE='23514'; END IF;
 END IF;
 RETURN NEW;
END $$;


--
-- Name: context_activation_rule_stats(jsonb, integer); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.context_activation_rule_stats(node jsonb, depth integer DEFAULT 1) RETURNS TABLE(max_depth integer, condition_count integer, is_valid boolean)
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $$
DECLARE child jsonb; child_stats record; field_name text; operator_name text;
BEGIN
  IF jsonb_typeof(node)<>'object' OR depth>4 THEN RETURN QUERY SELECT depth,0,false; RETURN; END IF;
  IF node->>'kind'='condition' THEN
    field_name:=node->>'field'; operator_name:=node->>'operator';
    RETURN QUERY SELECT depth,1,
      field_name=ANY(ARRAY['task_key','task_group','content_type','tag','material_status','canonical_status','volume','chapter','scene','story_range','relation_exists','association_exists','source_type','stale','manual_switch'])
      AND operator_name=ANY(ARRAY['equals','not_equals','in','not_in','contains','exists','not_exists','gte','lte','between','enabled'])
      AND (node-ARRAY['kind','field','operator','value']::text[])='{}'::jsonb
      AND (NOT (node ? 'value') OR jsonb_typeof(node->'value') IN ('string','number','boolean','array','null'))
      AND (NOT (node ? 'value') OR jsonb_typeof(node->'value')<>'array' OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(node->'value') AS array_item(value) WHERE jsonb_typeof(value) NOT IN ('string','number')));
    RETURN;
  END IF;
  IF node->>'kind'<>'group' OR NOT (node->>'operator'=ANY(ARRAY['and','or'])) OR (node-ARRAY['kind','operator','items']::text[])<>'{}'::jsonb OR jsonb_typeof(node->'items')<>'array' OR jsonb_array_length(node->'items')>20 THEN
    RETURN QUERY SELECT depth,0,false; RETURN;
  END IF;
  max_depth:=depth; condition_count:=0; is_valid:=true;
  FOR child IN SELECT value FROM jsonb_array_elements(node->'items') LOOP
    SELECT * INTO child_stats FROM context_activation_rule_stats(child,depth+1);
    max_depth:=greatest(max_depth,child_stats.max_depth); condition_count:=condition_count+child_stats.condition_count; is_valid:=is_valid AND child_stats.is_valid;
  END LOOP;
  is_valid:=is_valid AND condition_count<=40;
  RETURN NEXT;
END $$;


--
-- Name: create_character_author_influence_candidate(); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.create_character_author_influence_candidate() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $$
DECLARE first_order integer;
BEGIN
 IF NEW.status='succeeded' AND NEW.output->'influenceDraft' IS NOT NULL AND NEW.output->'influenceDraft'<>'null'::jsonb THEN
  SELECT COALESCE(max(document.logical_order),0)+1 INTO first_order FROM chapter_documents document JOIN chapter_stable_checkpoints checkpoint ON checkpoint.chapter_document_id=document.id AND checkpoint.body_version_id=document.adopted_version_id AND checkpoint.status='stable' WHERE document.book_id=NEW.book_id AND document.status='active';
  INSERT INTO character_author_influence_candidates(id,book_id,card_id,source_hash,draft,target_start,target_end) VALUES(NEW.id,NEW.book_id,NEW.card_id,NEW.source_snapshot->>'hash',NEW.output->'influenceDraft',first_order,first_order+2) ON CONFLICT(id) DO NOTHING;
 END IF;
 RETURN NEW;
END $$;


--
-- Name: dependency_content_hash(text); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.dependency_content_hash(payload text) RETURNS character
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $$
  SELECT (md5(COALESCE(payload,'')) || md5(reverse(COALESCE(payload,''))))::char(64)
$$;


--
-- Name: enqueue_graph_projection_resource(); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.enqueue_graph_projection_resource() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $$
DECLARE target dependency_resources%ROWTYPE; request_kind_value text; reason_value text; idempotency_value text;
BEGIN
  IF TG_TABLE_NAME='dependency_resources' THEN
    target:=NEW;
    request_kind_value:='incremental_upsert'; reason_value:='统一依赖资源登记后同步图投影。'; idempotency_value:='resource:'||target.id::text;
  ELSE
    SELECT * INTO target FROM dependency_resources WHERE id=(to_jsonb(NEW)->>'resource_id')::uuid;
    request_kind_value:='tombstone'; reason_value:='统一依赖资源失效后移出当前图投影。'; idempotency_value:='invalidation:'||(to_jsonb(NEW)->>'event_id')||':'||target.id::text;
  END IF;
  IF target.book_id IS NULL OR target.resource_kind NOT IN ('card_version','card_relation','canonical_fact','state_change','knowledge_state_change','story_event_timing','story_event_relation','planning_version') THEN RETURN NEW; END IF;
  INSERT INTO graph_projection_book_states(book_id,last_request_at) VALUES(target.book_id,now()) ON CONFLICT(book_id) DO UPDATE SET last_request_at=excluded.last_request_at,revision=graph_projection_book_states.revision+1,updated_at=now();
  INSERT INTO graph_projection_requests(id,book_id,request_kind,dependency_resource_id,source_kind,source_id,source_version_id,source_revision,source_hash,reason,idempotency_key)
  VALUES(gen_random_uuid(),target.book_id,request_kind_value,target.id,target.resource_kind,target.stable_object_id,target.exact_version_id,1,target.content_hash,reason_value,idempotency_value)
  ON CONFLICT(book_id,idempotency_key) DO NOTHING;
  RETURN NEW;
END $$;


--
-- Name: enqueue_registered_background_job(text, uuid, uuid, uuid, uuid, uuid, text); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.enqueue_registered_background_job(request_kind text, request_id uuid, request_space_id uuid, request_book_id uuid, requested_correlation_id uuid, requested_causation_id uuid, requested_producer_kind text DEFAULT 'domain_store'::text) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $$
DECLARE handler background_job_handlers%ROWTYPE; event_id uuid; job_id uuid; sequence_value bigint; payload_value jsonb; ordering_value text; priority_value integer:=0;
BEGIN
  SELECT * INTO handler FROM background_job_handlers WHERE specialized_request_kind=request_kind AND status='active';
  IF NOT FOUND THEN RAISE EXCEPTION 'no active handler registered for %',request_kind USING ERRCODE='23514'; END IF;
  IF requested_producer_kind NOT IN ('domain_store','migration_bridge') THEN RAISE EXCEPTION 'invalid specialized request producer kind' USING ERRCODE='23514'; END IF;
  IF request_kind='dependency_recompute_request' THEN SELECT priority INTO priority_value FROM dependency_recompute_requests WHERE id=request_id;
  ELSIF request_kind='ai_task' THEN SELECT priority INTO priority_value FROM ai_tasks WHERE id=request_id;
  END IF;
  payload_value:=jsonb_build_object('specializedRequestKind',request_kind,'specializedRequestId',request_id,'bookId',request_book_id);
  SELECT id,aggregate_sequence,ordering_key INTO event_id,sequence_value,ordering_value FROM outbox_events WHERE topic=handler.topic AND producer_idempotency_key='request:'||request_kind||':'||request_id::text;
  IF event_id IS NULL THEN
    ordering_value:=COALESCE('book:'||request_book_id::text||':handler:'||handler.handler_key,'space:'||request_space_id::text||':handler:'||handler.handler_key);
    sequence_value:=reserve_outbox_aggregate_sequence(request_space_id,request_book_id,CASE WHEN request_book_id IS NULL THEN 'space_runtime' ELSE 'book_runtime' END,COALESCE(request_book_id,request_space_id));
    event_id:=gen_random_uuid();
    INSERT INTO outbox_events(id,space_id,book_id,topic,event_version,aggregate_kind,aggregate_id,aggregate_sequence,ordering_key,producer_kind,producer_idempotency_key,payload,payload_hash,correlation_id,causation_id)
    VALUES(event_id,request_space_id,request_book_id,handler.topic,handler.event_version,CASE WHEN request_book_id IS NULL THEN 'space_runtime' ELSE 'book_runtime' END,COALESCE(request_book_id,request_space_id),sequence_value,ordering_value,requested_producer_kind,'request:'||request_kind||':'||request_id::text,payload_value,dependency_content_hash(payload_value::text),requested_correlation_id,requested_causation_id);
  END IF;
  SELECT id INTO job_id FROM background_jobs WHERE handler_key=handler.handler_key AND specialized_request_kind=request_kind AND specialized_request_id=request_id AND execution_generation=1;
  IF job_id IS NULL THEN
    job_id:=gen_random_uuid();
    INSERT INTO background_jobs(id,outbox_event_id,space_id,book_id,handler_key,job_kind,specialized_request_kind,specialized_request_id,ordering_key,aggregate_sequence,priority,max_attempts)
    VALUES(job_id,event_id,request_space_id,request_book_id,handler.handler_key,handler.job_kind,request_kind,request_id,ordering_value,sequence_value,priority_value,handler.default_max_attempts);
  END IF;
  RETURN job_id;
END $$;


--
-- Name: fence_resource_supplement_integrity_extraction(); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.fence_resource_supplement_integrity_extraction() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $$
DECLARE origin chapter_resource_supplements%ROWTYPE;
BEGIN
  SELECT * INTO origin FROM chapter_resource_supplements WHERE session_id=NEW.session_id AND book_id=NEW.book_id;
  IF origin.session_id IS NULL THEN RETURN NEW; END IF;
  IF origin.source_snapshot->>'contract'='stable_resource_correction_preview_v1' THEN
    PERFORM assert_resource_correction_claim(NEW);
    RETURN NEW;
  END IF;
  IF EXISTS(SELECT 1 FROM resource_supplement_integrity_issues issue JOIN chapter_documents document ON document.id=issue.chapter_document_id AND document.book_id=issue.book_id
    WHERE issue.book_id=NEW.book_id AND document.logical_order<=(origin.source_snapshot#>>'{basis,chapterOrder}')::numeric
      AND EXISTS(SELECT 1 FROM jsonb_array_elements(origin.source_snapshot#>'{catalog,subjects}') subject WHERE (subject->>'id')::uuid=issue.subject_id AND subject->>'subjectKind'=issue.subject_kind)
      AND NOT EXISTS(SELECT 1 FROM resource_supplement_integrity_resolutions resolution WHERE resolution.issue_id=issue.issue_id)) THEN
    RAISE EXCEPTION 'ordinary stable resource extraction cannot bypass actual source conflict' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: fence_resource_supplement_integrity_projection(); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.fence_resource_supplement_integrity_projection() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $$
DECLARE key_book uuid; key_kind text; key_subject uuid; key_state text;
BEGIN
  IF TG_OP='UPDATE' AND (NEW.book_id IS DISTINCT FROM OLD.book_id OR NEW.subject_kind IS DISTINCT FROM OLD.subject_kind OR NEW.subject_id IS DISTINCT FROM OLD.subject_id OR NEW.state_key IS DISTINCT FROM OLD.state_key)
    AND EXISTS(SELECT 1 FROM resource_supplement_integrity_issues issue WHERE issue.book_id=OLD.book_id AND issue.subject_kind=OLD.subject_kind AND issue.subject_id=OLD.subject_id AND issue.state_key=OLD.state_key
      AND NOT EXISTS(SELECT 1 FROM resource_supplement_integrity_resolutions resolution WHERE resolution.issue_id=issue.issue_id)) THEN
    RAISE EXCEPTION 'open resource source identity cannot be moved to bypass integrity' USING ERRCODE='23514';
  END IF;
  IF TG_OP='DELETE' THEN key_book=OLD.book_id;key_kind=OLD.subject_kind;key_subject=OLD.subject_id;key_state=OLD.state_key;
  ELSE key_book=NEW.book_id;key_kind=NEW.subject_kind;key_subject=NEW.subject_id;key_state=NEW.state_key; END IF;
  IF EXISTS(SELECT 1 FROM resource_supplement_integrity_issues issue WHERE issue.book_id=key_book AND issue.subject_kind=key_kind AND issue.subject_id=key_subject AND issue.state_key=key_state
    AND NOT EXISTS(SELECT 1 FROM resource_supplement_integrity_resolutions resolution WHERE resolution.issue_id=issue.issue_id)) THEN
    IF TG_OP='DELETE' OR NEW.is_stale IS DISTINCT FROM true THEN RAISE EXCEPTION 'open actual resource source conflict cannot be cleared by projection rebuild or deletion' USING ERRCODE='23514'; END IF;
  END IF;
  IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
END $$;


--
-- Name: guard_ai_attempt_update(); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.guard_ai_attempt_update() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $$
DECLARE debug_task boolean;
BEGIN
  IF TG_OP='DELETE' THEN RAISE EXCEPTION 'AI attempts cannot be deleted' USING ERRCODE='23514'; END IF;
  IF OLD.status IN ('succeeded','failed','cancelled','discarded') THEN RAISE EXCEPTION 'finished AI attempt is immutable' USING ERRCODE='23514'; END IF;
  IF (to_jsonb(NEW)-ARRAY['status','provider_request_digest','result_kind','result_stable_id','result_version_id','result_hash','error_category','retry_eligibility','error_summary','started_at','ended_at','debug_result','debug_execution','debug_failure']::text[]) IS DISTINCT FROM
     (to_jsonb(OLD)-ARRAY['status','provider_request_digest','result_kind','result_stable_id','result_version_id','result_hash','error_category','retry_eligibility','error_summary','started_at','ended_at','debug_result','debug_execution','debug_failure']::text[]) THEN
    RAISE EXCEPTION 'AI attempt frozen inputs are immutable' USING ERRCODE='23514';
  END IF;
  IF NOT ((OLD.status='queued' AND NEW.status IN ('running','cancelled')) OR (OLD.status='running' AND NEW.status IN ('succeeded','failed','cancelled','discarded'))) THEN
    RAISE EXCEPTION 'illegal AI attempt status transition' USING ERRCODE='23514';
  END IF;
  SELECT source_kind='prompt_composition_debug' INTO debug_task FROM new_design.ai_tasks WHERE id=OLD.task_id;
  IF debug_task IS true AND NEW.status IN ('succeeded','failed','cancelled','discarded') THEN
    IF (NEW.status='succeeded' AND (NEW.debug_result IS NULL OR NEW.debug_execution IS NULL OR NEW.debug_failure IS NOT NULL)) OR
       (NEW.status IN ('failed','cancelled','discarded') AND (NEW.debug_failure IS NULL OR NEW.debug_result IS NOT NULL)) THEN
      RAISE EXCEPTION 'debug terminal outcome is incomplete' USING ERRCODE='23514';
    END IF;
  END IF;
  IF ROW(NEW.debug_result,NEW.debug_execution,NEW.debug_failure) IS DISTINCT FROM ROW(OLD.debug_result,OLD.debug_execution,OLD.debug_failure) THEN
    IF debug_task IS DISTINCT FROM true OR OLD.status<>'running' OR NEW.status NOT IN ('succeeded','failed','cancelled','discarded') OR OLD.debug_result IS NOT NULL OR OLD.debug_execution IS NOT NULL OR OLD.debug_failure IS NOT NULL THEN
      RAISE EXCEPTION 'debug payload can only be frozen once when a debug attempt terminates' USING ERRCODE='23514';
    END IF;
  END IF;
  RETURN NEW;
END $$;


