--
-- Name: guard_context_binding_version(); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.guard_context_binding_version() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $$
DECLARE stats record;
BEGIN
  IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'context binding versions are immutable' USING ERRCODE='23514'; END IF;
  SELECT * INTO stats FROM context_activation_rule_stats(NEW.activation_rule);
  IF NOT stats.is_valid OR stats.max_depth>4 OR stats.condition_count>40 THEN RAISE EXCEPTION 'activation rule exceeds the safe typed rule contract' USING ERRCODE='23514'; END IF;
  RETURN NEW;
END $$;


--
-- Name: guard_context_preview(); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.guard_context_preview() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $$
BEGIN
  IF TG_OP='DELETE' THEN RAISE EXCEPTION 'context previews are immutable; stale them instead' USING ERRCODE='23514'; END IF;
  IF OLD.status NOT IN ('complete','invalid') OR NEW.status<>'stale' OR NEW.stale_at IS NULL OR
     (to_jsonb(NEW)-ARRAY['status','stale_at','stale_reason']::text[]) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['status','stale_at','stale_reason']::text[]) THEN
    RAISE EXCEPTION 'context preview may only transition to stale' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: guard_context_selector(); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.guard_context_selector() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $$
BEGIN
  IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'context binding selectors are immutable' USING ERRCODE='23514'; END IF;
  IF NEW.selector_kind IN ('explicit_source','prompt_component') AND (NEW.stable_object_id IS NULL OR NEW.exact_version_id IS NULL) THEN RAISE EXCEPTION 'explicit selector requires an exact source version' USING ERRCODE='23514'; END IF;
  IF NEW.selector_kind NOT IN ('explicit_source','prompt_component') AND (NEW.stable_object_id IS NOT NULL OR NEW.exact_version_id IS NOT NULL) THEN RAISE EXCEPTION 'dynamic selector cannot pin an unrelated source identity' USING ERRCODE='23514'; END IF;
  IF NEW.selector_kind='explicit_source' AND NEW.source_type NOT IN ('card_version','body_version','canonical_fact','knowledge_state_change','state_change','story_time','story_event_relation','research_document_version','planning_version','research_version','research_pack_version') THEN RAISE EXCEPTION 'unsupported explicit source type' USING ERRCODE='23514'; END IF;
  IF NEW.selector_kind='prompt_component' AND NEW.source_type<>'prompt_component' THEN RAISE EXCEPTION 'prompt component selector requires prompt_component source type' USING ERRCODE='23514'; END IF;
  IF NEW.selector_kind IN ('card_type','tag','smart_view','relation') AND NEW.source_type<>'card_version' THEN RAISE EXCEPTION 'card selector requires card_version source type' USING ERRCODE='23514'; END IF;
  IF NEW.selector_kind='story_range' AND NEW.source_type NOT IN ('card_version','story_time') THEN RAISE EXCEPTION 'story range selector has an unsupported source type' USING ERRCODE='23514'; END IF;
  IF NEW.selector_kind='research_pack' AND NEW.source_type NOT IN ('research_version','research_pack_version') THEN RAISE EXCEPTION 'research pack selector has an unsupported source type' USING ERRCODE='23514'; END IF;
  IF NEW.selector_kind='retrieval_trace' AND NEW.source_type<>'retrieval_chunk' THEN RAISE EXCEPTION 'retrieval selector requires retrieval_chunk source type' USING ERRCODE='23514'; END IF;
  IF NEW.selector_kind IN ('explicit_source','prompt_component') AND NEW.selector_config<>'{}'::jsonb THEN RAISE EXCEPTION 'explicit selector config must be empty' USING ERRCODE='23514'; END IF;
  IF NEW.selector_kind='card_type' AND (NOT (NEW.selector_config ? 'typeKey') OR (NEW.selector_config-ARRAY['typeKey']::text[])<>'{}'::jsonb) THEN RAISE EXCEPTION 'card type selector requires only typeKey' USING ERRCODE='23514'; END IF;
  IF NEW.selector_kind='tag' AND (NOT (NEW.selector_config ? 'tagId') OR (NEW.selector_config-ARRAY['tagId']::text[])<>'{}'::jsonb) THEN RAISE EXCEPTION 'tag selector requires only tagId' USING ERRCODE='23514'; END IF;
  IF NEW.selector_kind='smart_view' AND (NOT (NEW.selector_config ? 'smartViewId') OR (NEW.selector_config-ARRAY['smartViewId','limit']::text[])<>'{}'::jsonb) THEN RAISE EXCEPTION 'smart view selector requires smartViewId and optional limit' USING ERRCODE='23514'; END IF;
  IF NEW.selector_kind='relation' AND (NOT (NEW.selector_config ? 'relationTypeId') OR (NEW.selector_config-ARRAY['relationTypeId','anchorCardId']::text[])<>'{}'::jsonb) THEN RAISE EXCEPTION 'relation selector requires relationTypeId and optional anchorCardId' USING ERRCODE='23514'; END IF;
  IF NEW.selector_kind='story_range' AND (NOT (NEW.selector_config ?& ARRAY['start','end']) OR (NEW.selector_config-ARRAY['start','end']::text[])<>'{}'::jsonb) THEN RAISE EXCEPTION 'story range selector requires start and end' USING ERRCODE='23514'; END IF;
  IF NEW.selector_kind='research_pack' AND (NOT (NEW.selector_config ? 'packVersionId') OR (NEW.selector_config-ARRAY['packVersionId']::text[])<>'{}'::jsonb) THEN RAISE EXCEPTION 'research pack selector requires only packVersionId' USING ERRCODE='23514'; END IF;
  IF NEW.selector_kind='retrieval_trace' AND (NOT (NEW.selector_config ? 'retrievalRunId') OR (NEW.selector_config-ARRAY['retrievalRunId','limit']::text[])<>'{}'::jsonb) THEN RAISE EXCEPTION 'retrieval selector requires an existing trace and optional limit; fake retrieval is forbidden' USING ERRCODE='23514'; END IF;
  IF EXISTS(SELECT 1 FROM jsonb_object_keys(NEW.selector_config) AS item(key_name) WHERE key_name ~* '(sql|jsonpath|cypher|javascript|script|prompt)') THEN RAISE EXCEPTION 'selector contains a forbidden executable expression' USING ERRCODE='23514'; END IF;
  RETURN NEW;
END $$;


--
-- Name: guard_creation_director_control_receipts(); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.guard_creation_director_control_receipts() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $$
DECLARE entry jsonb;
BEGIN
 IF TG_OP='DELETE' THEN IF jsonb_array_length(OLD.director_control_receipts)>0 THEN RAISE EXCEPTION '导演原控制回执不可删除' USING ERRCODE='23514'; END IF; RETURN OLD; END IF;
 FOR entry IN SELECT value FROM jsonb_array_elements(OLD.director_control_receipts) LOOP
  IF NOT NEW.director_control_receipts @> jsonb_build_array(entry) THEN RAISE EXCEPTION '导演原控制回执不可改写' USING ERRCODE='23514'; END IF;
 END LOOP;
 RETURN NEW;
END $$;


--
-- Name: guard_creation_preparation_ai(); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.guard_creation_preparation_ai() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $_$
DECLARE entry jsonb; snapshot model_route_snapshots%ROWTYPE; source_batch ai_generation_batches%ROWTYPE;
BEGIN
 IF TG_OP='DELETE' THEN IF OLD.preparation_contract IS NOT NULL THEN RAISE EXCEPTION '受控开书准备原记录不可删除' USING ERRCODE='23514'; END IF; RETURN OLD; END IF;
 IF TG_OP='UPDATE' AND OLD.preparation_contract IS DISTINCT FROM NEW.preparation_contract THEN RAISE EXCEPTION '原批次不能伪装为新受控开书准备' USING ERRCODE='23514'; END IF;
 IF NEW.preparation_contract IS NULL THEN RETURN NEW; END IF;
 IF NEW.frozen_plan->>'format' IS DISTINCT FROM '1' OR NEW.frozen_plan->'input'->>'contract' IS DISTINCT FROM 'creation_preparation_v1'
  OR NEW.frozen_plan->'input'->>'sessionId' IS DISTINCT FROM NEW.session_id::text
  OR NEW.frozen_plan->'input'->>'sessionRevision' IS DISTINCT FROM NEW.base_revision::text
  OR NEW.frozen_plan->>'taskType' IS DISTINCT FROM NEW.operation OR NEW.frozen_plan->>'assetId' IS DISTINCT FROM NEW.prompt_id
  OR NEW.frozen_plan->>'assetVersion' IS DISTINCT FROM NEW.prompt_version
  OR NEW.prompt_id IS DISTINCT FROM (CASE NEW.operation WHEN 'directions' THEN 'new_design.creation.directions' WHEN 'initial_content' THEN 'new_design.creation.initial_content' WHEN 'form_assist' THEN 'new_design.forms.assist' END)
  OR NEW.prompt_version IS DISTINCT FROM 'v1' OR jsonb_typeof(NEW.frozen_plan->'sourceBatches') IS DISTINCT FROM 'array'
  OR jsonb_typeof(NEW.frozen_plan->'input'->'targets') IS DISTINCT FROM 'array'
  OR jsonb_typeof(NEW.frozen_plan->'outputSchema') IS DISTINCT FROM 'object'
  OR jsonb_typeof(NEW.frozen_plan->'messages') IS DISTINCT FROM 'array'
  OR COALESCE(NEW.frozen_plan->>'inputHash','') !~ '^[0-9a-f]{64}$' THEN
  RAISE EXCEPTION '受控开书准备必须冻结准确来源与自有提示合同' USING ERRCODE='23514';
 END IF;
 SELECT * INTO snapshot FROM model_route_snapshots WHERE id=NEW.model_route_snapshot_id;
 IF NOT FOUND OR snapshot.managed_task_key IS DISTINCT FROM NEW.operation
  OR NEW.frozen_plan->'modelSnapshot'->>'id' IS DISTINCT FROM snapshot.id::text
  OR NEW.frozen_plan->'modelSnapshot'->>'snapshotHash' IS DISTINCT FROM snapshot.snapshot_hash THEN
  RAISE EXCEPTION '开书准备必须引用真实本任务模型快照' USING ERRCODE='23514';
 END IF;
 FOR entry IN SELECT value FROM jsonb_array_elements(NEW.frozen_plan->'sourceBatches') LOOP
  SELECT * INTO source_batch FROM ai_generation_batches WHERE id=(entry->>'id')::uuid;
  IF NOT FOUND OR source_batch.id=NEW.id OR source_batch.session_id IS DISTINCT FROM NEW.session_id OR source_batch.preparation_contract IS DISTINCT FROM NEW.preparation_contract
   OR source_batch.frozen_plan->>'inputHash' IS DISTINCT FROM entry->>'inputHash'
   OR COALESCE(entry->>'outputHash','') !~ '^[0-9a-f]{64}$' OR jsonb_typeof(source_batch.output_payload->'candidates') IS DISTINCT FROM 'array' THEN
   RAISE EXCEPTION '累计候选必须引用同一开书原批次精确输出' USING ERRCODE='23514';
  END IF;
 END LOOP;
 IF TG_OP='INSERT' THEN
  IF NEW.status<>'running' OR NEW.preparation_generated_output IS NOT NULL OR NEW.preparation_execution IS NOT NULL OR NEW.preparation_terminal IS NOT NULL OR NEW.preparation_superseded_by IS NOT NULL OR jsonb_array_length(NEW.preparation_adoption_receipts)<>0 THEN RAISE EXCEPTION '新开书准备必须从未执行的冻结运行开始' USING ERRCODE='23514'; END IF;
 ELSE
  IF (OLD.session_id,OLD.operation,OLD.base_revision,OLD.prompt_id,OLD.prompt_version,OLD.preparation_request_key,OLD.preparation_request_hash,OLD.frozen_plan,OLD.model_route_snapshot_id,OLD.preparation_lease_until) IS DISTINCT FROM (NEW.session_id,NEW.operation,NEW.base_revision,NEW.prompt_id,NEW.prompt_version,NEW.preparation_request_key,NEW.preparation_request_hash,NEW.frozen_plan,NEW.model_route_snapshot_id,NEW.preparation_lease_until) THEN RAISE EXCEPTION '已领取开书来源与请求不可换版' USING ERRCODE='23514'; END IF;
  IF OLD.preparation_generated_output IS NOT NULL AND (OLD.preparation_generated_output IS DISTINCT FROM NEW.preparation_generated_output OR OLD.preparation_execution IS DISTINCT FROM NEW.preparation_execution) THEN RAISE EXCEPTION '已保存原模型输出与真实用量不可改写' USING ERRCODE='23514'; END IF;
  IF jsonb_typeof(OLD.output_payload->'candidates')='array' AND OLD.output_payload IS DISTINCT FROM NEW.output_payload THEN RAISE EXCEPTION '已保存累计候选不可改写' USING ERRCODE='23514'; END IF;
  IF OLD.preparation_terminal IS NOT NULL AND (OLD.preparation_terminal IS DISTINCT FROM NEW.preparation_terminal OR OLD.status IS DISTINCT FROM NEW.status OR OLD.preparation_generated_output IS DISTINCT FROM NEW.preparation_generated_output) THEN RAISE EXCEPTION '已结束原准备不可复活或接受迟到结果' USING ERRCODE='23514'; END IF;
  IF OLD.status<>NEW.status AND NOT ((OLD.status='running' AND NEW.status IN('review','failed','discarded')) OR (OLD.status='review' AND NEW.status IN('applied','discarded'))) THEN RAISE EXCEPTION '开书准备状态迁移非法' USING ERRCODE='23514'; END IF;
  FOR entry IN SELECT value FROM jsonb_array_elements(OLD.preparation_adoption_receipts) LOOP
   IF NOT NEW.preparation_adoption_receipts @> jsonb_build_array(entry) THEN RAISE EXCEPTION '原候选采用回执不可改写' USING ERRCODE='23514'; END IF;
  END LOOP;
 END IF;
 IF NEW.preparation_generated_output IS NOT NULL THEN
  IF jsonb_typeof(NEW.preparation_generated_output->'candidates') IS DISTINCT FROM 'array' OR NEW.preparation_execution IS NULL
   OR NEW.preparation_execution->'modelSnapshot'->>'routeSnapshotId' IS DISTINCT FROM snapshot.id::text
   OR NEW.preparation_execution->'modelSnapshot'->>'routeSnapshotHash' IS DISTINCT FROM snapshot.snapshot_hash
   OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(NEW.preparation_execution->'modelSnapshot'->'attempts') attempt WHERE attempt->>'requestSent'='true' AND attempt->>'status'='succeeded') THEN RAISE EXCEPTION '保存模型输出必须附真实已发送执行与快照回执' USING ERRCODE='23514'; END IF;
 END IF;
 IF NEW.status IN('review','applied') AND (NEW.preparation_generated_output IS NULL OR jsonb_typeof(NEW.output_payload->'candidates') IS DISTINCT FROM 'array') THEN RAISE EXCEPTION '候选审阅与采用必须已有真实保存的模型输出' USING ERRCODE='23514'; END IF;
 IF NEW.preparation_terminal IS NOT NULL AND NEW.status<>'discarded' THEN RAISE EXCEPTION '已结束准备必须保留终止状态' USING ERRCODE='23514'; END IF;
 IF NEW.preparation_terminal='released' AND NEW.preparation_generated_output IS NULL THEN RAISE EXCEPTION '保留旧结果结束必须已有原输出' USING ERRCODE='23514'; END IF;
 IF NEW.preparation_terminal='ended_unknown' AND NEW.preparation_generated_output IS NOT NULL THEN RAISE EXCEPTION '真实已保存输出不能称为未知未返回' USING ERRCODE='23514'; END IF;
 IF NEW.preparation_superseded_by IS NOT NULL THEN
  SELECT * INTO source_batch FROM ai_generation_batches WHERE id=NEW.preparation_superseded_by;
  IF NOT FOUND OR source_batch.id=NEW.id OR source_batch.session_id IS DISTINCT FROM NEW.session_id OR source_batch.preparation_contract IS DISTINCT FROM NEW.preparation_contract OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(source_batch.frozen_plan->'sourceBatches') source WHERE source->>'id'=NEW.id::text) THEN RAISE EXCEPTION '前阶段只读来源必须指向真实累计后批次' USING ERRCODE='23514'; END IF;
 END IF;
 RETURN NEW;
END $_$;


--
-- Name: guard_creative_extraction_preview(); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.guard_creative_extraction_preview() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $$
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'creative evidence cannot be deleted' USING ERRCODE='23514'; END IF;
 IF ROW(NEW.id,NEW.request_key,NEW.book_id,NEW.mode,NEW.input_hash,NEW.original_input,NEW.input_payload,NEW.frozen_plan,NEW.created_at) IS DISTINCT FROM ROW(OLD.id,OLD.request_key,OLD.book_id,OLD.mode,OLD.input_hash,OLD.original_input,OLD.input_payload,OLD.frozen_plan,OLD.created_at) THEN RAISE EXCEPTION 'creative frozen input is immutable' USING ERRCODE='23514'; END IF;
 IF OLD.run_key IS NOT NULL AND ROW(NEW.run_key,NEW.run_hash,NEW.run_input,NEW.task_id,NEW.step_id,NEW.attempt_id) IS DISTINCT FROM ROW(OLD.run_key,OLD.run_hash,OLD.run_input,OLD.task_id,OLD.step_id,OLD.attempt_id) THEN RAISE EXCEPTION 'creative claim is immutable' USING ERRCODE='23514'; END IF;
 IF OLD.output_payload IS NOT NULL AND ROW(NEW.output_payload,NEW.execution) IS DISTINCT FROM ROW(OLD.output_payload,OLD.execution) THEN RAISE EXCEPTION 'creative reply is immutable' USING ERRCODE='23514'; END IF;
 IF OLD.status IN ('succeeded','failed','blocked') THEN RAISE EXCEPTION 'creative terminal preview is immutable' USING ERRCODE='23514'; END IF;
 IF NEW.status<>OLD.status AND NOT ((OLD.status='ready' AND NEW.status='running') OR (OLD.status='running' AND NEW.status IN ('succeeded','failed'))) THEN RAISE EXCEPTION 'illegal creative transition' USING ERRCODE='23514'; END IF;
 IF NEW.output_payload IS NOT NULL AND NEW.status NOT IN ('running','succeeded') THEN RAISE EXCEPTION 'creative reply requires original live attempt' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $$;


