-- Name: guard_outbox_append_only(); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.guard_outbox_append_only() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $$ BEGIN RAISE EXCEPTION '% is append-only',TG_TABLE_NAME USING ERRCODE='23514'; END $$;


--
-- Name: guard_payoff_window_version(); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.guard_payoff_window_version() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $$
BEGIN
  IF TG_OP <> 'INSERT' THEN
    RAISE EXCEPTION 'payoff window versions are immutable' USING ERRCODE='23514';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM books book
    JOIN cards card ON card.space_id=book.space_id AND card.id=NEW.card_id AND card.status='active'
    JOIN card_types type ON type.id=card.card_type_id AND type.type_key='foreshadow'
    WHERE book.id=NEW.book_id AND book.status='active'
  ) THEN
    RAISE EXCEPTION 'payoff window must target an active foreshadow in its book' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: guard_planning_center_append_only(); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.guard_planning_center_append_only() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $$
BEGIN RAISE EXCEPTION 'planning center history is append-only' USING ERRCODE='23514'; END $$;


--
-- Name: guard_planning_version_immutability(); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.guard_planning_version_immutability() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $$
BEGIN
  IF (to_jsonb(NEW) - ARRAY['status','stale_at','stale_reason']::text[]) IS DISTINCT FROM (to_jsonb(OLD) - ARRAY['status','stale_at','stale_reason']::text[]) THEN
    RAISE EXCEPTION 'planning version content is immutable' USING ERRCODE='23514';
  END IF;
  IF OLD.status='rejected' AND NEW.status<>OLD.status THEN RAISE EXCEPTION 'rejected planning version is final' USING ERRCODE='23514'; END IF;
  RETURN NEW;
END $$;


--
-- Name: guard_production_director_metadata(); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.guard_production_director_metadata() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $$
BEGIN
  IF TG_OP='DELETE' THEN RAISE EXCEPTION 'director execution metadata cannot be deleted' USING ERRCODE='23514'; END IF;
  IF TG_TABLE_NAME='production_director_commands' AND TG_OP='UPDATE' THEN RAISE EXCEPTION 'director command receipt is immutable' USING ERRCODE='23514'; END IF;
  IF TG_TABLE_NAME='production_director_runs' THEN
    IF ROW(NEW.id,NEW.book_id,NEW.request_key,NEW.request_hash,NEW.issue_policy,NEW.instruction,NEW.knowledge_sources,NEW.created_at) IS DISTINCT FROM ROW(OLD.id,OLD.book_id,OLD.request_key,OLD.request_hash,OLD.issue_policy,OLD.instruction,OLD.knowledge_sources,OLD.created_at) THEN RAISE EXCEPTION 'director scope is immutable' USING ERRCODE='23514'; END IF;
  ELSIF TG_TABLE_NAME='production_director_chapters' THEN
    IF (to_jsonb(NEW)-ARRAY['current_request_id','current_request_key','boundary_completed']::text[]) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['current_request_id','current_request_key','boundary_completed']::text[]) THEN RAISE EXCEPTION 'director frozen chapter range is immutable' USING ERRCODE='23514'; END IF;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: guard_professional_resource_receipt(); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.guard_professional_resource_receipt() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $$
DECLARE kind text;
BEGIN
 IF TG_OP <> 'INSERT' THEN RAISE EXCEPTION 'professional command receipts are immutable' USING ERRCODE='23514'; END IF;
 IF NEW.resource_version_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM new_design.card_versions WHERE id=NEW.resource_version_id AND card_id=NEW.resource_card_id) THEN
  RAISE EXCEPTION 'resource version scope mismatch' USING ERRCODE='23514';
 END IF;
 IF NEW.resource_card_id IS NOT NULL THEN
  SELECT t.type_key INTO kind FROM new_design.cards c JOIN new_design.card_types t ON t.id=c.card_type_id
   WHERE c.id=NEW.resource_card_id AND c.space_id='60000000-0000-4000-8000-000000000001';
  IF kind IS NULL OR kind NOT IN ('title_candidate','writing_config','quality_rule','genre_strategy','progression_mode','character') THEN
   RAISE EXCEPTION 'not an original professional resource' USING ERRCODE='23514';
  END IF;
  IF kind='character' THEN
   IF NEW.operation NOT IN ('create','edit','archive','favorite') OR NOT EXISTS(
    SELECT 1 FROM new_design.public_character_profile_capability WHERE contract='public_character_profile_v1' AND operational
   ) THEN RAISE EXCEPTION 'public character profile command is not operational' USING ERRCODE='23514'; END IF;
  END IF;
 END IF;
 IF NEW.receipt->>'requestKey' IS DISTINCT FROM NEW.request_key OR NEW.receipt->>'operation' IS DISTINCT FROM NEW.operation THEN
  RAISE EXCEPTION 'command receipt identity mismatch' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_prompt_primary_classification(); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.guard_prompt_primary_classification() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $$
BEGIN
  IF NEW.is_primary AND NOT EXISTS (
    SELECT 1 FROM new_design.cards card JOIN new_design.card_types type ON type.id=card.card_type_id
    WHERE card.id=NEW.card_id AND card.space_id='63000000-0000-4000-8000-000000000001'
      AND type.type_key='prompt_component'
  ) THEN RAISE EXCEPTION 'primary prompt classification requires the prompt resource space' USING ERRCODE='23514'; END IF;
  RETURN NEW;
END;
$$;


--
-- Name: guard_public_character_manifest(); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.guard_public_character_manifest() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $$ BEGIN IF TG_OP <> 'DELETE' THEN IF NEW.public_title_scope IS NOT NULL THEN RETURN NEW; END IF; ELSE IF OLD.public_title_scope IS NOT NULL THEN RETURN OLD; END IF; END IF;
 IF TG_OP='DELETE' THEN
  IF OLD.public_character_scope IS NOT NULL THEN RAISE EXCEPTION 'public character manifest immutable' USING ERRCODE='23514'; END IF;
  RETURN OLD;
 END IF;
 IF TG_OP='UPDATE' AND (OLD.public_character_scope IS NOT NULL OR NEW.public_character_scope IS NOT NULL) THEN
  IF NEW IS DISTINCT FROM OLD THEN RAISE EXCEPTION 'public character manifest immutable' USING ERRCODE='23514'; END IF;
  RETURN NEW;
 END IF;
 IF NEW.book_id IS NULL AND NOT EXISTS(SELECT 1 FROM public_character_workshop_capability WHERE contract='public_character_trial_v1' AND operational) THEN RAISE EXCEPTION 'public character workshop not enabled' USING ERRCODE='23514'; END IF;
 IF NEW.book_id IS NULL AND NOT EXISTS(
  SELECT 1 FROM cards card JOIN card_types type ON type.id=card.card_type_id
  JOIN task_contract_versions contract ON contract.id=NEW.task_contract_version_id
  JOIN prompt_recipe_versions recipe ON recipe.id=NEW.prompt_recipe_version_id AND recipe.id=contract.prompt_recipe_version_id
  WHERE card.id=NEW.public_character_scope AND card.space_id='60000000-0000-4000-8000-000000000001'
   AND type.type_key='character' AND card.status='active' AND type.status='published'
   AND recipe.variables_schema->'x-public-character'->>'contract'='public_character_trial_v1'
   AND recipe.variables_schema->'x-public-character'->>'resourceId'=card.id::text
   AND recipe.variables_schema->'const'=contract.input_schema->'const'
   AND (contract.task_group IN ('character_dialogue','image_generation') OR (contract.task_group='form_assist' AND recipe.variables_schema->'x-image-preparation'->>'contract'='image_prompt_preparation_v1' AND contract.budget_policy->>'assetId'='new_design.image.prompt_preparation' AND EXISTS(SELECT 1 FROM image_preparation_capability WHERE contract='image_prompt_preparation_v1' AND operational)))
 ) THEN RAISE EXCEPTION 'invalid public character manifest' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_public_character_portrait_event(); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.guard_public_character_portrait_event() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $$ BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'public portrait history immutable' USING ERRCODE='23514'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public_character_workshop_capability WHERE contract='public_character_trial_v1' AND operational) THEN RAISE EXCEPTION 'public character workshop not enabled' USING ERRCODE='23514'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('public-character-source:'||NEW.resource_id::text,0));
 IF NEW.input_payload->>'expectedLatestEventId' IS DISTINCT FROM (SELECT id::text FROM public_character_portrait_events WHERE resource_id=NEW.resource_id ORDER BY sequence DESC LIMIT 1) THEN RAISE EXCEPTION 'public portrait latest event changed' USING ERRCODE='23514'; END IF;
 IF EXISTS(SELECT 1 FROM public_character_portrait_events WHERE trial_id=NEW.trial_id AND operation='archive') THEN RAISE EXCEPTION 'public portrait already archived' USING ERRCODE='23514'; END IF;
 IF NEW.input_payload->>'requestKey' IS DISTINCT FROM NEW.request_key::text OR NEW.input_payload->>'resourceId' IS DISTINCT FROM NEW.resource_id::text OR NEW.input_payload->>'trialId' IS DISTINCT FROM NEW.trial_id::text OR NEW.input_payload->>'operation' IS DISTINCT FROM NEW.operation THEN RAISE EXCEPTION 'public portrait command identity mismatch' USING ERRCODE='23514'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public_character_trials trial JOIN cards card ON card.id=trial.resource_id WHERE trial.id=NEW.trial_id AND trial.resource_id=NEW.resource_id AND trial.status='succeeded' AND trial.input_payload->>'kind'='portrait' AND trial.output->>'contentObjectId' IS NOT NULL AND card.status='active') THEN RAISE EXCEPTION 'public portrait requires original saved image' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_public_character_trial(); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.guard_public_character_trial() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $$ BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'public character original reply cannot be deleted' USING ERRCODE='23514'; END IF;
 IF TG_OP='INSERT' AND NOT EXISTS(SELECT 1 FROM public_character_workshop_capability WHERE contract='public_character_trial_v1' AND operational) THEN RAISE EXCEPTION 'public character workshop not enabled' USING ERRCODE='23514'; END IF;
 IF TG_OP='UPDATE' THEN
  IF (to_jsonb(NEW)-ARRAY['status','request_state','reply','execution','output','summary']::text[]) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['status','request_state','reply','execution','output','summary']::text[]) THEN RAISE EXCEPTION 'public character freeze immutable' USING ERRCODE='23514'; END IF;
  IF OLD.reply IS NOT NULL AND (OLD.reply,OLD.execution) IS DISTINCT FROM (NEW.reply,NEW.execution) THEN RAISE EXCEPTION 'public character received reply immutable' USING ERRCODE='23514'; END IF;
  IF OLD.status<>'running' AND NEW IS DISTINCT FROM OLD THEN RAISE EXCEPTION 'public character terminal request immutable' USING ERRCODE='23514'; END IF;
 END IF;
 IF NOT EXISTS(SELECT 1 FROM cards card JOIN card_types type ON type.id=card.card_type_id JOIN card_versions version ON version.card_id=card.id
  JOIN ai_tasks task ON task.id=NEW.id JOIN ai_task_steps step ON step.task_id=task.id JOIN ai_task_attempts attempt ON attempt.task_id=task.id AND attempt.step_id=step.id
  JOIN card_type_versions spec ON spec.id=version.type_version_id AND spec.card_type_id=type.id
  JOIN task_contract_versions contract ON contract.id=attempt.task_contract_version_id AND contract.id=task.task_contract_version_id
  JOIN prompt_recipe_versions recipe ON recipe.id=attempt.prompt_recipe_version_id AND recipe.id=contract.prompt_recipe_version_id
  JOIN context_manifests manifest ON manifest.id=attempt.context_manifest_id
  JOIN model_route_snapshots route ON route.id=attempt.model_route_snapshot_id
  WHERE card.id=NEW.resource_id AND version.id=NEW.resource_version_id AND type.type_key='character'
   AND card.space_id='60000000-0000-4000-8000-000000000001' AND task.space_id=card.space_id AND task.book_id IS NULL
   AND task.source_kind='public_character_trial' AND task.source_id=NEW.id AND task.request_idempotency_key=NEW.request_key::text AND task.request_hash=NEW.request_hash
   AND step.id=NEW.step_id AND step.max_attempts=1 AND step.current_attempt_id=attempt.id AND attempt.id=NEW.attempt_id AND attempt.attempt_number=1
   AND manifest.book_id IS NULL AND manifest.public_character_scope=card.id AND route.book_id IS NULL
   AND manifest.task_contract_version_id=contract.id AND manifest.prompt_recipe_version_id=recipe.id AND manifest.model_route_snapshot_id=route.id
   AND NEW.frozen_plan->>'contractVersionId'=contract.id::text AND NEW.frozen_plan->>'recipeVersionId'=recipe.id::text
   AND NEW.frozen_plan->>'manifestId'=manifest.id::text AND NEW.frozen_plan->>'inputHash'=attempt.input_hash::text
   AND NEW.frozen_plan->>'outputSchemaVersion'=attempt.output_schema_version AND attempt.output_schema_version=contract.output_schema_version
   AND contract.retry_policy->'maxAttempts'='1'::jsonb AND contract.retry_policy->'automaticRetry'='false'::jsonb
   AND manifest.source_set_hash::text=NEW.source_snapshot->>'hash' AND manifest.manifest_hash::text=NEW.frozen_plan->>'inputHash'
   AND recipe.variables_schema->'const'=NEW.frozen_plan->'promptInput' AND contract.input_schema->'const'=NEW.frozen_plan->'promptInput'
   AND ((NEW.input_payload->>'kind'='dialogue' AND contract.task_group='character_dialogue' AND contract.budget_policy->>'assetId'='new_design.character.public_dialogue' AND contract.budget_policy->>'assetVersion'='v1')
    OR (NEW.input_payload->>'kind'='portrait' AND contract.task_group='image_generation' AND contract.budget_policy->>'assetId'='new_design.character.public_portrait' AND contract.budget_policy->>'assetVersion'='v1'))
   AND NEW.input_payload->>'requestKey'=NEW.request_key::text AND NEW.input_payload->>'resourceId'=card.id::text AND NEW.input_payload->>'resourceVersionId'=version.id::text
   AND NEW.source_snapshot->>'id'=card.id::text AND NEW.source_snapshot->>'versionId'=version.id::text AND NEW.source_snapshot->>'typeVersionId'=version.type_version_id::text
   AND NEW.source_snapshot->>'title'=version.title AND NEW.source_snapshot->>'revision'=version.revision::text
   AND NEW.source_snapshot->'values'=version.values||COALESCE((SELECT jsonb_object_agg(definition.field_key,local.value) FROM card_version_local_values local JOIN field_definitions definition ON definition.id=local.field_definition_id WHERE local.card_version_id=version.id),'{}'::jsonb)
   AND NEW.source_snapshot->'fields'=spec.fields||COALESCE((SELECT jsonb_agg(field.field_schema ORDER BY definition.field_key) FROM card_version_local_values local JOIN field_definitions definition ON definition.id=local.field_definition_id JOIN field_definition_versions field ON field.id=local.field_definition_version_id AND field.field_definition_id=definition.id WHERE local.card_version_id=version.id),'[]'::jsonb)
   AND NEW.source_snapshot->'localFields'=COALESCE((SELECT jsonb_agg(jsonb_build_object('definitionId',definition.id::text,'versionId',field.id::text,'field',field.field_schema,'value',local.value) ORDER BY definition.field_key) FROM card_version_local_values local JOIN field_definitions definition ON definition.id=local.field_definition_id JOIN field_definition_versions field ON field.id=local.field_definition_version_id AND field.field_definition_id=definition.id WHERE local.card_version_id=version.id),'[]'::jsonb)
   AND NEW.input_payload->>'sourceHash'=NEW.source_snapshot->>'hash'
   AND NEW.frozen_plan->'source'=NEW.source_snapshot AND NEW.frozen_plan->'input'=NEW.input_payload
   AND ((NEW.input_payload->>'kind'='dialogue' AND NEW.frozen_plan->'promptInput'->'source'=NEW.source_snapshot AND NEW.frozen_plan->'promptInput'->>'message'=NEW.input_payload->>'message')
    OR (NEW.input_payload->>'kind'='portrait' AND NEW.frozen_plan->'promptInput'->'portraitSource'=NEW.source_snapshot AND NEW.frozen_plan->'promptInput'->>'prompt'=NEW.input_payload->>'prompt' AND NEW.frozen_plan->'promptInput'->>'description'=NEW.input_payload->>'description' AND NEW.frozen_plan->'promptInput'->>'size'=NEW.input_payload->>'size'))
   AND ((NEW.input_payload->>'kind'='dialogue' AND route.managed_task_key='character_dialogue'
     AND NEW.frozen_plan->'route'->'sourceLayers'=route.source_layers AND NEW.frozen_plan->'route'->'primary'->>'provider'=route.provider AND NEW.frozen_plan->'route'->'primary'->>'model'=route.model)
    OR (NEW.input_payload->>'kind'='portrait' AND route.managed_task_key='image_generation'
     AND NEW.input_payload->>'connectionVersionId'=route.source_layers->0->>'versionId'
     AND NEW.frozen_plan->'connection'->>'id'=NEW.input_payload->>'connectionVersionId'
     AND EXISTS(SELECT 1 FROM model_route_versions connection JOIN model_route_configs config ON config.id=connection.config_id WHERE connection.id::text=NEW.input_payload->>'connectionVersionId' AND config.scope='task_group' AND config.task_group='image_generation' AND connection.provider=route.provider AND connection.model=route.model AND connection.content_hash::text=NEW.frozen_plan->'connection'->>'connectionHash')))
   AND NEW.frozen_plan->>'snapshotId'=route.id::text AND NEW.frozen_plan->>'snapshotHash'=route.snapshot_hash::text
 ) THEN RAISE EXCEPTION 'public character exact source and original attempt mismatch' USING ERRCODE='23514'; END IF;
 IF NEW.reply IS NOT NULL AND (NEW.execution IS NULL OR NEW.request_state<>'completed' OR NOT EXISTS(
  SELECT 1 FROM model_route_snapshots route WHERE route.id::text=NEW.frozen_plan->>'snapshotId'
   AND NEW.execution->>'routeSnapshotId'=route.id::text AND NEW.execution->>'routeSnapshotHash'=route.snapshot_hash::text
   AND NEW.execution->>'provider'=route.provider AND NEW.execution->>'model'=route.model
   AND EXISTS(SELECT 1 FROM jsonb_array_elements(CASE WHEN jsonb_typeof(NEW.execution->'attempts')='array' THEN NEW.execution->'attempts' ELSE '[]'::jsonb END) trace WHERE trace->>'status'='succeeded' AND trace->'requestSent'='true'::jsonb AND trace->'responseReceived'='true'::jsonb)
 )) THEN RAISE EXCEPTION 'public character reply requires actual frozen execution' USING ERRCODE='23514'; END IF;
 IF NEW.status='succeeded' AND (NEW.reply IS NULL OR NEW.output IS NULL OR NOT EXISTS(SELECT 1 FROM ai_task_attempts WHERE id=NEW.attempt_id AND status='succeeded')) THEN RAISE EXCEPTION 'public character success requires saved original reply' USING ERRCODE='23514'; END IF;
 IF NEW.status='succeeded' AND NEW.input_payload->>'kind'='dialogue' AND
  (NEW.output IS DISTINCT FROM NEW.reply OR NEW.output->>'resourceId' IS DISTINCT FROM NEW.resource_id::text OR NEW.output->>'resourceVersionId' IS DISTINCT FROM NEW.resource_version_id::text) THEN RAISE EXCEPTION 'public dialogue output source mismatch' USING ERRCODE='23514'; END IF;
 IF NEW.status='succeeded' AND NEW.input_payload->>'kind'='portrait' AND NOT EXISTS(
  SELECT 1 FROM asset_content_objects content WHERE content.id::text=NEW.output->>'contentObjectId' AND content.storage_kind='managed_file' AND content.storage_provider='local' AND content.integrity_state='verified'
   AND content.checksum::text=NEW.output->>'checksum' AND content.byte_size::text=NEW.output->>'byteSize' AND content.mime_type=NEW.output->>'mimeType'
   AND NEW.output->>'checksum'=NEW.reply->>'checksum' AND NEW.output->>'byteSize'=NEW.reply->>'byteSize' AND NEW.output->>'mimeType'=NEW.reply->>'mimeType'
   AND NEW.output->>'title'=NEW.input_payload->>'title' AND NEW.output->>'description'=NEW.input_payload->>'description'
 ) THEN RAISE EXCEPTION 'public portrait output content mismatch' USING ERRCODE='23514'; END IF;
 IF NEW.status='ended_unknown'  AND NEW.reply IS NOT NULL THEN RAISE EXCEPTION 'received reply cannot be ended as unknown' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_public_title_choice(); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.guard_public_title_choice() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $$
DECLARE trial public_title_factory_trials%ROWTYPE; chosen text;
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'original title selection immutable' USING ERRCODE='23514'; END IF;
 SELECT * INTO STRICT trial FROM public_title_factory_trials WHERE id=NEW.trial_id AND status='succeeded';chosen:=trial.output->'groups'->((NEW.input_payload->>'groupIndex')::integer)->'titles'->((NEW.input_payload->>'titleIndex')::integer)->>'title';
 IF NOT COALESCE(NEW.input_payload->>'requestKey'=NEW.request_key::text AND NEW.input_payload->>'trialId'=NEW.trial_id::text AND NEW.input_payload->>'sourceVersionId'=trial.source_version_id::text AND NEW.input_payload->>'sourceHash'=trial.source_hash AND chosen IS NOT NULL AND NEW.receipt->>'title'=chosen AND NEW.receipt->>'requestKey'=NEW.request_key::text AND NEW.receipt->>'inputHash'=NEW.input_hash AND NEW.receipt->'command'=NEW.input_payload,false) THEN RAISE EXCEPTION 'original title choice mismatch' USING ERRCODE='23514'; END IF;
 IF NEW.input_payload->>'action' IN('save_library','archive_library') THEN
  IF NOT EXISTS(SELECT 1 FROM card_versions version JOIN cards card ON card.id=version.card_id JOIN card_types type ON type.id=card.card_type_id WHERE card.id=(NEW.receipt->>'resourceId')::uuid AND version.id=(NEW.receipt->>'versionId')::uuid AND version.card_id=card.id AND version.id=card.current_version_id AND card.space_id='60000000-0000-4000-8000-000000000001' AND type.type_key='public_title_resource' AND version.values->>'source_trial_id'=trial.id::text AND version.values->>'source_version_id'=trial.source_version_id::text AND version.values->>'source_hash'=trial.source_hash AND version.values->>'name'=chosen AND (NEW.input_payload->>'action'='save_library' AND card.status='active' AND version.source='create' OR NEW.input_payload->>'action'='archive_library' AND card.status='archived' AND version.source='archive' AND NEW.input_payload->>'resourceId'=card.id::text AND (NEW.input_payload->>'expectedRevision')::integer+1=card.revision AND NEW.input_payload->>'confirm'='true')) OR NEW.receipt->'bookRevision'<>'null'::jsonb THEN RAISE EXCEPTION 'original title library version mismatch' USING ERRCODE='23514'; END IF;
 ELSIF NEW.input_payload->>'action'='adopt_book_title' THEN
  IF NOT EXISTS(SELECT 1 FROM books WHERE id=(NEW.input_payload->>'bookId')::uuid AND status='active' AND name=chosen AND revision=(NEW.input_payload->>'expectedBookRevision')::integer+1 AND revision=(NEW.receipt->>'bookRevision')::integer AND NEW.input_payload->>'confirm'='true') OR NEW.receipt->'resourceId'<>'null'::jsonb OR NEW.receipt->'versionId'<>'null'::jsonb THEN RAISE EXCEPTION 'original explicit book title adoption mismatch' USING ERRCODE='23514'; END IF;
 ELSE RAISE EXCEPTION 'unknown public title action' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_public_title_manifest(); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.guard_public_title_manifest() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $$
BEGIN
 IF TG_OP='DELETE' THEN IF OLD.public_title_scope IS NOT NULL THEN RAISE EXCEPTION 'public title manifest immutable' USING ERRCODE='23514'; END IF; RETURN OLD; END IF;
 IF TG_OP='UPDATE' AND (OLD.public_title_scope IS NOT NULL OR NEW.public_title_scope IS NOT NULL) THEN IF NEW IS DISTINCT FROM OLD THEN RAISE EXCEPTION 'public title manifest immutable' USING ERRCODE='23514'; END IF; RETURN NEW; END IF;
 IF NEW.public_title_scope IS NULL THEN RETURN NEW; END IF;
 IF NOT EXISTS(SELECT 1 FROM public_title_factory_capability WHERE operational) OR NOT EXISTS(
  SELECT 1 FROM cards card JOIN card_types type ON type.id=card.card_type_id JOIN card_versions source ON source.id=card.current_version_id AND source.card_id=card.id
  JOIN task_contract_versions contract ON contract.id=NEW.task_contract_version_id JOIN prompt_recipe_versions recipe ON recipe.id=NEW.prompt_recipe_version_id AND recipe.id=contract.prompt_recipe_version_id
  WHERE card.id=NEW.public_title_scope AND card.space_id='60000000-0000-4000-8000-000000000001' AND card.status='active' AND type.type_key='public_title_brief' AND type.status='published'
  AND contract.status='published' AND recipe.status='published' AND contract.task_group='creative_extraction' AND contract.budget_policy->>'assetId'='new_design.public.title_factory' AND contract.budget_policy->>'assetVersion'='v1'
  AND contract.input_schema->'const'=recipe.variables_schema->'const' AND contract.input_schema->'const'->>'contract'='public_title_factory_v1'
  AND contract.input_schema->'const'->'source'->>'id'=card.id::text AND contract.input_schema->'const'->'source'->>'versionId'=source.id::text AND contract.input_schema->'const'->'source'->'values'=source.values
  AND NEW.source_set_hash=contract.input_schema->'const'->'source'->>'hash'
 ) THEN RAISE EXCEPTION 'public title requires original public source and independent exact contract' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_public_title_trial(); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.guard_public_title_trial() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $$
DECLARE task ai_tasks%ROWTYPE;step ai_task_steps%ROWTYPE;attempt ai_task_attempts%ROWTYPE;contract task_contract_versions%ROWTYPE;manifest context_manifests%ROWTYPE;
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'original public title trial immutable' USING ERRCODE='23514'; END IF;
 IF TG_OP='INSERT' THEN IF NEW.status<>'running' OR NEW.reply IS NOT NULL OR NEW.output IS NOT NULL OR NOT EXISTS(SELECT 1 FROM public_title_factory_capability WHERE operational) THEN RAISE EXCEPTION 'public title not enabled' USING ERRCODE='23514'; END IF;
 ELSE
  IF (to_jsonb(NEW)-ARRAY['status','reply','output','summary']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['status','reply','output','summary']) OR OLD.status<>'running' OR OLD.reply IS NOT NULL AND NEW.reply IS DISTINCT FROM OLD.reply THEN RAISE EXCEPTION 'original title input/reply immutable' USING ERRCODE='23514'; END IF;
 END IF;
 SELECT * INTO STRICT task FROM ai_tasks WHERE id=NEW.id;SELECT * INTO STRICT step FROM ai_task_steps WHERE id=NEW.step_id AND task_id=NEW.id;SELECT * INTO STRICT attempt FROM ai_task_attempts WHERE id=NEW.attempt_id AND step_id=NEW.step_id AND task_id=NEW.id;
 SELECT * INTO STRICT contract FROM task_contract_versions WHERE id=task.task_contract_version_id;SELECT * INTO STRICT manifest FROM context_manifests WHERE id=attempt.context_manifest_id;
 IF NOT COALESCE(task.book_id IS NULL AND task.space_id='60000000-0000-4000-8000-000000000001' AND task.source_kind='public_title_factory' AND task.source_id=NEW.id AND task.request_hash=NEW.request_hash AND task.request_idempotency_key=NEW.request_key::text AND contract.task_group='creative_extraction' AND contract.budget_policy->>'assetId'='new_design.public.title_factory' AND contract.budget_policy->>'assetVersion'='v1' AND contract.retry_policy='{"maxAttempts":1,"automaticRetry":false}'::jsonb AND contract.input_schema->'const'=NEW.frozen_plan->'promptInput' AND contract.input_schema->'const'->'input'=NEW.input_payload AND contract.input_schema->'const'->'source'=NEW.source_snapshot AND NEW.source_snapshot->>'id'=NEW.source_id::text AND NEW.source_snapshot->>'versionId'=NEW.source_version_id::text AND NEW.source_snapshot->>'hash'=NEW.source_hash AND manifest.book_id IS NULL AND manifest.public_title_scope=NEW.source_id AND manifest.task_contract_version_id=contract.id AND step.max_attempts=1 AND attempt.attempt_number=1 AND attempt.input_hash=NEW.frozen_plan->>'inputHash' AND attempt.output_schema_version=NEW.frozen_plan->>'outputSchemaVersion' AND attempt.model_route_snapshot_id=(NEW.frozen_plan->>'snapshotId')::uuid,false) THEN RAISE EXCEPTION 'original title frozen execution mismatch' USING ERRCODE='23514'; END IF;
 IF NOT EXISTS(SELECT 1 FROM card_versions version JOIN cards card ON card.id=version.card_id JOIN card_types type ON type.id=card.card_type_id WHERE version.id=NEW.source_version_id AND card.id=NEW.source_id AND card.space_id=task.space_id AND type.type_key='public_title_brief' AND version.values=NEW.source_snapshot->'values') OR NOT EXISTS(SELECT 1 FROM context_manifest_entries entry WHERE entry.manifest_id=manifest.id AND entry.source_type='card_version' AND entry.stable_object_id=NEW.source_id AND entry.exact_version_id=NEW.source_version_id AND entry.transform_status='full') THEN RAISE EXCEPTION 'original title source version unavailable' USING ERRCODE='23514'; END IF;
 IF NEW.reply IS NOT NULL AND NOT COALESCE(NEW.reply->'output'->>'sourceId'=NEW.source_id::text AND NEW.reply->'output'->>'sourceVersionId'=NEW.source_version_id::text AND NEW.reply->'output'->>'sourceHash'=NEW.source_hash AND NEW.reply->'execution'->>'routeSnapshotId'=NEW.frozen_plan->>'snapshotId' AND NEW.reply->'execution'->>'routeSnapshotHash'=NEW.frozen_plan->>'snapshotHash' AND jsonb_array_length(NEW.reply->'output'->'groups')=(NEW.input_payload->>'groupCount')::integer AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(NEW.reply->'output'->'groups') item WHERE jsonb_array_length(item->'titles')<>(NEW.input_payload->>'candidatesPerGroup')::integer) AND EXISTS(SELECT 1 FROM jsonb_array_elements(NEW.reply->'execution'->'attempts') trace WHERE trace->>'status'='succeeded' AND trace->>'requestSent'='true' AND trace->>'responseReceived'='true'),false) THEN RAISE EXCEPTION 'original title reply execution mismatch' USING ERRCODE='23514'; END IF;
 IF NEW.status='succeeded' AND (NEW.reply IS NULL OR NEW.output IS DISTINCT FROM NEW.reply->'output' OR task.status<>'succeeded' OR step.status<>'succeeded' OR attempt.status<>'succeeded') THEN RAISE EXCEPTION 'original successful title requires original reply and ledger' USING ERRCODE='23514'; END IF;
 IF NEW.status IN('failed','ended_unknown') AND (NEW.output IS NOT NULL OR task.status<>CASE WHEN NEW.status='failed' THEN 'failed' ELSE 'cancelled' END OR attempt.status<>CASE WHEN NEW.status='failed' THEN 'failed' ELSE 'discarded' END) THEN RAISE EXCEPTION 'original title failure ledger mismatch' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $$;


