  IF NEW.revision<>OLD.revision+1 OR NEW.status<>'resolved' OR NEW.resolution IS NULL OR NEW.resolved_at IS NULL THEN RAISE EXCEPTION 'invalid transfer conflict resolution' USING ERRCODE='23514'; END IF;
  RETURN NEW;
END $$;


--
-- Name: guard_transfer_operation_update(); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.guard_transfer_operation_update() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $$
BEGIN
  IF TG_OP='DELETE' THEN RAISE EXCEPTION 'transfer operation history cannot be deleted' USING ERRCODE='23514'; END IF;
  IF (to_jsonb(NEW)-ARRAY['status','current_step_key','progress_completed','progress_total','ready_manifest_id','revision','last_error_code','last_error_summary','started_at','completed_at','archived_at']::text[]) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['status','current_step_key','progress_completed','progress_total','ready_manifest_id','revision','last_error_code','last_error_summary','started_at','completed_at','archived_at']::text[]) THEN RAISE EXCEPTION 'transfer operation frozen input is immutable' USING ERRCODE='23514'; END IF;
  IF NEW.revision<>OLD.revision+1 THEN RAISE EXCEPTION 'transfer operation revision must advance by one' USING ERRCODE='23514'; END IF;
  IF OLD.ready_manifest_id IS NOT NULL AND NEW.ready_manifest_id IS DISTINCT FROM OLD.ready_manifest_id THEN RAISE EXCEPTION 'ready transfer manifest cannot be replaced' USING ERRCODE='23514'; END IF;
  IF NOT ((OLD.status='queued' AND NEW.status IN ('running','failed','cancelled')) OR (OLD.status='running' AND NEW.status IN ('running','verifying','failed','cancelled')) OR (OLD.status='verifying' AND NEW.status IN ('verifying','ready','failed','cancelled','imported','restored')) OR (OLD.status IN ('ready','failed','cancelled','imported','restored') AND NEW.status='archived')) THEN RAISE EXCEPTION 'illegal transfer operation transition' USING ERRCODE='23514'; END IF;
  IF NEW.status='ready' AND NOT ((NEW.execution_mode='execute' AND NEW.operation_kind IN ('full_backup','book_export','template_export','resource_export')) OR NEW.execution_mode='dry_run') THEN RAISE EXCEPTION 'only export, backup, or dry-run operations can become ready' USING ERRCODE='23514'; END IF;
  IF NEW.status='imported' AND NOT (NEW.execution_mode='apply' AND NEW.operation_kind IN ('book_import','template_import','resource_import')) THEN RAISE EXCEPTION 'only apply import can become imported' USING ERRCODE='23514'; END IF;
  IF NEW.status='restored' AND NOT (NEW.operation_kind='full_restore' AND NEW.execution_mode='apply') THEN RAISE EXCEPTION 'only apply full restore can become restored' USING ERRCODE='23514'; END IF;
  IF NEW.status IN ('ready','imported','restored') AND (NEW.ready_manifest_id IS NULL OR EXISTS(SELECT 1 FROM transfer_validation_results WHERE operation_id=NEW.id AND outcome IN ('failed','unavailable'))) THEN RAISE EXCEPTION 'transfer operation cannot pass a failed validation gate' USING ERRCODE='23514'; END IF;
  IF NEW.status IN ('ready','imported','restored') AND NOT EXISTS(SELECT 1 FROM transfer_compatibility_snapshots WHERE operation_id=NEW.id AND outcome IN ('compatible','upgrade_required') AND jsonb_array_length(unknown_required_capabilities)=0) THEN RAISE EXCEPTION 'transfer operation requires a fail-closed compatibility snapshot' USING ERRCODE='23514'; END IF;
  IF NEW.status='ready' AND NEW.execution_mode='execute' AND NOT EXISTS(SELECT 1 FROM transfer_artifacts WHERE operation_id=NEW.id AND manifest_id=NEW.ready_manifest_id AND artifact_kind='package' AND status='ready') THEN RAISE EXCEPTION 'export or backup requires a verified package artifact' USING ERRCODE='23514'; END IF;
  IF NEW.status IN ('imported','restored') AND NOT EXISTS(SELECT 1 FROM transfer_import_sources WHERE operation_id=NEW.id) THEN RAISE EXCEPTION 'import or restore requires frozen source evidence' USING ERRCODE='23514'; END IF;
  IF NEW.status IN ('failed','cancelled') AND (NEW.last_error_code='' OR NEW.last_error_summary='') THEN RAISE EXCEPTION 'failed or cancelled transfer requires sanitized error detail' USING ERRCODE='23514'; END IF;
  RETURN NEW;
END $$;


--
-- Name: guard_transfer_staging_update(); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.guard_transfer_staging_update() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $$
BEGIN
  IF TG_OP='DELETE' OR OLD.status IN ('published','abandoned') THEN RAISE EXCEPTION 'terminal transfer staging scope is immutable' USING ERRCODE='23514'; END IF;
  IF (to_jsonb(NEW)-ARRAY['status','target_space_id','target_book_id','revision','published_at','abandoned_at']::text[]) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['status','target_space_id','target_book_id','revision','published_at','abandoned_at']::text[]) THEN RAISE EXCEPTION 'transfer staging identity is immutable' USING ERRCODE='23514'; END IF;
  IF NEW.revision<>OLD.revision+1 OR NOT ((OLD.status='allocated' AND NEW.status IN ('validating','abandoned')) OR (OLD.status='validating' AND NEW.status IN ('ready_to_publish','abandoned')) OR (OLD.status='ready_to_publish' AND NEW.status IN ('published','abandoned'))) THEN RAISE EXCEPTION 'illegal transfer staging transition' USING ERRCODE='23514'; END IF;
  RETURN NEW;
END $$;


--
-- Name: guard_transfer_step_update(); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.guard_transfer_step_update() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $$
BEGIN
  IF TG_OP='DELETE' OR OLD.status IN ('succeeded','failed','cancelled','skipped') THEN RAISE EXCEPTION 'finished transfer step is immutable' USING ERRCODE='23514'; END IF;
  IF (to_jsonb(NEW)-ARRAY['status','progress_completed','progress_total','checkpoint_key','error_code','error_summary','revision','started_at','completed_at']::text[]) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['status','progress_completed','progress_total','checkpoint_key','error_code','error_summary','revision','started_at','completed_at']::text[]) THEN RAISE EXCEPTION 'transfer step identity is immutable' USING ERRCODE='23514'; END IF;
  IF NEW.revision<>OLD.revision+1 THEN RAISE EXCEPTION 'transfer step revision must advance by one' USING ERRCODE='23514'; END IF;
  IF NOT ((OLD.status='queued' AND NEW.status IN ('running','skipped','cancelled')) OR (OLD.status='running' AND NEW.status IN ('running','succeeded','failed','cancelled'))) THEN RAISE EXCEPTION 'illegal transfer step transition' USING ERRCODE='23514'; END IF;
  IF NEW.status='failed' AND (NEW.error_code='' OR NEW.error_summary='') THEN RAISE EXCEPTION 'failed transfer step requires sanitized error detail' USING ERRCODE='23514'; END IF;
  RETURN NEW;
END $$;


--
-- Name: guard_visual_active_mount(); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.guard_visual_active_mount() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $$
DECLARE source_asset assets%ROWTYPE;
BEGIN
 IF NEW.status<>'active' THEN RETURN NEW; END IF;
 SELECT * INTO source_asset FROM assets WHERE id=NEW.asset_id AND book_id=NEW.book_id;
 IF NOT FOUND OR source_asset.asset_kind NOT IN ('cover','illustration') THEN RETURN NEW; END IF;
 PERFORM id FROM books WHERE id=NEW.book_id AND status='active' FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'visual binding book is not active' USING ERRCODE='23514'; END IF;
 SELECT * INTO source_asset FROM assets WHERE id=NEW.asset_id AND book_id=NEW.book_id FOR SHARE;
 IF NOT FOUND THEN RETURN NEW; END IF; -- The original scope guard retains its failure.
 IF source_asset.asset_kind IN ('cover','illustration') AND source_asset.status<>'active' THEN
  RAISE EXCEPTION 'archived visual asset does not accept new active bindings' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_world_added_card_ref(); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.guard_world_added_card_ref() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $$
DECLARE command world_package_sync_commands;
BEGIN
 SELECT * INTO command FROM world_package_sync_commands WHERE id=NEW.command_id;
 IF command.operation IS DISTINCT FROM 'pull' OR command.installation_id IS DISTINCT FROM NEW.installation_id OR command.input->>'packageId' IS DISTINCT FROM NEW.package_id::text
 OR EXISTS(SELECT 1 FROM world_package_install_card_refs WHERE installation_id=NEW.installation_id AND (source_card_id=NEW.source_card_id OR target_card_id=NEW.target_card_id))
 OR NOT EXISTS(SELECT 1 FROM world_package_card_refs source JOIN books book ON book.id=command.book_id JOIN cards target ON target.id=NEW.target_card_id AND target.space_id=book.space_id
  JOIN card_versions version ON version.card_id=target.id AND version.id=(NEW.snapshot->>'targetVersionId')::uuid
  JOIN jsonb_array_elements(command.input->'newCards') AS selected(item) ON selected.item->>'sourceCardId'=NEW.source_card_id::text
  WHERE source.package_id=NEW.package_id AND source.source_card_id=NEW.source_card_id AND source.source_version_id::text=NEW.snapshot->>'sourceVersionId'
   AND version.author_book_id=command.book_id AND version.author_request_key=(selected.item->>'requestKey')::uuid AND target.card_type_id=(selected.item->>'targetTypeId')::uuid
   AND NEW.snapshot->>'sourceCardId'=NEW.source_card_id::text AND NEW.snapshot->>'targetCardId'=NEW.target_card_id::text AND NEW.snapshot->>'targetTypeVersionId'=version.type_version_id::text
   AND NEW.snapshot->'mapping'=selected.item->'mapping' AND EXISTS(SELECT 1 FROM jsonb_array_elements(command.receipt->'addedCards') AS receipt(item) WHERE receipt.item=NEW.snapshot))
 THEN RAISE EXCEPTION 'added world object must prove selected independent normal save' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_world_consistency_request(); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.guard_world_consistency_request() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $$ BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'world consistency evidence cannot be deleted' USING ERRCODE='23514'; END IF;
 IF TG_OP='UPDATE' THEN
  IF (OLD.book_id,OLD.request_key,OLD.request_hash,OLD.input_hash,OLD.input_payload,OLD.frozen_plan,OLD.ai_task_id,OLD.step_id,OLD.attempt_id) IS DISTINCT FROM (NEW.book_id,NEW.request_key,NEW.request_hash,NEW.input_hash,NEW.input_payload,NEW.frozen_plan,NEW.ai_task_id,NEW.step_id,NEW.attempt_id) THEN RAISE EXCEPTION 'world consistency freeze is immutable' USING ERRCODE='23514'; END IF;
  IF OLD.generated_output IS NOT NULL AND (OLD.generated_output,OLD.generated_execution) IS DISTINCT FROM (NEW.generated_output,NEW.generated_execution) THEN RAISE EXCEPTION 'world consistency original reply is immutable' USING ERRCODE='23514'; END IF;
  IF OLD.status<>'running' AND (OLD.status,OLD.report_id) IS DISTINCT FROM (NEW.status,NEW.report_id) THEN RAISE EXCEPTION 'terminal world check cannot be revived' USING ERRCODE='23514'; END IF;
 END IF;
 IF NOT EXISTS(SELECT 1 FROM ai_tasks task JOIN ai_task_steps step ON step.task_id=task.id JOIN ai_task_attempts attempt ON attempt.task_id=task.id AND attempt.step_id=step.id WHERE task.id=NEW.ai_task_id AND task.book_id=NEW.book_id AND task.source_kind='world_consistency' AND task.source_id=NEW.id AND step.id=NEW.step_id AND attempt.id=NEW.attempt_id AND attempt.input_hash=NEW.input_hash AND attempt.attempt_number=1 AND step.max_attempts=1) THEN RAISE EXCEPTION 'world check task attempt provenance mismatch' USING ERRCODE='23514'; END IF;
 IF NEW.status='succeeded' AND NEW.report_id IS NULL THEN RAISE EXCEPTION 'world check success requires original quality report' USING ERRCODE='23514'; END IF;
 IF NEW.report_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM quality_audit_reports report WHERE report.id=NEW.report_id AND report.book_id=NEW.book_id AND report.task_id=NEW.ai_task_id AND report.step_id=NEW.step_id AND report.attempt_id=NEW.attempt_id AND report.input_hash=NEW.input_hash AND report.rule_set_key='world_consistency' AND report.rule_set_version='v1') THEN RAISE EXCEPTION 'world report does not match original request' USING ERRCODE='23514'; END IF;
 IF NEW.generated_output IS NOT NULL AND (jsonb_typeof(NEW.generated_output)<>'object' OR NEW.generated_execution IS NULL OR jsonb_typeof(NEW.generated_execution)<>'object' OR NEW.model_request_state<>'completed' OR NEW.generated_execution->>'routeSnapshotId' IS DISTINCT FROM NEW.frozen_plan->>'snapshotId' OR NEW.generated_execution->>'routeSnapshotHash' IS DISTINCT FROM NEW.frozen_plan->>'snapshotHash' OR NEW.generated_execution->>'provider' IS DISTINCT FROM NEW.frozen_plan->'route'->'primary'->>'provider' OR NEW.generated_execution->>'model' IS DISTINCT FROM NEW.frozen_plan->'route'->'primary'->>'model' OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(COALESCE(NEW.generated_execution->'attempts','[]'::jsonb)) attempt WHERE attempt->>'status'='succeeded' AND attempt->>'responseReceived'='true' AND attempt->>'requestSent'='true')) THEN RAISE EXCEPTION 'world reply requires original received execution proof' USING ERRCODE='23514'; END IF;
 IF NEW.status='ended_unknown' AND NEW.generated_output IS NOT NULL THEN RAISE EXCEPTION 'saved world reply cannot become unknown' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $$;


