--
-- Name: guard_world_library_command(); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.guard_world_library_command() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM world_package_capability WHERE operational) OR NOT EXISTS(SELECT 1 FROM books WHERE id=NEW.book_id AND status='active')
 OR NEW.input->>'requestKey' IS DISTINCT FROM NEW.request_key::text OR NEW.receipt->>'id' IS DISTINCT FROM NEW.id::text
 OR NEW.receipt->>'bookId' IS DISTINCT FROM NEW.book_id::text OR NEW.receipt->>'requestKey' IS DISTINCT FROM NEW.request_key::text
 OR NEW.receipt->>'operation' IS DISTINCT FROM NEW.operation OR NEW.receipt->>'inputHash' IS DISTINCT FROM NEW.input_hash
 OR NEW.receipt->'input' IS DISTINCT FROM NEW.input
 THEN RAISE EXCEPTION 'world library original command mismatch' USING ERRCODE='23514'; END IF;
 IF NEW.operation='publish' AND NOT EXISTS(SELECT 1 FROM world_library_candidates candidate JOIN world_package_versions package ON package.id=(NEW.receipt->'package'->>'id')::uuid WHERE candidate.id=(NEW.input->>'candidateId')::uuid AND candidate.book_id=NEW.book_id AND package.request_key=(NEW.input->>'publicRequestKey')::uuid AND package.receipt->'package'=NEW.receipt->'package')
 THEN RAISE EXCEPTION 'world library public result mismatch' USING ERRCODE='23514'; END IF;RETURN NEW;
END $$;


--
-- Name: guard_world_package_catalog_action(); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.guard_world_package_catalog_action() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $$
DECLARE previous_revision integer;
BEGIN
 IF NOT EXISTS(SELECT 1 FROM world_package_capability WHERE contract='public_world_package_v1' AND operational)
 OR NOT EXISTS(SELECT 1 FROM world_package_versions WHERE root_card_id=NEW.root_card_id)
 THEN RAISE EXCEPTION 'public world must be operational and published before catalog action' USING ERRCODE='23514'; END IF;
 SELECT coalesce(max(revision),0) INTO previous_revision FROM world_package_catalog_actions WHERE root_card_id=NEW.root_card_id;
 IF NEW.expected_revision<>previous_revision OR NEW.revision<>previous_revision+1
 OR (previous_revision=0 AND NEW.action<>'archive')
 OR (previous_revision>0 AND EXISTS(SELECT 1 FROM world_package_catalog_actions WHERE root_card_id=NEW.root_card_id AND revision=previous_revision AND action=NEW.action))
 OR NEW.receipt->>'rootCardId' IS DISTINCT FROM NEW.root_card_id::text
 OR NEW.receipt->>'requestKey' IS DISTINCT FROM NEW.request_key::text
 OR (NEW.action='archive' AND NEW.receipt->>'status' IS DISTINCT FROM 'archived')
 OR (NEW.action='restore' AND NEW.receipt->>'status' IS DISTINCT FROM 'active')
 OR NEW.receipt->>'revision' IS DISTINCT FROM NEW.revision::text
 OR NEW.receipt->'repeated' IS DISTINCT FROM 'false'::jsonb
 THEN RAISE EXCEPTION 'public world catalog action is stale or incomplete' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END; $$;


