    WHERE origin.session_id=NEW.id AND origin.base_checkpoint_id=NEW.supplement_base_checkpoint_id AND origin.book_id=NEW.book_id) THEN
    RAISE EXCEPTION 'supplement session requires an atomic full original receipt' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: reserve_outbox_aggregate_sequence(uuid, uuid, text, uuid); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.reserve_outbox_aggregate_sequence(requested_space_id uuid, requested_book_id uuid, requested_kind text, requested_id uuid) RETURNS bigint
    LANGUAGE plpgsql
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $$
DECLARE sequence_value bigint;
BEGIN
  INSERT INTO outbox_aggregate_sequences(space_id,book_id,aggregate_kind,aggregate_id,last_sequence) VALUES(requested_space_id,requested_book_id,requested_kind,requested_id,1)
  ON CONFLICT(aggregate_kind,aggregate_id) DO UPDATE SET last_sequence=outbox_aggregate_sequences.last_sequence+1,updated_at=now()
  RETURNING last_sequence INTO sequence_value;
  RETURN sequence_value;
END $$;


--
-- Name: resolve_dependency_resource(text, uuid, uuid); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.resolve_dependency_resource(requested_kind text, requested_stable_id uuid, requested_version_id uuid) RETURNS TABLE(resolved_space_id uuid, resolved_book_id uuid, resolved_hash character)
    LANGUAGE plpgsql STABLE
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $$
BEGIN
 IF requested_kind='context_manifest' AND EXISTS(SELECT 1 FROM context_manifests WHERE id=requested_stable_id AND id=requested_version_id AND book_id IS NULL AND public_title_scope IS NOT NULL) THEN
  RETURN QUERY SELECT card.space_id,NULL::uuid,manifest.manifest_hash FROM context_manifests manifest JOIN cards card ON card.id=manifest.public_title_scope WHERE manifest.id=requested_stable_id AND manifest.id=requested_version_id;
 ELSE RETURN QUERY SELECT * FROM resolve_dependency_resource_pre103(requested_kind,requested_stable_id,requested_version_id); END IF;
END $$;


--
-- Name: resolve_dependency_resource_pre029(text, uuid, uuid); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.resolve_dependency_resource_pre029(requested_kind text, requested_stable_id uuid, requested_version_id uuid) RETURNS TABLE(resolved_space_id uuid, resolved_book_id uuid, resolved_hash character)
    LANGUAGE plpgsql STABLE
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $$
BEGIN
  CASE requested_kind
    WHEN 'card_type_version' THEN
      RETURN QUERY SELECT type.space_id,book.id,dependency_content_hash(version.fields::text)
      FROM card_type_versions version JOIN card_types type ON type.id=version.card_type_id
      LEFT JOIN books book ON book.space_id=type.space_id
      WHERE type.id=requested_stable_id AND version.id=requested_version_id;
    WHEN 'template_group_version' THEN
      RETURN QUERY SELECT NULL::uuid,NULL::uuid,dependency_content_hash(version.payload::text)
      FROM template_group_versions version WHERE version.template_id=requested_stable_id AND version.id=requested_version_id;
    WHEN 'card_version' THEN
      RETURN QUERY SELECT card.space_id,book.id,dependency_content_hash(version.title || version.values::text || version.type_version_id::text)
      FROM card_versions version JOIN cards card ON card.id=version.card_id LEFT JOIN books book ON book.space_id=card.space_id
      WHERE card.id=requested_stable_id AND version.id=requested_version_id;
    WHEN 'card_relation' THEN
      RETURN QUERY SELECT relation.space_id,book.id,dependency_content_hash(to_jsonb(relation)::text)
      FROM card_relations relation LEFT JOIN books book ON book.space_id=relation.space_id
      WHERE relation.id=requested_stable_id AND relation.id=requested_version_id;
    WHEN 'research_document_version' THEN
      RETURN QUERY SELECT NULL::uuid,NULL::uuid,version.content_hash::char(64)
      FROM research_document_versions version WHERE version.document_id=requested_stable_id AND version.id=requested_version_id;
    WHEN 'research_record_version' THEN
      RETURN QUERY SELECT NULL::uuid,NULL::uuid,version.run_hash::char(64)
      FROM research_record_versions version WHERE version.record_id=requested_stable_id AND version.id=requested_version_id;
    WHEN 'research_reference_pack_version' THEN
      RETURN QUERY SELECT NULL::uuid,NULL::uuid,dependency_content_hash(version.id::text || version.note)
      FROM research_reference_pack_versions version WHERE version.pack_id=requested_stable_id AND version.id=requested_version_id;
    WHEN 'chapter_body_version' THEN
      RETURN QUERY SELECT book.space_id,document.book_id,version.content_hash
      FROM chapter_body_versions version JOIN chapter_documents document ON document.id=version.chapter_document_id JOIN books book ON book.id=document.book_id
      WHERE document.id=requested_stable_id AND version.id=requested_version_id;
    WHEN 'chapter_text_anchor' THEN
      RETURN QUERY SELECT book.space_id,anchor.book_id,anchor.fragment_hash
      FROM chapter_text_anchors anchor JOIN books book ON book.id=anchor.book_id
      WHERE anchor.id=requested_stable_id AND anchor.body_version_id=requested_version_id;
    WHEN 'canonical_fact' THEN
      RETURN QUERY SELECT book.space_id,fact.book_id,fact.value_hash
      FROM canonical_facts fact JOIN books book ON book.id=fact.book_id
      WHERE fact.id=requested_stable_id AND fact.id=requested_version_id;
    WHEN 'chapter_settlement' THEN
      RETURN QUERY SELECT book.space_id,settlement.book_id,dependency_content_hash(to_jsonb(settlement)::text)
      FROM chapter_settlements settlement JOIN books book ON book.id=settlement.book_id
      WHERE settlement.chapter_document_id=requested_stable_id AND settlement.id=requested_version_id;
    WHEN 'state_change' THEN
      RETURN QUERY SELECT book.space_id,change.book_id,dependency_content_hash(to_jsonb(change)::text)
      FROM state_changes change JOIN books book ON book.id=change.book_id
      WHERE change.id=requested_stable_id AND change.id=requested_version_id;
    WHEN 'knowledge_state_change' THEN
      RETURN QUERY SELECT book.space_id,change.book_id,dependency_content_hash(to_jsonb(change)::text)
      FROM knowledge_state_changes change JOIN books book ON book.id=change.book_id
      WHERE change.proposal_id=requested_stable_id AND change.id=requested_version_id;
    WHEN 'story_event_timing' THEN
      RETURN QUERY SELECT book.space_id,timing.book_id,dependency_content_hash(to_jsonb(timing)::text)
      FROM story_event_timings timing JOIN books book ON book.id=timing.book_id
      WHERE timing.id=requested_stable_id AND timing.id=requested_version_id;
    WHEN 'story_event_relation' THEN
      RETURN QUERY SELECT book.space_id,relation.book_id,dependency_content_hash(to_jsonb(relation)::text)
      FROM story_event_relations relation JOIN books book ON book.id=relation.book_id
      WHERE relation.proposal_id=requested_stable_id AND relation.id=requested_version_id;
    WHEN 'planning_version' THEN
      RETURN QUERY SELECT book.space_id,version.book_id,version.content_hash
      FROM planning_versions version JOIN books book ON book.id=version.book_id
      WHERE version.object_id=requested_stable_id AND version.id=requested_version_id;
    WHEN 'prompt_recipe_version' THEN
      RETURN QUERY SELECT NULL::uuid,NULL::uuid,version.content_hash
      FROM prompt_recipe_versions version WHERE version.recipe_id=requested_stable_id AND version.id=requested_version_id;
    WHEN 'task_contract_version' THEN
      RETURN QUERY SELECT NULL::uuid,NULL::uuid,version.content_hash
      FROM task_contract_versions version WHERE version.contract_id=requested_stable_id AND version.id=requested_version_id;
    WHEN 'context_manifest' THEN
      RETURN QUERY SELECT book.space_id,manifest.book_id,manifest.manifest_hash
      FROM context_manifests manifest JOIN books book ON book.id=manifest.book_id
      WHERE manifest.id=requested_stable_id AND manifest.id=requested_version_id;
    WHEN 'model_route_snapshot' THEN
      RETURN QUERY SELECT book.space_id,snapshot.book_id,snapshot.snapshot_hash
      FROM model_route_snapshots snapshot JOIN books book ON book.id=snapshot.book_id
      WHERE snapshot.id=requested_stable_id AND snapshot.id=requested_version_id;
    WHEN 'ai_task_attempt' THEN
      RETURN QUERY SELECT task.space_id,task.book_id,COALESCE(attempt.result_hash,attempt.input_hash)
      FROM ai_task_attempts attempt JOIN ai_tasks task ON task.id=attempt.task_id
      WHERE attempt.task_id=requested_stable_id AND attempt.id=requested_version_id;
    WHEN 'quality_audit_report' THEN
      RETURN QUERY SELECT book.space_id,report.book_id,dependency_content_hash(report.input_hash || report.id::text)
      FROM quality_audit_reports report JOIN books book ON book.id=report.book_id
      WHERE report.id=requested_stable_id AND report.id=requested_version_id;
    ELSE
      RAISE EXCEPTION 'unsupported dependency resource kind: %',requested_kind USING ERRCODE='23514';
  END CASE;
END $$;


--
-- Name: resolve_dependency_resource_pre035(text, uuid, uuid); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.resolve_dependency_resource_pre035(requested_kind text, requested_stable_id uuid, requested_version_id uuid) RETURNS TABLE(resolved_space_id uuid, resolved_book_id uuid, resolved_hash character)
    LANGUAGE plpgsql STABLE
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $$
BEGIN
  CASE requested_kind
    WHEN 'embedding_source_snapshot' THEN RETURN QUERY SELECT snapshot.space_id,snapshot.book_id,snapshot.source_hash FROM embedding_source_snapshots snapshot WHERE snapshot.id=requested_stable_id AND snapshot.id=requested_version_id;
    WHEN 'embedding_chunk' THEN RETURN QUERY SELECT snapshot.space_id,chunk.book_id,chunk.content_hash FROM embedding_chunks chunk JOIN embedding_source_snapshots snapshot ON snapshot.id=chunk.source_snapshot_id WHERE chunk.id=requested_stable_id AND chunk.id=requested_version_id;
    WHEN 'embedding_result' THEN RETURN QUERY SELECT snapshot.space_id,request.book_id,result.vector_hash FROM embedding_results result JOIN embedding_requests request ON request.id=result.request_id JOIN embedding_chunks chunk ON chunk.id=result.chunk_id JOIN embedding_source_snapshots snapshot ON snapshot.id=chunk.source_snapshot_id WHERE result.id=requested_stable_id AND result.id=requested_version_id AND result.outcome='applied';
    WHEN 'embedding_index_generation' THEN RETURN QUERY SELECT book.space_id,generation.book_id,generation.checksum FROM embedding_index_generations generation JOIN books book ON book.id=generation.book_id WHERE generation.id=requested_stable_id AND generation.id=requested_version_id AND generation.checksum IS NOT NULL;
    ELSE RETURN QUERY SELECT * FROM resolve_dependency_resource_pre029(requested_kind,requested_stable_id,requested_version_id);
  END CASE;
END $$;


--
-- Name: resolve_dependency_resource_pre036(text, uuid, uuid); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.resolve_dependency_resource_pre036(requested_kind text, requested_stable_id uuid, requested_version_id uuid) RETURNS TABLE(resolved_space_id uuid, resolved_book_id uuid, resolved_hash character)
    LANGUAGE plpgsql STABLE
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $$
BEGIN
  IF requested_kind='card_mount' THEN
    RETURN QUERY SELECT instance.space_id,book.id,dependency_content_hash(to_jsonb(version)::text)
    FROM card_mount_versions version JOIN card_mounts mount ON mount.id=version.card_mount_id
    JOIN card_group_form_instances instance ON instance.id=mount.form_instance_id LEFT JOIN books book ON book.space_id=instance.space_id
    WHERE mount.id=requested_stable_id AND version.id=requested_version_id;
  ELSIF requested_kind='card_relation' THEN
    RETURN QUERY SELECT relation.space_id,book.id,dependency_content_hash(to_jsonb(version)::text)
    FROM card_relations relation JOIN card_relation_versions version ON version.card_relation_id=relation.id
    LEFT JOIN books book ON book.space_id=relation.space_id
    WHERE relation.id=requested_stable_id AND version.id=CASE WHEN requested_version_id=relation.id THEN relation.current_version_id ELSE requested_version_id END;
  ELSE
    RETURN QUERY SELECT * FROM resolve_dependency_resource_pre035(requested_kind,requested_stable_id,requested_version_id);
  END IF;
END $$;


--
-- Name: resolve_dependency_resource_pre037(text, uuid, uuid); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.resolve_dependency_resource_pre037(requested_kind text, requested_stable_id uuid, requested_version_id uuid) RETURNS TABLE(resolved_space_id uuid, resolved_book_id uuid, resolved_hash character)
    LANGUAGE plpgsql STABLE
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $$
BEGIN
  IF requested_kind='tag_version' THEN
    RETURN QUERY SELECT tag.space_id,book.id,dependency_content_hash(to_jsonb(version)::text)
    FROM material_tags tag JOIN material_tag_versions version ON version.tag_id=tag.id LEFT JOIN books book ON book.space_id=tag.space_id
    WHERE tag.id=requested_stable_id AND version.id=requested_version_id;
  ELSIF requested_kind='tag_membership' THEN
    RETURN QUERY SELECT membership.space_id,book.id,dependency_content_hash(to_jsonb(version)::text)
    FROM material_tag_memberships membership JOIN material_tag_membership_versions version ON version.membership_id=membership.id LEFT JOIN books book ON book.space_id=membership.space_id
    WHERE membership.id=requested_stable_id AND version.id=requested_version_id;
  ELSIF requested_kind='material_group_version' THEN
    RETURN QUERY SELECT group_row.space_id,group_row.book_id,dependency_content_hash(to_jsonb(version)::text)
    FROM material_groups group_row JOIN material_group_versions version ON version.group_id=group_row.id
    WHERE group_row.id=requested_stable_id AND version.id=requested_version_id;
  ELSIF requested_kind='group_membership' THEN
    RETURN QUERY SELECT membership.space_id,book.id,dependency_content_hash(to_jsonb(version)::text)
    FROM material_group_memberships membership JOIN material_group_membership_versions version ON version.membership_id=membership.id LEFT JOIN books book ON book.space_id=membership.space_id
    WHERE membership.id=requested_stable_id AND version.id=requested_version_id;
  ELSIF requested_kind='smart_view_version' THEN
    RETURN QUERY SELECT view_row.space_id,view_row.book_id,dependency_content_hash(to_jsonb(version)::text)
    FROM smart_views view_row JOIN smart_view_versions version ON version.smart_view_id=view_row.id
    WHERE view_row.id=requested_stable_id AND version.id=requested_version_id;
  ELSE
    RETURN QUERY SELECT * FROM resolve_dependency_resource_pre036(requested_kind,requested_stable_id,requested_version_id);
  END IF;
END $$;


--
-- Name: resolve_dependency_resource_pre097(text, uuid, uuid); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.resolve_dependency_resource_pre097(requested_kind text, requested_stable_id uuid, requested_version_id uuid) RETURNS TABLE(resolved_space_id uuid, resolved_book_id uuid, resolved_hash character)
    LANGUAGE plpgsql STABLE
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $$
BEGIN
  IF requested_kind='entity_initial_state' THEN
    RETURN QUERY SELECT book.space_id,initial.book_id,version.value_hash
      FROM entity_initial_states initial JOIN entity_initial_state_versions version ON version.initial_state_id=initial.id JOIN books book ON book.id=initial.book_id
      WHERE initial.id=requested_stable_id AND version.id=requested_version_id;
  ELSIF requested_kind='model_route_snapshot' THEN
    RETURN QUERY SELECT NULL::uuid,NULL::uuid,snapshot.snapshot_hash FROM model_route_snapshots snapshot
      WHERE snapshot.id=requested_stable_id AND snapshot.id=requested_version_id AND snapshot.book_id IS NULL AND snapshot.task_contract_version_id IS NULL
      AND snapshot.managed_task_key IN ('directions','initial_content','form_assist','market_analysis','book_analysis','planning_candidate','chapter_settlement','chapter_generation','world_consistency','creative_extraction','character_dialogue');
    RETURN QUERY SELECT * FROM resolve_dependency_resource_pre037(requested_kind,requested_stable_id,requested_version_id);
  ELSIF requested_kind='context_binding_version' THEN
    RETURN QUERY SELECT binding.space_id,binding.book_id,version.content_hash FROM context_bindings binding JOIN context_binding_versions version ON version.binding_id=binding.id WHERE binding.id=requested_stable_id AND version.id=requested_version_id;
  ELSIF requested_kind='context_preview' THEN
    RETURN QUERY SELECT book.space_id,preview.book_id,preview.source_set_hash FROM context_previews preview JOIN books book ON book.id=preview.book_id WHERE preview.id=requested_stable_id AND preview.id=requested_version_id;
  ELSIF requested_kind='semantic_retrieval_run' THEN
    RETURN QUERY SELECT book.space_id,run.book_id,dependency_content_hash(run.query_hash||run.id::text||run.result_count::text) FROM semantic_retrieval_runs run JOIN books book ON book.id=run.book_id WHERE run.id=requested_stable_id AND run.id=requested_version_id;
  ELSE RETURN QUERY SELECT * FROM resolve_dependency_resource_pre037(requested_kind,requested_stable_id,requested_version_id);
  END IF;
END $$;


--
-- Name: resolve_dependency_resource_pre103(text, uuid, uuid); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.resolve_dependency_resource_pre103(requested_kind text, requested_stable_id uuid, requested_version_id uuid) RETURNS TABLE(resolved_space_id uuid, resolved_book_id uuid, resolved_hash character)
    LANGUAGE plpgsql STABLE
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $$ BEGIN
 IF requested_kind='context_manifest' AND EXISTS(SELECT 1 FROM context_manifests WHERE id=requested_stable_id AND id=requested_version_id AND book_id IS NULL AND public_character_scope IS NOT NULL) THEN
  RETURN QUERY SELECT card.space_id,NULL::uuid,manifest.manifest_hash FROM context_manifests manifest JOIN cards card ON card.id=manifest.public_character_scope WHERE manifest.id=requested_stable_id AND manifest.id=requested_version_id;
 ELSIF requested_kind='model_route_snapshot' AND EXISTS(SELECT 1 FROM model_route_snapshots WHERE id=requested_stable_id AND id=requested_version_id AND book_id IS NULL AND task_contract_version_id IS NULL AND managed_task_key='image_generation') THEN
  RETURN QUERY SELECT NULL::uuid,NULL::uuid,snapshot_hash FROM model_route_snapshots WHERE id=requested_stable_id AND id=requested_version_id;
 ELSE RETURN QUERY SELECT * FROM resolve_dependency_resource_pre097(requested_kind,requested_stable_id,requested_version_id);
 END IF;
END $$;


--
-- Name: scoped_field_uuid(text); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.scoped_field_uuid(seed text) RETURNS uuid
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $$
  SELECT (substr(md5(seed),1,8)||'-'||substr(md5(seed),9,4)||'-4'||substr(md5(seed),14,3)||'-8'||substr(md5(seed),18,3)||'-'||substr(md5(seed),21,12))::uuid
$$;


--
-- Name: stale_quality_on_body_switch(); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.stale_quality_on_body_switch() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $$
DECLARE item record;
BEGIN
  IF NEW.adopted_version_id IS DISTINCT FROM OLD.adopted_version_id THEN
    FOR item IN SELECT DISTINCT binding.report_id FROM new_design.quality_report_body_versions binding WHERE binding.chapter_document_id=NEW.id AND binding.body_version_id IS DISTINCT FROM NEW.adopted_version_id LOOP
      PERFORM new_design.stale_quality_report(item.report_id,'章节正文已采用其他版本。');
    END LOOP;
    UPDATE new_design.quality_rechecks SET status='stale',stale_at=now(),stale_reason='章节正文已采用其他版本。' WHERE checked_body_version_id IS DISTINCT FROM NEW.adopted_version_id AND checked_body_version_id IN (SELECT id FROM new_design.chapter_body_versions WHERE chapter_document_id=NEW.id) AND status='active';
    FOR item IN UPDATE new_design.quality_fix_candidates candidate SET status='stale',revision=revision+1,updated_at=now() WHERE status='proposed' AND EXISTS(SELECT 1 FROM new_design.quality_fix_candidate_versions version WHERE version.id=candidate.current_version_id AND version.target_chapter_document_id=NEW.id AND version.target_body_version_id IS DISTINCT FROM NEW.adopted_version_id) RETURNING id,current_version_id,revision LOOP
      INSERT INTO new_design.quality_fix_candidate_events(id,candidate_id,candidate_version_id,from_status,to_status,action,actor,reason,candidate_revision) VALUES(gen_random_uuid(),item.id,item.current_version_id,'proposed','stale','mark_stale','system','目标正文已切换。',item.revision);
    END LOOP;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: stale_quality_on_fact_change(); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.stale_quality_on_fact_change() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $$
DECLARE item record;
BEGIN
  IF NEW.status IN ('rejected','superseded','stale') AND NEW.status IS DISTINCT FROM OLD.status THEN
    FOR item IN SELECT report_id FROM new_design.quality_report_facts WHERE fact_id=NEW.id LOOP
      PERFORM new_design.stale_quality_report(item.report_id,'引用的事实已失效。');
    END LOOP;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: stale_quality_on_plan_switch(); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.stale_quality_on_plan_switch() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $$
DECLARE item record;
BEGIN
  IF NEW.adopted_version_id IS DISTINCT FROM OLD.adopted_version_id THEN
    FOR item IN SELECT DISTINCT binding.report_id FROM new_design.quality_report_planning_versions binding WHERE binding.planning_object_id=NEW.id AND binding.planning_version_id IS DISTINCT FROM NEW.adopted_version_id LOOP
      PERFORM new_design.stale_quality_report(item.report_id,'规划对象已采用其他版本。');
    END LOOP;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: stale_quality_on_plan_version_change(); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.stale_quality_on_plan_version_change() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $$
DECLARE item record;
BEGIN
  IF (NEW.stale_at IS NOT NULL AND OLD.stale_at IS NULL) OR (NEW.status IN ('rejected','superseded') AND NEW.status IS DISTINCT FROM OLD.status) THEN
    FOR item IN SELECT report_id FROM new_design.quality_report_planning_versions WHERE planning_version_id=NEW.id LOOP
      PERFORM new_design.stale_quality_report(item.report_id,'引用的规划版本已失效。');
    END LOOP;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: stale_quality_report(uuid, text); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.stale_quality_report(target_report uuid, reason text) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $$
DECLARE changed record; old_status text; new_revision integer;
BEGIN
  UPDATE new_design.quality_audit_reports SET stale_at=now(),stale_reason=reason WHERE id=target_report AND stale_at IS NULL;
  FOR changed IN SELECT id,current_version_id,current_status,revision FROM new_design.quality_issues WHERE report_id=target_report AND current_status NOT IN ('stale','superseded') FOR UPDATE LOOP
    old_status:=changed.current_status;
    UPDATE new_design.quality_issues SET current_status='stale',revision=revision+1,updated_at=now() WHERE id=changed.id RETURNING revision INTO new_revision;
    INSERT INTO new_design.quality_issue_events(id,issue_id,issue_version_id,from_status,to_status,action,actor_kind,actor,reason,issue_revision)
    VALUES(gen_random_uuid(),changed.id,changed.current_version_id,old_status,'stale','dependency_invalidated','system','system',reason,new_revision);
  END LOOP;
  FOR changed IN SELECT recheck.id,recheck.issue_id,issue.current_version_id,issue.current_status,issue.revision FROM new_design.quality_rechecks recheck JOIN new_design.quality_issues issue ON issue.id=recheck.issue_id WHERE recheck.recheck_report_id=target_report AND recheck.status='active' FOR UPDATE OF recheck,issue LOOP
    IF changed.current_status NOT IN ('stale','superseded') THEN
      old_status:=changed.current_status;
      UPDATE new_design.quality_issues SET current_status='stale',revision=revision+1,updated_at=now() WHERE id=changed.issue_id RETURNING revision INTO new_revision;
      INSERT INTO new_design.quality_issue_events(id,issue_id,issue_version_id,from_status,to_status,action,actor_kind,actor,reason,issue_revision) VALUES(gen_random_uuid(),changed.issue_id,changed.current_version_id,old_status,'stale','recheck_dependency_invalidated','system','system',reason,new_revision);
    END IF;
  END LOOP;
  UPDATE new_design.quality_rechecks SET status='stale',stale_at=now(),stale_reason=reason WHERE recheck_report_id=target_report AND status='active';
END $$;


--
-- Name: stale_world_quality_material(); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.stale_world_quality_material() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $$ BEGIN
 IF OLD.current_version_id IS NOT DISTINCT FROM NEW.current_version_id AND OLD.status IS NOT DISTINCT FROM NEW.status THEN RETURN NEW; END IF;
 UPDATE quality_audit_reports report SET stale_at=now(),stale_reason='正式资料或关系版本已变化；旧报告仅为历史证据'
 WHERE report.stale_at IS NULL AND EXISTS(SELECT 1 FROM quality_report_material_versions binding WHERE binding.report_id=report.id AND binding.subject_id=NEW.id AND binding.subject_kind=CASE WHEN TG_TABLE_NAME='cards' THEN 'card' ELSE 'relation' END);
 UPDATE quality_rechecks recheck SET status='stale',stale_at=now(),stale_reason='复查的正式来源版本已变化'
 WHERE recheck.status='active' AND recheck.checked_material_versions IS NOT NULL AND EXISTS(SELECT 1 FROM jsonb_array_elements(recheck.checked_material_versions) material WHERE material->>'id'=NEW.id::text AND material->>'kind'=CASE WHEN TG_TABLE_NAME='cards' THEN 'card' ELSE 'relation' END);
 RETURN NEW;
END $$;


--
-- Name: stale_world_quality_specification(); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.stale_world_quality_specification() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $$
DECLARE old_data jsonb; new_data jsonb; report_ids uuid[];
BEGIN
 new_data:=to_jsonb(NEW);old_data:=CASE WHEN TG_OP='INSERT' THEN NULL ELSE to_jsonb(OLD) END;
 IF TG_OP='UPDATE' AND (old_data-ARRAY['revision','updated_at','updated_by']::text[]) IS NOT DISTINCT FROM (new_data-ARRAY['revision','updated_at','updated_by']::text[]) THEN RETURN NEW; END IF;
 SELECT array_agg(request.report_id) INTO report_ids FROM world_consistency_requests request
 WHERE request.report_id IS NOT NULL AND EXISTS(
  SELECT 1 FROM jsonb_array_elements(request.frozen_plan->'catalog'->'subjects') subject
  WHERE
   (TG_TABLE_NAME='field_definitions' AND new_data->>'scope' IN('book_type','card') AND subject->>'kind'='card' AND subject->>'typeId'=new_data->>'card_type_id' AND (new_data->>'scope'='book_type' OR subject->>'id'=new_data->>'card_id') AND EXISTS(SELECT 1 FROM books WHERE id=request.book_id AND space_id::text=new_data->>'space_id')) OR
   (TG_TABLE_NAME='card_types' AND subject->>'kind'='card' AND subject->>'typeId'=new_data->>'id' AND (old_data->>'name' IS DISTINCT FROM new_data->>'name' OR old_data->>'status' IS DISTINCT FROM new_data->>'status')) OR
   (TG_TABLE_NAME='relation_types' AND subject->>'kind'='relation' AND subject->>'typeId'=new_data->>'id') OR
   (TG_TABLE_NAME IN('dictionary_items','dictionary_definitions') AND EXISTS(
    SELECT 1 FROM jsonb_array_elements(subject->'fields') field
    WHERE field->'specification'->'optionSource'->>'kind'='dictionary_tree' AND field->'specification'->'optionSource'->>'dictionaryId'=CASE WHEN TG_TABLE_NAME='dictionary_items' THEN new_data->>'dictionary_id' ELSE new_data->>'id' END))
 );
 IF report_ids IS NULL THEN RETURN NEW; END IF;
 UPDATE quality_audit_reports SET stale_at=now(),stale_reason='正式字段／关系规格或字典树已变化；原检查仅为历史证据' WHERE id=ANY(report_ids) AND stale_at IS NULL;
 UPDATE quality_rechecks SET status='stale',stale_at=now(),stale_reason='复查的正式规格或字典树已变化' WHERE recheck_report_id=ANY(report_ids) AND status='active';
 RETURN NEW;
END $$;


--
-- Name: sync_type_version_fields(uuid); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.sync_type_version_fields(target_version_id uuid) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $_$
DECLARE
  version_row card_type_versions%rowtype;
  type_row record;
  source_template uuid;
  source_form uuid;
  item jsonb;
  option_item jsonb;
  definition_id uuid;
  definition_version_id uuid;
  option_id uuid;
  option_version_id uuid;
  resolved_origin text;
BEGIN
  SELECT * INTO version_row FROM card_type_versions WHERE id=target_version_id;
  SELECT * INTO type_row FROM card_types WHERE id=version_row.card_type_id;
  SELECT book.template_version_id INTO source_template FROM books book WHERE book.space_id=type_row.space_id;
  SELECT form.current_version_id INTO source_form
  FROM card_group_forms form JOIN card_group_form_versions version ON version.id=form.current_version_id
  WHERE form.space_id=type_row.space_id AND version.definition->>'primaryTypeKey'=type_row.type_key
  ORDER BY form.updated_at DESC LIMIT 1;

  FOR item IN SELECT value FROM jsonb_array_elements(version_row.fields) LOOP
    definition_id:=scoped_field_uuid(version_row.card_type_id::text||':'||(item->>'key'));
    SELECT origin INTO resolved_origin FROM field_definitions WHERE id=definition_id;
    IF resolved_origin IS NULL THEN
      resolved_origin:=CASE
        WHEN type_row.space_id='00000000-0000-4000-8000-000000000001'::uuid THEN 'core'
        WHEN type_row.source_type_version_id IS NOT NULL AND version_row.version=1 THEN 'template'
        ELSE 'book_extension'
      END;
    END IF;
    INSERT INTO field_definitions(id,space_id,card_type_id,field_key,origin,scope,status,source_template_version_id,source_type_version_id,source_form_version_id,created_by)
    VALUES(definition_id,type_row.space_id,version_row.card_type_id,item->>'key',resolved_origin,'book_type',CASE WHEN COALESCE((item->>'hidden')::boolean,false) THEN 'archived' ELSE 'active' END,source_template,version_row.id,source_form,'system:type-version')
    ON CONFLICT(id) DO UPDATE SET status=EXCLUDED.status,source_type_version_id=EXCLUDED.source_type_version_id,source_form_version_id=COALESCE(EXCLUDED.source_form_version_id,field_definitions.source_form_version_id),revision=field_definitions.revision+1,updated_at=now();

    definition_version_id:=scoped_field_uuid(definition_id::text||':version:'||version_row.id::text);
    INSERT INTO field_definition_versions(id,field_definition_id,version,field_schema,created_by)
    VALUES(definition_version_id,definition_id,version_row.version,item,'system:type-version') ON CONFLICT DO NOTHING;
    UPDATE field_definitions SET current_version_id=definition_version_id WHERE id=definition_id;

    FOR option_item IN SELECT value FROM jsonb_array_elements(COALESCE(item->'options','[]'::jsonb)) LOOP
      option_id:=CASE WHEN COALESCE(option_item->>'id','') ~* '^[0-9a-f-]{36}$' THEN (option_item->>'id')::uuid ELSE scoped_field_uuid(definition_id::text||':option:'||(option_item->>'value')) END;
      UPDATE field_option_definitions SET status='active',revision=revision+1,updated_at=now() WHERE id=option_id;
      IF NOT FOUND THEN
        INSERT INTO field_option_definitions(id,field_definition_id,option_key,status)
        VALUES(option_id,definition_id,option_item->>'value','active');
      END IF;
      option_version_id:=scoped_field_uuid(option_id::text||':version:'||version_row.id::text);
      IF NOT EXISTS(SELECT 1 FROM field_option_versions WHERE id=option_version_id) THEN
        INSERT INTO field_option_versions(id,option_definition_id,version,label,created_by)
        VALUES(option_version_id,option_id,version_row.version,option_item->>'label','system:type-version');
      END IF;
      UPDATE field_option_definitions SET current_version_id=option_version_id WHERE id=option_id;
    END LOOP;
  END LOOP;
END $_$;


--
-- Name: transfer_json_is_safe(jsonb); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.transfer_json_is_safe(value jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $$
DECLARE entry record; item jsonb; scalar text;
BEGIN
  IF jsonb_typeof(value)='object' THEN
    FOR entry IN SELECT key,val FROM jsonb_each(value) pair(key,val) LOOP
      IF regexp_replace(lower(entry.key),'[^a-z0-9]','','g') IN ('password','token','accesstoken','refreshtoken','sessiontoken','secret','clientsecret','apikey','privatekey','credential','connectionstring','databaseurl','authorization','cookie','setcookie','absolutepath','temporaryurl') THEN RETURN false; END IF;
      IF NOT transfer_json_is_safe(entry.val) THEN RETURN false; END IF;
    END LOOP;
  ELSIF jsonb_typeof(value)='array' THEN
    FOR item IN SELECT array_item FROM jsonb_array_elements(value) items(array_item) LOOP IF NOT transfer_json_is_safe(item) THEN RETURN false; END IF; END LOOP;
  ELSIF jsonb_typeof(value)='string' THEN
    scalar:=value#>>'{}';
    IF scalar ~ '^[A-Za-z]:[\\/]' OR scalar ~ '^/' OR scalar ~ '^[/\\]{2}' OR scalar ~* '^file://' OR scalar ~* '\mbearer[[:space:]]+[^[:space:]]+' OR scalar ~* '://[^/@:]+:[^/@]+@' OR scalar ~* '[?&](token|signature|x-amz-credential|x-amz-signature)=' THEN RETURN false; END IF;
  END IF;
  RETURN true;
END $$;


--
-- Name: transfer_locator_is_safe(text); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.transfer_locator_is_safe(value text) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $_$
DECLARE segment text;
BEGIN
  IF value IS NULL OR value='' OR position(E'\\' IN value)>0 OR value !~ '^[A-Za-z0-9._/-]+$' OR value ~ '(^/|^[A-Za-z]:|(^|/)\.\.(/|$)|//)' THEN RETURN false; END IF;
  FOR segment IN SELECT part FROM unnest(string_to_array(value,'/')) AS parts(part) LOOP
    IF segment='' OR segment IN ('.','..') OR segment ~ '[ .]$' OR upper(split_part(segment,'.',1)) ~ '^(CON|PRN|AUX|NUL|COM[1-9]|LPT[1-9])$' THEN RETURN false; END IF;
  END LOOP;
  RETURN true;
END $_$;


--
-- Name: validate_ai_task_book_space(); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.validate_ai_task_book_space() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $$
BEGIN
  IF NEW.book_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM new_design.books book WHERE book.id=NEW.book_id AND book.space_id=NEW.space_id) THEN
    RAISE EXCEPTION 'AI task book and space mismatch' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: validate_asset_derivation_request(); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.validate_asset_derivation_request() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $$
DECLARE
  source_book uuid; source_checksum char(64); source_current uuid; source_status text;
  output_book uuid; output_revision integer; output_current uuid; output_status text;
BEGIN
  SELECT version.book_id,content.checksum,asset.current_version_id,asset.status
    INTO source_book,source_checksum,source_current,source_status
  FROM asset_versions version
  JOIN assets asset ON asset.id=version.asset_id
  JOIN asset_content_objects content ON content.id=version.content_object_id
  WHERE version.id=NEW.source_asset_version_id;
  SELECT book_id,revision,current_version_id,status
    INTO output_book,output_revision,output_current,output_status
  FROM assets WHERE id=NEW.output_asset_id;
  IF source_book IS DISTINCT FROM NEW.book_id OR output_book IS DISTINCT FROM NEW.book_id THEN
    RAISE EXCEPTION 'asset derivation cannot cross book boundary' USING ERRCODE='23514';
  END IF;
  IF source_status<>'active' OR source_current IS DISTINCT FROM NEW.source_asset_version_id THEN
    RAISE EXCEPTION 'asset derivation source must be the currently adopted version' USING ERRCODE='23514';
  END IF;
  IF output_status<>'active' THEN RAISE EXCEPTION 'asset derivation output asset must be active' USING ERRCODE='23514'; END IF;
  IF source_checksum IS DISTINCT FROM NEW.expected_source_checksum OR
     output_revision IS DISTINCT FROM NEW.expected_output_asset_revision OR
     output_current IS DISTINCT FROM NEW.expected_output_current_version_id THEN
    RAISE EXCEPTION 'asset derivation optimistic snapshot is inconsistent' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: validate_asset_integrity_check(); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.validate_asset_integrity_check() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $$
DECLARE registered_checksum char(64); registered_size bigint;
BEGIN
  SELECT checksum,byte_size INTO registered_checksum,registered_size FROM asset_content_objects WHERE id=NEW.content_object_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'asset content object does not exist' USING ERRCODE='23503'; END IF;
  IF NEW.expected_checksum IS DISTINCT FROM registered_checksum OR NEW.expected_byte_size IS DISTINCT FROM registered_size THEN
    RAISE EXCEPTION 'asset integrity baseline does not match registered content' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: validate_asset_mount(); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.validate_asset_mount() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $$
DECLARE owner_book uuid; version_book uuid;
BEGIN
  SELECT book_id INTO version_book FROM asset_versions WHERE id=NEW.asset_version_id AND asset_id=NEW.asset_id;
  IF version_book IS DISTINCT FROM NEW.book_id THEN RAISE EXCEPTION 'asset version belongs to another book' USING ERRCODE='23514'; END IF;
  CASE NEW.owner_kind
    WHEN 'book' THEN SELECT id INTO owner_book FROM books WHERE id=NEW.owner_stable_id AND id=NEW.owner_exact_version_id;
    WHEN 'card_version' THEN SELECT book.id INTO owner_book FROM card_versions version JOIN cards card ON card.id=version.card_id JOIN books book ON book.space_id=card.space_id WHERE card.id=NEW.owner_stable_id AND version.id=NEW.owner_exact_version_id;
    WHEN 'chapter_body_version' THEN SELECT document.book_id INTO owner_book FROM chapter_body_versions version JOIN chapter_documents document ON document.id=version.chapter_document_id WHERE document.id=NEW.owner_stable_id AND version.id=NEW.owner_exact_version_id;
    WHEN 'research_record_version' THEN SELECT NEW.book_id INTO owner_book FROM research_record_versions version WHERE version.record_id=NEW.owner_stable_id AND version.id=NEW.owner_exact_version_id AND EXISTS(SELECT 1 FROM book_research_references reference WHERE reference.book_id=NEW.book_id AND (reference.research_version_id=version.id OR EXISTS(SELECT 1 FROM research_reference_pack_items item WHERE item.pack_version_id=reference.pack_version_id AND item.research_version_id=version.id)));
    WHEN 'prompt_recipe_version' THEN SELECT NEW.book_id INTO owner_book FROM prompt_recipe_versions version WHERE version.recipe_id=NEW.owner_stable_id AND version.id=NEW.owner_exact_version_id;
    WHEN 'ai_task_attempt' THEN SELECT task.book_id INTO owner_book FROM ai_task_attempts attempt JOIN ai_tasks task ON task.id=attempt.task_id WHERE attempt.task_id=NEW.owner_stable_id AND attempt.id=NEW.owner_exact_version_id;
    WHEN 'quality_issue_evidence' THEN SELECT issue.book_id INTO owner_book FROM quality_issue_evidence evidence JOIN quality_issue_versions version ON version.id=evidence.issue_version_id JOIN quality_issues issue ON issue.id=version.issue_id WHERE evidence.id=NEW.owner_stable_id AND evidence.id=NEW.owner_exact_version_id;
  END CASE;
  IF owner_book IS DISTINCT FROM NEW.book_id THEN RAISE EXCEPTION 'asset mount owner is invalid or belongs to another book' USING ERRCODE='23514'; END IF;
  RETURN NEW;
END $$;


--
-- Name: validate_background_job_reference(); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.validate_background_job_reference() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $$
DECLARE expected_handler background_job_handlers%ROWTYPE; event_row outbox_events%ROWTYPE; resolved_book uuid; resolved_space uuid;
BEGIN
  SELECT * INTO expected_handler FROM background_job_handlers WHERE handler_key=NEW.handler_key AND job_kind=NEW.job_kind AND specialized_request_kind=NEW.specialized_request_kind AND status='active';
  IF NOT FOUND THEN RAISE EXCEPTION 'job handler or specialized request kind is not registered' USING ERRCODE='23514'; END IF;
  SELECT * INTO event_row FROM outbox_events WHERE id=NEW.outbox_event_id;
  IF NOT FOUND OR event_row.topic IS DISTINCT FROM expected_handler.topic OR event_row.event_version IS DISTINCT FROM expected_handler.event_version OR event_row.space_id IS DISTINCT FROM NEW.space_id OR event_row.book_id IS DISTINCT FROM NEW.book_id OR event_row.ordering_key IS DISTINCT FROM NEW.ordering_key OR event_row.aggregate_sequence IS DISTINCT FROM NEW.aggregate_sequence OR event_row.payload->>'specializedRequestKind' IS DISTINCT FROM NEW.specialized_request_kind OR event_row.payload->>'specializedRequestId' IS DISTINCT FROM NEW.specialized_request_id::text THEN RAISE EXCEPTION 'job and outbox event identity mismatch' USING ERRCODE='23514'; END IF;
  CASE NEW.specialized_request_kind
    WHEN 'dependency_recompute_request' THEN SELECT request.book_id,book.space_id INTO resolved_book,resolved_space FROM dependency_recompute_requests request JOIN books book ON book.id=request.book_id WHERE request.id=NEW.specialized_request_id;
    WHEN 'asset_derivation' THEN SELECT request.book_id,book.space_id INTO resolved_book,resolved_space FROM asset_derivations request JOIN books book ON book.id=request.book_id WHERE request.id=NEW.specialized_request_id;
    WHEN 'graph_projection_request' THEN SELECT request.book_id,book.space_id INTO resolved_book,resolved_space FROM graph_projection_requests request JOIN books book ON book.id=request.book_id WHERE request.id=NEW.specialized_request_id;
    WHEN 'embedding_chunking_request' THEN SELECT request.book_id,book.space_id INTO resolved_book,resolved_space FROM chunking_requests request JOIN books book ON book.id=request.book_id WHERE request.id=NEW.specialized_request_id;
    WHEN 'embedding_request' THEN SELECT request.book_id,book.space_id INTO resolved_book,resolved_space FROM embedding_requests request JOIN books book ON book.id=request.book_id WHERE request.id=NEW.specialized_request_id;
    WHEN 'embedding_index_generation' THEN SELECT request.book_id,book.space_id INTO resolved_book,resolved_space FROM embedding_index_generations request JOIN books book ON book.id=request.book_id WHERE request.id=NEW.specialized_request_id;
    WHEN 'ai_task' THEN SELECT request.book_id,request.space_id INTO resolved_book,resolved_space FROM ai_tasks request WHERE request.id=NEW.specialized_request_id;
    WHEN 'backup_request' THEN SELECT operation.book_id,operation.space_id INTO resolved_book,resolved_space FROM transfer_operations operation WHERE operation.id=NEW.specialized_request_id;
    WHEN 'publication_export_request' THEN SELECT request.book_id,book.space_id INTO resolved_book,resolved_space FROM publication_export_requests request JOIN books book ON book.id=request.book_id WHERE request.id=NEW.specialized_request_id;
  END CASE;
  IF resolved_space IS NULL OR resolved_book IS DISTINCT FROM NEW.book_id OR resolved_space IS DISTINCT FROM NEW.space_id THEN RAISE EXCEPTION 'job specialized request does not resolve in the same scope' USING ERRCODE='23514'; END IF;
  RETURN NEW;
END $$;


--
-- Name: validate_book_lifecycle_event(); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.validate_book_lifecycle_event() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $$
DECLARE latest_state text;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtextextended(NEW.book_id::text,0));
  IF NEW.snapshot_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM book_completion_snapshots snapshot WHERE snapshot.id=NEW.snapshot_id AND snapshot.book_id=NEW.book_id) THEN RAISE EXCEPTION 'completion snapshot and lifecycle book mismatch' USING ERRCODE='23514'; END IF;
  SELECT event_kind INTO latest_state FROM book_lifecycle_events WHERE book_id=NEW.book_id AND event_kind IN ('completed','reopened') ORDER BY created_at DESC,id DESC LIMIT 1;
  IF NEW.event_kind='completed' AND latest_state='completed' THEN RAISE EXCEPTION 'book is already completed' USING ERRCODE='23514'; END IF;
  IF NEW.event_kind='reopened' AND latest_state IS DISTINCT FROM 'completed' THEN RAISE EXCEPTION 'only a completed book can be reopened' USING ERRCODE='23514'; END IF;
  RETURN NEW;
END $$;


--
-- Name: validate_chapter_adoption_preparation(); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.validate_chapter_adoption_preparation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $$
BEGIN
  IF NEW.supplement_base_checkpoint_id IS NULL THEN
    IF NOT EXISTS(
      SELECT 1 FROM chapter_documents document
      JOIN chapter_body_versions body ON body.id=NEW.body_version_id AND body.chapter_document_id=document.id
      JOIN planning_objects object ON object.id=NEW.planning_object_id
      WHERE document.id=NEW.chapter_document_id AND document.book_id=NEW.book_id AND document.revision=NEW.expected_document_revision
        AND body.archived_at IS NULL AND body.planning_version_id=NEW.planning_version_id
        AND body.context_manifest_id IS NOT DISTINCT FROM NEW.context_manifest_id
        AND object.book_id=NEW.book_id AND object.card_id=document.chapter_card_id AND object.level='chapter'
        AND object.adopted_version_id=NEW.planning_version_id
    ) THEN RAISE EXCEPTION 'chapter adoption preparation dependencies mismatch' USING ERRCODE='23514'; END IF;
  ELSE
    IF NOT EXISTS(
      SELECT 1 FROM chapter_stable_checkpoints base
      JOIN chapter_adoption_sessions original ON original.id=base.session_id AND original.status='stable'
      JOIN chapter_settlements settlement ON settlement.id=base.settlement_id AND settlement.status='committed'
      JOIN chapter_documents document ON document.id=base.chapter_document_id AND document.book_id=base.book_id
        AND document.status='active' AND document.adopted_version_id=base.body_version_id
      JOIN books book ON book.id=base.book_id AND book.status='active'
      JOIN chapter_body_versions body ON body.id=base.body_version_id AND body.chapter_document_id=document.id AND body.archived_at IS NULL
      JOIN planning_versions plan ON plan.id=original.planning_version_id AND plan.object_id=original.planning_object_id AND plan.book_id=base.book_id
      WHERE base.id=NEW.supplement_base_checkpoint_id AND base.status='stable'
        AND base.book_id=NEW.book_id AND base.chapter_document_id=NEW.chapter_document_id AND base.body_version_id=NEW.body_version_id
        AND document.revision=NEW.expected_document_revision AND base.chapter_order=document.logical_order
        AND original.book_id=base.book_id AND original.chapter_document_id=document.id AND original.body_version_id=body.id
        AND original.settlement_id=settlement.id AND settlement.book_id=base.book_id
        AND settlement.chapter_document_id=document.id AND settlement.body_version_id=body.id
        AND NEW.planning_object_id=original.planning_object_id AND NEW.planning_version_id=original.planning_version_id
        AND NEW.planning_content_hash=plan.content_hash AND body.planning_version_id=plan.id
        AND NEW.context_manifest_id IS NOT DISTINCT FROM body.context_manifest_id
        AND NEW.context_manifest_id IS NOT DISTINCT FROM original.context_manifest_id
    ) THEN RAISE EXCEPTION 'supplement requires the exact active stable origin' USING ERRCODE='23514'; END IF;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: validate_chapter_adoption_session(); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.validate_chapter_adoption_session() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $$
DECLARE prep chapter_adoption_preparations%ROWTYPE; document chapter_documents%ROWTYPE; body chapter_body_versions%ROWTYPE;
BEGIN
  SELECT * INTO prep FROM chapter_adoption_preparations WHERE id=NEW.preparation_id;
  SELECT * INTO document FROM chapter_documents WHERE id=NEW.chapter_document_id;
  SELECT * INTO body FROM chapter_body_versions WHERE id=NEW.body_version_id;
  IF prep.book_id IS DISTINCT FROM NEW.book_id OR prep.chapter_document_id IS DISTINCT FROM NEW.chapter_document_id OR prep.body_version_id IS DISTINCT FROM NEW.body_version_id OR prep.planning_object_id IS DISTINCT FROM NEW.planning_object_id OR prep.planning_version_id IS DISTINCT FROM NEW.planning_version_id OR prep.context_manifest_id IS DISTINCT FROM NEW.context_manifest_id OR prep.dependency_hash IS DISTINCT FROM NEW.dependency_hash THEN RAISE EXCEPTION 'adoption session does not match frozen preparation' USING ERRCODE='23514'; END IF;
  IF document.book_id IS DISTINCT FROM NEW.book_id OR body.chapter_document_id IS DISTINCT FROM NEW.chapter_document_id OR body.archived_at IS NOT NULL THEN RAISE EXCEPTION 'adoption session body scope mismatch' USING ERRCODE='23514'; END IF;
  RETURN NEW;
END $$;


--
-- Name: validate_chapter_body_version_provenance(); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.validate_chapter_body_version_provenance() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $$
DECLARE document_book uuid; document_chapter uuid;
BEGIN
  SELECT book_id,chapter_card_id INTO document_book,document_chapter FROM new_design.chapter_documents WHERE id=NEW.chapter_document_id;
  IF NEW.ai_attempt_id IS NOT NULL AND NOT EXISTS(
    SELECT 1 FROM new_design.ai_task_attempts attempt JOIN new_design.ai_tasks task ON task.id=attempt.task_id
    WHERE attempt.id=NEW.ai_attempt_id AND attempt.task_id=NEW.ai_task_id AND task.book_id=document_book
      AND attempt.task_contract_version_id=NEW.task_contract_version_id
      AND attempt.prompt_recipe_version_id=NEW.prompt_recipe_version_id
      AND attempt.context_manifest_id=NEW.context_manifest_id
      AND attempt.model_route_snapshot_id=NEW.model_route_snapshot_id
  ) THEN RAISE EXCEPTION 'chapter body AI attempt and frozen runtime mismatch' USING ERRCODE='23514'; END IF;
  IF NEW.source='ai_candidate' AND NEW.source_run_id IS NULL AND (
    NEW.ai_task_id IS NULL OR NEW.ai_attempt_id IS NULL OR NEW.planning_version_id IS NULL OR
    NEW.context_manifest_id IS NULL OR NEW.task_contract_version_id IS NULL OR
    NEW.prompt_recipe_version_id IS NULL OR NEW.model_route_snapshot_id IS NULL
  ) THEN RAISE EXCEPTION 'new AI chapter candidate requires frozen provenance' USING ERRCODE='23514'; END IF;
  IF NEW.source<>'ai_candidate' AND (NEW.ai_task_id IS NOT NULL OR NEW.ai_attempt_id IS NOT NULL) THEN
    RAISE EXCEPTION 'manual chapter candidate cannot claim AI execution provenance' USING ERRCODE='23514';
  END IF;
  IF NEW.planning_version_id IS NOT NULL AND NOT EXISTS(
    SELECT 1 FROM new_design.planning_objects object JOIN new_design.planning_versions version ON version.id=NEW.planning_version_id AND version.object_id=object.id
    WHERE object.id=NEW.planning_object_id AND object.book_id=document_book AND object.card_id=document_chapter AND object.level='chapter'
  ) THEN RAISE EXCEPTION 'chapter body planning provenance mismatch' USING ERRCODE='23514'; END IF;
  RETURN NEW;
END $$;


--
-- Name: validate_chapter_revision_execution_insert(); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.validate_chapter_revision_execution_insert() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $$
DECLARE source_row record;
BEGIN
  SELECT plan.preview_id,plan.book_id,preview.chapter_document_id,preview.old_body_version_id,preview.new_body_version_id,preview.old_checkpoint_id,preview.restart_checkpoint_id
  INTO source_row FROM chapter_revision_plans plan JOIN chapter_revision_previews preview ON preview.id=plan.preview_id WHERE plan.id=NEW.plan_id;
  IF NOT FOUND OR ROW(NEW.preview_id,NEW.book_id,NEW.chapter_document_id,NEW.old_body_version_id,NEW.new_body_version_id,NEW.old_checkpoint_id,NEW.restart_checkpoint_id)
    IS DISTINCT FROM ROW(source_row.preview_id,source_row.book_id,source_row.chapter_document_id,source_row.old_body_version_id,source_row.new_body_version_id,source_row.old_checkpoint_id,source_row.restart_checkpoint_id)
  THEN RAISE EXCEPTION 'chapter revision execution does not match plan and preview' USING ERRCODE='23514'; END IF;
  RETURN NEW;
END $$;


--
-- Name: validate_chapter_revision_plan_insert(); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.validate_chapter_revision_plan_insert() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $$
DECLARE preview chapter_revision_previews%ROWTYPE;
BEGIN
  SELECT * INTO preview FROM chapter_revision_previews WHERE id=NEW.preview_id;
  IF NOT FOUND OR NEW.book_id<>preview.book_id OR NEW.expected_preview_revision<>preview.revision OR NEW.expected_document_revision<>preview.expected_document_revision THEN RAISE EXCEPTION 'chapter revision plan does not match frozen preview' USING ERRCODE='23514'; END IF;
  RETURN NEW;
END $$;


--
-- Name: validate_chapter_revision_preview_insert(); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.validate_chapter_revision_preview_insert() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $$
DECLARE source_row record;
BEGIN
  SELECT session.book_id,session.chapter_document_id,session.prior_body_version_id,session.body_version_id,
         checkpoint.settlement_id checkpoint_settlement_id
  INTO source_row FROM chapter_adoption_sessions session
  JOIN chapter_stable_checkpoints checkpoint ON checkpoint.id=NEW.old_checkpoint_id
  WHERE session.id=NEW.session_id;
  IF NOT FOUND OR ROW(NEW.book_id,NEW.chapter_document_id,NEW.old_body_version_id,NEW.new_body_version_id,NEW.old_settlement_id)
    IS DISTINCT FROM ROW(source_row.book_id,source_row.chapter_document_id,source_row.prior_body_version_id,source_row.body_version_id,source_row.checkpoint_settlement_id)
  THEN RAISE EXCEPTION 'chapter revision preview sources do not match adoption session and checkpoint' USING ERRCODE='23514'; END IF;
  RETURN NEW;
END $$;


--
-- Name: validate_chapter_revision_review_flag_insert(); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.validate_chapter_revision_review_flag_insert() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $$
DECLARE execution_row chapter_revision_executions%ROWTYPE; impact_preview uuid; body_document uuid; execution_found boolean;
BEGIN
  SELECT * INTO execution_row FROM chapter_revision_executions WHERE id=NEW.execution_id;
  execution_found:=FOUND;
  IF NEW.impact_id IS NOT NULL THEN SELECT preview_id INTO impact_preview FROM chapter_revision_impacts WHERE id=NEW.impact_id; END IF;
  IF NEW.target_body_version_id IS NOT NULL THEN SELECT chapter_document_id INTO body_document FROM chapter_body_versions WHERE id=NEW.target_body_version_id; END IF;
  IF NOT execution_found OR NEW.book_id<>execution_row.book_id OR NEW.changed_chapter_document_id<>execution_row.chapter_document_id OR (NEW.impact_id IS NOT NULL AND impact_preview IS DISTINCT FROM execution_row.preview_id) OR (NEW.target_body_version_id IS NOT NULL AND body_document IS DISTINCT FROM NEW.target_chapter_document_id) THEN RAISE EXCEPTION 'chapter revision review flag sources do not match execution' USING ERRCODE='23514'; END IF;
  RETURN NEW;
END $$;


--
-- Name: validate_chapter_settlement_ai_attempt(); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.validate_chapter_settlement_ai_attempt() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $$
DECLARE task ai_tasks%ROWTYPE;
BEGIN
  SELECT * INTO task FROM ai_tasks WHERE id=NEW.task_id;
  IF task.source_kind='chapter_settlement_extraction' AND (NEW.attempt_number<>1 OR NEW.trigger_kind<>'initial' OR NEW.status NOT IN ('queued','running') OR NOT EXISTS(SELECT 1 FROM ai_task_steps step WHERE step.id=NEW.step_id AND step.task_id=NEW.task_id AND step.max_attempts=1)) THEN
    RAISE EXCEPTION 'chapter extraction is one initial attempt' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: validate_chapter_settlement_item(); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.validate_chapter_settlement_item() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $$
DECLARE session chapter_adoption_sessions%ROWTYPE; anchor chapter_text_anchors%ROWTYPE;
BEGIN
  SELECT * INTO session FROM chapter_adoption_sessions WHERE id=NEW.session_id;
  SELECT * INTO anchor FROM chapter_text_anchors WHERE id=NEW.evidence_anchor_id;
  IF session.status IN ('stable','impact_review_required','cancelled') THEN RAISE EXCEPTION 'settlement session cannot accept proposal changes' USING ERRCODE='23514'; END IF;
  IF anchor.chapter_document_id IS DISTINCT FROM session.chapter_document_id OR anchor.body_version_id IS DISTINCT FROM session.body_version_id OR anchor.status<>'active' THEN RAISE EXCEPTION 'settlement item evidence must point to active adopted body' USING ERRCODE='23514'; END IF;
  IF NEW.source_kind='ai' AND NOT EXISTS(SELECT 1 FROM ai_task_attempts attempt WHERE attempt.id=NEW.source_attempt_id AND attempt.task_id=NEW.source_task_id) THEN RAISE EXCEPTION 'settlement AI provenance mismatch' USING ERRCODE='23514'; END IF;
  RETURN NEW;
END $$;


--
-- Name: validate_chapter_writing_request_scope(); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.validate_chapter_writing_request_scope() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $$
DECLARE document_row chapter_documents%ROWTYPE; manifest_row context_manifests%ROWTYPE; contract_prompt uuid; controlled boolean;
BEGIN
  SELECT * INTO document_row FROM chapter_documents WHERE id=NEW.chapter_document_id;
  IF NOT FOUND OR document_row.book_id IS DISTINCT FROM NEW.book_id THEN RAISE EXCEPTION 'chapter writing request book mismatch' USING ERRCODE='23514'; END IF;
  IF NOT EXISTS(SELECT 1 FROM planning_objects object WHERE object.id=NEW.planning_object_id AND object.book_id=NEW.book_id AND object.card_id=document_row.chapter_card_id AND object.level='chapter' AND (TG_OP<>'INSERT' OR object.adopted_version_id=NEW.planning_version_id)) THEN RAISE EXCEPTION 'chapter writing request plan mismatch' USING ERRCODE='23514'; END IF;
  SELECT * INTO manifest_row FROM context_manifests WHERE id=NEW.context_manifest_id;
  SELECT prompt_recipe_version_id INTO contract_prompt FROM task_contract_versions WHERE id=NEW.task_contract_version_id;
  controlled:=NEW.controlled_snapshot IS NOT NULL;
  IF controlled THEN
    IF NEW.controlled_snapshot->'input'->>'operation' IS DISTINCT FROM NEW.operation_kind OR NEW.controlled_snapshot->'input'->'body'->>'versionId' IS DISTINCT FROM NEW.input_body_version_id::text OR NEW.controlled_snapshot->'input'->'body'->>'contentHash' IS DISTINCT FROM NEW.input_body_hash::text OR NEW.controlled_snapshot->'input'->'selection'->>'start' IS DISTINCT FROM NEW.selection_start::text OR NEW.controlled_snapshot->'input'->'selection'->>'end' IS DISTINCT FROM NEW.selection_end::text THEN RAISE EXCEPTION 'controlled body operation mismatch' USING ERRCODE='23514'; END IF;
    IF NEW.input_body_version_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM chapter_body_versions body WHERE body.id=NEW.input_body_version_id AND body.chapter_document_id=NEW.chapter_document_id AND body.content=NEW.controlled_snapshot->'input'->'body'->>'content') THEN RAISE EXCEPTION 'controlled frozen body content mismatch' USING ERRCODE='23514'; END IF;
    IF NEW.selection_start IS NOT NULL AND (NEW.controlled_snapshot->'candidateBoundary'->>'prefix'||(NEW.controlled_snapshot->'input'->'selection'->>'text')||(NEW.controlled_snapshot->'candidateBoundary'->>'suffix')) IS DISTINCT FROM NEW.controlled_snapshot->'input'->'body'->>'content' THEN RAISE EXCEPTION 'controlled selection boundary mismatch' USING ERRCODE='23514'; END IF;
    IF NEW.result_body_version_id IS NOT NULL THEN
      IF NEW.controlled_output IS NULL OR NOT EXISTS(SELECT 1 FROM chapter_body_versions body WHERE body.id=NEW.result_body_version_id AND body.content=CASE WHEN NEW.selection_start IS NULL THEN NEW.controlled_output->>'content' ELSE (NEW.controlled_snapshot->'candidateBoundary'->>'prefix')||(NEW.controlled_output->>'content')||(NEW.controlled_snapshot->'candidateBoundary'->>'suffix') END) THEN RAISE EXCEPTION 'controlled candidate differs from saved reply' USING ERRCODE='23514'; END IF;
    END IF;
  END IF;
  IF controlled AND (NEW.controlled_snapshot->>'assetId' IS DISTINCT FROM 'new_design.chapter.generate_candidate' OR COALESCE(NEW.controlled_snapshot->>'assetVersion','') NOT IN ('v1','v2') OR
    NEW.controlled_snapshot->'input'->>'bookId' IS DISTINCT FROM NEW.book_id::text OR NEW.controlled_snapshot->'input'->>'chapterCardId' IS DISTINCT FROM document_row.chapter_card_id::text OR
    NEW.controlled_snapshot->>'contextManifestId' IS DISTINCT FROM NEW.context_manifest_id::text OR NEW.controlled_snapshot->>'taskContractVersionId' IS DISTINCT FROM NEW.task_contract_version_id::text OR
    NOT EXISTS(SELECT 1 FROM task_contract_versions version JOIN task_contracts contract ON contract.id=version.contract_id JOIN prompt_recipe_versions recipe ON recipe.id=version.prompt_recipe_version_id
      WHERE version.id=NEW.task_contract_version_id AND version.task_group='controlled_chapter_generation' AND contract.task_key='controlled_chapter_'||NEW.id::text
        AND version.input_schema->'const'=NEW.controlled_snapshot->'input' AND recipe.variables_schema->'const'=NEW.controlled_snapshot->'input')) THEN RAISE EXCEPTION 'controlled chapter runtime scope mismatch' USING ERRCODE='23514'; END IF;
  IF manifest_row.book_id IS DISTINCT FROM NEW.book_id OR manifest_row.chapter_id IS DISTINCT FROM document_row.chapter_card_id OR
    (CASE WHEN controlled THEN manifest_row.status<>'complete' ELSE manifest_row.status<>'finalized' END) OR
    manifest_row.task_contract_version_id IS DISTINCT FROM NEW.task_contract_version_id OR manifest_row.prompt_recipe_version_id IS DISTINCT FROM NEW.prompt_recipe_version_id OR
    manifest_row.model_route_snapshot_id IS DISTINCT FROM NEW.model_route_snapshot_id OR contract_prompt IS DISTINCT FROM NEW.prompt_recipe_version_id THEN RAISE EXCEPTION 'chapter writing frozen runtime mismatch' USING ERRCODE='23514'; END IF;
  IF NEW.input_body_version_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM chapter_body_versions version WHERE version.id=NEW.input_body_version_id AND version.chapter_document_id=NEW.chapter_document_id AND version.content_hash=NEW.input_body_hash) THEN RAISE EXCEPTION 'chapter writing input body mismatch' USING ERRCODE='23514'; END IF;
  IF NEW.ai_task_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM ai_tasks task WHERE task.id=NEW.ai_task_id AND task.book_id=NEW.book_id AND task.task_contract_version_id=NEW.task_contract_version_id AND task.source_kind='chapter_writing_request' AND task.source_id=NEW.id) THEN RAISE EXCEPTION 'chapter writing AI task mismatch' USING ERRCODE='23514'; END IF;
  IF NEW.result_body_version_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM chapter_body_versions version WHERE version.id=NEW.result_body_version_id AND version.chapter_document_id=NEW.chapter_document_id AND version.source='ai_candidate' AND version.operation_kind=NEW.operation_kind AND version.planning_object_id=NEW.planning_object_id AND version.planning_version_id=NEW.planning_version_id AND version.context_manifest_id=NEW.context_manifest_id AND version.task_contract_version_id=NEW.task_contract_version_id AND version.prompt_recipe_version_id=NEW.prompt_recipe_version_id AND version.model_route_snapshot_id=NEW.model_route_snapshot_id AND version.ai_task_id=NEW.ai_task_id AND version.input_body_version_id IS NOT DISTINCT FROM NEW.input_body_version_id) THEN RAISE EXCEPTION 'chapter writing result body mismatch' USING ERRCODE='23514'; END IF;
  RETURN NEW;
END $$;


--
-- Name: validate_completion_snapshot_chapter(); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.validate_completion_snapshot_chapter() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $$
BEGIN
  IF NOT EXISTS(SELECT 1 FROM book_completion_snapshots snapshot JOIN chapter_documents document ON document.book_id=snapshot.book_id AND document.id=NEW.chapter_document_id LEFT JOIN chapter_body_versions body ON body.id=NEW.body_version_id AND body.chapter_document_id=document.id LEFT JOIN chapter_stable_checkpoints checkpoint ON checkpoint.id=NEW.stable_checkpoint_id AND checkpoint.chapter_document_id=document.id AND checkpoint.body_version_id=NEW.body_version_id WHERE snapshot.id=NEW.snapshot_id AND (NEW.body_version_id IS NULL OR body.id IS NOT NULL) AND (NEW.stable_checkpoint_id IS NULL OR checkpoint.id IS NOT NULL)) THEN RAISE EXCEPTION 'completion chapter binding is outside the snapshot book or version' USING ERRCODE='23514'; END IF;
  RETURN NEW;
END $$;


--
-- Name: validate_debug_attempt_insert(); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.validate_debug_attempt_insert() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $$
DECLARE debug_task boolean;
BEGIN
  IF NEW.debug_result IS NOT NULL OR NEW.debug_execution IS NOT NULL OR NEW.debug_failure IS NOT NULL THEN
    RAISE EXCEPTION 'debug outcome must be written only by terminal transition' USING ERRCODE='23514';
  END IF;
  SELECT source_kind='prompt_composition_debug' INTO debug_task FROM new_design.ai_tasks WHERE id=NEW.task_id;
  IF debug_task IS true AND (NEW.attempt_number<>1 OR NEW.trigger_kind<>'initial' OR NEW.status NOT IN ('queued','running') OR NOT EXISTS(SELECT 1 FROM new_design.ai_task_steps step WHERE step.id=NEW.step_id AND step.task_id=NEW.task_id AND step.max_attempts=1)) THEN
    RAISE EXCEPTION 'debug run is a single initial attempt, never an automatic retry' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: validate_dependency_resource(); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.validate_dependency_resource() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $$
DECLARE resolved record;
BEGIN
  IF NEW.resource_kind='asset_version' THEN
    SELECT asset.space_id,version.book_id,content.checksum INTO resolved
    FROM asset_versions version JOIN assets asset ON asset.id=version.asset_id JOIN asset_content_objects content ON content.id=version.content_object_id
    WHERE version.asset_id=NEW.stable_object_id AND version.id=NEW.exact_version_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'asset dependency resource reference does not resolve' USING ERRCODE='23503'; END IF;
    NEW.space_id:=resolved.space_id; NEW.book_id:=resolved.book_id; NEW.content_hash:=resolved.checksum;
  ELSE
    SELECT * INTO resolved FROM resolve_dependency_resource(NEW.resource_kind,NEW.stable_object_id,NEW.exact_version_id);
    IF NOT FOUND THEN RAISE EXCEPTION 'dependency resource reference does not resolve' USING ERRCODE='23503'; END IF;
    NEW.space_id:=resolved.resolved_space_id; NEW.book_id:=resolved.resolved_book_id; NEW.content_hash:=resolved.resolved_hash;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: validate_embedding_generation(); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.validate_embedding_generation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $$
BEGIN
  IF NOT EXISTS(SELECT 1 FROM embedding_profile_versions version JOIN embedding_profiles profile ON profile.id=version.profile_id WHERE version.id=NEW.profile_version_id AND profile.status='active') THEN RAISE EXCEPTION 'embedding generation requires an active profile' USING ERRCODE='23514'; END IF;
  RETURN NEW;
END $$;


--
-- Name: validate_embedding_index_state(); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.validate_embedding_index_state() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $$
BEGIN
  IF NEW.active_generation_id IS NOT NULL AND NOT EXISTS(
    SELECT 1 FROM embedding_index_generations generation JOIN embedding_profile_versions version ON version.id=generation.profile_version_id
    WHERE generation.id=NEW.active_generation_id AND generation.book_id=NEW.book_id AND version.profile_id=NEW.profile_id
  ) THEN RAISE EXCEPTION 'active embedding generation must belong to the same book and profile' USING ERRCODE='23514'; END IF;
  RETURN NEW;
END $$;


--
-- Name: validate_embedding_result(); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.validate_embedding_result() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $$
DECLARE request_row embedding_requests%ROWTYPE; chunk_row embedding_chunks%ROWTYPE; expected_dims integer;
BEGIN
  SELECT * INTO request_row FROM embedding_requests WHERE id=NEW.request_id;
  SELECT * INTO chunk_row FROM embedding_chunks WHERE id=NEW.chunk_id;
  SELECT dimensions INTO expected_dims FROM embedding_profile_versions WHERE id=NEW.profile_version_id;
  IF NOT EXISTS(SELECT 1 FROM embedding_attempts attempt WHERE attempt.id=NEW.attempt_id AND attempt.request_id=NEW.request_id) THEN RAISE EXCEPTION 'embedding attempt does not belong to request' USING ERRCODE='23514'; END IF;
  IF request_row.chunk_id<>NEW.chunk_id OR request_row.profile_version_id<>NEW.profile_version_id THEN RAISE EXCEPTION 'embedding result does not match frozen request' USING ERRCODE='23514'; END IF;
  IF NEW.outcome='applied' AND (NEW.observed_source_hash<>request_row.expected_source_hash OR NEW.observed_chunk_hash<>request_row.expected_chunk_hash OR chunk_row.status<>'current') THEN
    RAISE EXCEPTION 'late embedding result must be recorded as rejected_stale' USING ERRCODE='23514';
  END IF;
  IF NEW.vector_value IS NOT NULL AND vector_dims(NEW.vector_value)<>expected_dims THEN RAISE EXCEPTION 'embedding dimensions do not match profile version' USING ERRCODE='22000'; END IF;
  RETURN NEW;
END $$;


--
-- Name: validate_embedding_source_snapshot(); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.validate_embedding_source_snapshot() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $$
DECLARE dependency_row dependency_resources%ROWTYPE; allowed_kinds text[]; profile_status text;
BEGIN
  SELECT * INTO dependency_row FROM dependency_resources WHERE id=NEW.dependency_source_resource_id;
  SELECT version.allowed_source_kinds,profile.status INTO allowed_kinds,profile_status FROM embedding_profile_versions version JOIN embedding_profiles profile ON profile.id=version.profile_id WHERE version.id=NEW.profile_version_id;
  IF profile_status<>'active' THEN RAISE EXCEPTION 'archived embedding profile cannot accept sources' USING ERRCODE='23514'; END IF;
  IF dependency_row.book_id IS NOT NULL AND (dependency_row.book_id IS DISTINCT FROM NEW.book_id OR dependency_row.space_id IS DISTINCT FROM NEW.space_id) THEN RAISE EXCEPTION 'embedding source must use a global resource or a dependency resource from the same book' USING ERRCODE='23514'; END IF;
  IF dependency_row.content_hash<>NEW.source_hash THEN RAISE EXCEPTION 'embedding source hash does not match dependency snapshot' USING ERRCODE='23514'; END IF;
  IF NOT NEW.source_kind=ANY(allowed_kinds) THEN RAISE EXCEPTION 'source kind is not enabled by embedding profile version' USING ERRCODE='23514'; END IF;
  RETURN NEW;
END $$;


--
-- Name: validate_embedding_vector(); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.validate_embedding_vector() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $$
DECLARE generation_row embedding_index_generations%ROWTYPE; expected_dims integer; expected_metric text;
BEGIN
  SELECT * INTO generation_row FROM embedding_index_generations WHERE id=NEW.generation_id;
  SELECT dimensions,distance_metric INTO expected_dims,expected_metric FROM embedding_profile_versions WHERE id=NEW.profile_version_id;
  IF generation_row.book_id<>NEW.book_id OR generation_row.profile_version_id<>NEW.profile_version_id THEN RAISE EXCEPTION 'cross-book or mixed-profile generation is forbidden' USING ERRCODE='23514'; END IF;
  IF vector_dims(NEW.embedding)<>expected_dims THEN RAISE EXCEPTION 'mixed vector dimensions are forbidden' USING ERRCODE='22000'; END IF;
  RETURN NEW;
END $$;


--
-- Name: validate_image_generation_attempt(); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.validate_image_generation_attempt() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $$
DECLARE original_task ai_tasks; connection model_route_versions; config model_route_configs; contract task_contract_versions; recipe prompt_recipe_versions; snapshot model_route_snapshots;
BEGIN
 SELECT * INTO original_task FROM ai_tasks WHERE id=NEW.task_id;
 IF original_task.source_kind<>'image_generation' THEN
  IF NEW.image_freeze IS NOT NULL THEN RAISE EXCEPTION 'image freeze on unrelated attempt' USING ERRCODE='23514'; END IF; RETURN NEW;
 END IF;
 SELECT * INTO connection FROM model_route_versions WHERE id=(NEW.image_freeze->>'connectionVersionId')::uuid;
 SELECT * INTO config FROM model_route_configs WHERE id=connection.config_id;
 SELECT * INTO contract FROM task_contract_versions WHERE id=NEW.task_contract_version_id;
 SELECT * INTO recipe FROM prompt_recipe_versions WHERE id=NEW.prompt_recipe_version_id;
 SELECT * INTO snapshot FROM model_route_snapshots WHERE id=NEW.model_route_snapshot_id;
 IF NEW.image_freeze IS NULL OR NEW.attempt_number<>1 OR NEW.trigger_kind<>'initial' OR NEW.status<>'running' OR
    NEW.image_freeze->>'protocol' IS DISTINCT FROM 'openai_images_b64_v1' OR NEW.image_freeze->>'connectionHash' IS DISTINCT FROM connection.content_hash::text OR NEW.image_freeze->'input'->>'connectionVersionId' IS DISTINCT FROM connection.id::text OR
    config.scope IS DISTINCT FROM 'task_group' OR config.task_group IS DISTINCT FROM 'image_generation' OR config.task_key IS NOT NULL OR
    connection.status NOT IN ('published','superseded') OR connection.provider IS DISTINCT FROM 'openai-compatible' OR
    connection.required_capabilities IS DISTINCT FROM ARRAY['image_generation','image_base64']::text[] OR connection.parameters->>'imageProtocol' IS DISTINCT FROM 'openai_images_b64_v1' OR
    contract.task_group IS DISTINCT FROM 'image_generation' OR contract.budget_policy->>'assetId' IS DISTINCT FROM 'new_design.image.generate' OR contract.budget_policy->>'assetVersion' IS DISTINCT FROM 'v1' OR
    recipe.variables_schema->'const' IS DISTINCT FROM NEW.image_freeze->'input' OR contract.input_schema->'const' IS DISTINCT FROM NEW.image_freeze->'input' OR
    NEW.image_freeze->'input'->>'bookId' IS DISTINCT FROM original_task.book_id::text OR NEW.image_freeze->'input'->>'requestKey' IS DISTINCT FROM original_task.request_idempotency_key OR
    NEW.input_hash IS DISTINCT FROM original_task.request_hash OR snapshot.book_id IS DISTINCT FROM original_task.book_id OR snapshot.task_contract_version_id IS DISTINCT FROM contract.id OR
    snapshot.required_capabilities IS DISTINCT FROM ARRAY['image_generation','image_base64']::text[] OR snapshot.provider IS DISTINCT FROM connection.provider OR snapshot.model IS DISTINCT FROM connection.model OR
    snapshot.parameters IS DISTINCT FROM connection.parameters OR snapshot.credential_ref_id IS DISTINCT FROM connection.credential_ref_id OR snapshot.retry_policy IS DISTINCT FROM '{"maxRetries":0,"retryDelayMs":0}'::jsonb OR snapshot.budget_policy IS DISTINCT FROM '{"maxImages":1}'::jsonb OR
    recipe.variables_schema->'x-image-generation'->>'requestId' IS DISTINCT FROM original_task.id::text OR
    NOT EXISTS(SELECT 1 FROM task_contracts c WHERE c.id=contract.contract_id AND c.task_key='image_generation_'||original_task.id::text) OR
    snapshot.source_layers IS DISTINCT FROM jsonb_build_array(jsonb_build_object('scope','task_group','configId',config.id,'versionId',connection.id)) OR
    NOT EXISTS(SELECT 1 FROM ai_task_steps s WHERE s.id=NEW.step_id AND s.task_id=original_task.id AND s.max_attempts=1) OR
    NOT EXISTS(SELECT 1 FROM context_manifests m WHERE m.id=NEW.context_manifest_id AND m.book_id=original_task.book_id AND m.model_route_snapshot_id=snapshot.id AND m.task_contract_version_id=contract.id AND m.prompt_recipe_version_id=recipe.id) OR
    EXISTS(SELECT 1 FROM model_route_fallbacks f WHERE f.route_version_id=connection.id) THEN
  RAISE EXCEPTION 'image generation requires exact original connection and frozen single attempt' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: validate_image_generation_evidence(); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.validate_image_generation_evidence() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $_$
BEGIN
 IF NEW.reason_code NOT IN ('image_generation_sent','image_generation_reply') THEN
  IF NEW.image_reply IS NOT NULL THEN RAISE EXCEPTION 'unexpected image reply evidence' USING ERRCODE='23514'; END IF; RETURN NEW;
 END IF;
 IF NEW.entity_kind<>'attempt' OR NEW.to_status<>'running' OR NOT EXISTS(
  SELECT 1 FROM ai_tasks t JOIN ai_task_attempts a ON a.task_id=t.id JOIN ai_task_steps s ON s.id=a.step_id
  WHERE t.id=NEW.task_id AND t.source_kind='image_generation' AND t.status='running' AND a.id=NEW.attempt_id AND a.step_id=NEW.step_id AND a.status='running' AND a.image_freeze IS NOT NULL AND s.current_attempt_id=a.id AND s.status='running' AND (NEW.reason_code='image_generation_reply' OR s.lease_expires_at>now())
 ) THEN RAISE EXCEPTION 'image evidence requires original active attempt lease' USING ERRCODE='23514'; END IF;
 IF NEW.reason_code='image_generation_sent' AND NEW.image_reply IS NOT NULL THEN RAISE EXCEPTION 'dispatch evidence cannot invent a reply' USING ERRCODE='23514'; END IF;
 IF NEW.reason_code='image_generation_reply' AND (NEW.image_reply IS NULL OR NOT EXISTS(SELECT 1 FROM ai_task_state_events e WHERE e.attempt_id=NEW.attempt_id AND e.reason_code='image_generation_sent') OR
  jsonb_typeof(NEW.image_reply->'base64') IS DISTINCT FROM 'string' OR length(NEW.image_reply->>'base64') NOT BETWEEN 4 AND 13981016 OR jsonb_typeof(NEW.image_reply->'mimeType') IS DISTINCT FROM 'string' OR NEW.image_reply->>'mimeType' NOT IN ('image/png','image/jpeg','image/webp') OR
  jsonb_typeof(NEW.image_reply->'checksum') IS DISTINCT FROM 'string' OR NEW.image_reply->>'checksum' !~ '^[a-f0-9]{64}$' OR jsonb_typeof(NEW.image_reply->'byteSize') IS DISTINCT FROM 'number' OR (NEW.image_reply->>'byteSize')::bigint NOT BETWEEN 1 AND 10485760) THEN RAISE EXCEPTION 'image reply requires bounded original base64 evidence' USING ERRCODE='23514'; END IF;
 IF NEW.reason_code='image_generation_reply' AND (NEW.image_reply->>'base64' !~ '^(?:[A-Za-z0-9+/]{4})*(?:[A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=)?$' OR
  octet_length(decode(NEW.image_reply->>'base64','base64')) IS DISTINCT FROM (NEW.image_reply->>'byteSize')::bigint OR
  encode(pg_catalog.sha256(decode(NEW.image_reply->>'base64','base64')),'hex') IS DISTINCT FROM NEW.image_reply->>'checksum') THEN
  RAISE EXCEPTION 'image reply bytes require exact checksum and size' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $_$;


--
-- Name: validate_knowledge_embedding_freeze(jsonb, uuid); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.validate_knowledge_embedding_freeze(frozen jsonb, profile_id uuid) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $_$
DECLARE profile embedding_profile_versions%ROWTYPE; connection model_route_versions%ROWTYPE; config model_route_configs%ROWTYPE;
BEGIN
 IF jsonb_typeof(frozen) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'invalid embedding freeze' USING ERRCODE='23514'; END IF;
 SELECT * INTO profile FROM embedding_profile_versions WHERE id=validate_knowledge_embedding_freeze.profile_id;
 SELECT * INTO connection FROM model_route_versions WHERE id=(frozen->>'connectionVersionId')::uuid;
 SELECT * INTO config FROM model_route_configs WHERE id=connection.config_id;
 IF profile.id IS NULL OR connection.id IS NULL OR profile.connection_version_id IS DISTINCT FROM connection.id
 OR config.scope IS DISTINCT FROM 'task_group' OR config.task_group IS DISTINCT FROM 'knowledge_embedding' OR config.task_key IS NOT NULL
 OR connection.status NOT IN ('published','superseded') OR connection.required_capabilities IS DISTINCT FROM ARRAY['embedding']::text[]
 OR profile.provider_key IS DISTINCT FROM connection.provider OR profile.model_key IS DISTINCT FROM connection.model
 OR frozen->>'profileVersionId' IS DISTINCT FROM profile.id::text OR frozen->>'profileHash' IS DISTINCT FROM profile.content_hash::text
 OR frozen->>'connectionHash' IS DISTINCT FROM connection.content_hash::text OR frozen->>'provider' IS DISTINCT FROM connection.provider
 OR frozen->>'model' IS DISTINCT FROM connection.model OR (frozen->>'dimensions')::integer IS DISTINCT FROM profile.dimensions
 OR coalesce(frozen->>'inputHash','') !~ '^[a-f0-9]{64}$' THEN RAISE EXCEPTION 'embedding freeze does not resolve exact configuration' USING ERRCODE='23514'; END IF;
END $_$;


--
-- Name: validate_outbox_inbox_receipt(); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.validate_outbox_inbox_receipt() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $$
DECLARE expected_hash char(64); job_handler text; consumer_handler text; stored_outcome text;
BEGIN
  SELECT event.payload_hash,job.handler_key INTO expected_hash,job_handler FROM background_jobs job JOIN outbox_events event ON event.id=job.outbox_event_id WHERE job.id=NEW.job_id AND event.id=NEW.event_id;
  SELECT handler_key INTO consumer_handler FROM outbox_consumers WHERE consumer_key=NEW.consumer_key;
  IF expected_hash IS NULL OR expected_hash IS DISTINCT FROM NEW.event_payload_hash OR job_handler IS DISTINCT FROM consumer_handler THEN RAISE EXCEPTION 'inbox receipt does not match event or consumer handler' USING ERRCODE='23514'; END IF;
  IF NEW.result_id IS NULL THEN
    IF NEW.outcome<>'cancelled' THEN RAISE EXCEPTION 'non-cancelled inbox receipt requires a result' USING ERRCODE='23514'; END IF;
  ELSE
    SELECT outcome INTO stored_outcome FROM background_job_results WHERE id=NEW.result_id AND job_id=NEW.job_id;
    IF (CASE stored_outcome WHEN 'applied' THEN 'succeeded' ELSE stored_outcome END) IS DISTINCT FROM NEW.outcome THEN RAISE EXCEPTION 'inbox receipt outcome does not match result' USING ERRCODE='23514'; END IF;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: validate_outbox_scope(); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.validate_outbox_scope() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $$
BEGIN
  IF NEW.space_id IS NULL THEN RAISE EXCEPTION 'outbox runtime record requires a space' USING ERRCODE='23514'; END IF;
  IF NEW.book_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM books WHERE id=NEW.book_id AND space_id=NEW.space_id) THEN RAISE EXCEPTION 'outbox runtime book and space mismatch' USING ERRCODE='23514'; END IF;
  IF TG_TABLE_NAME='outbox_events' AND NOT EXISTS(SELECT 1 FROM outbox_aggregate_sequences aggregate_row WHERE aggregate_row.aggregate_kind=NEW.aggregate_kind AND aggregate_row.aggregate_id=NEW.aggregate_id AND aggregate_row.space_id=NEW.space_id AND aggregate_row.book_id IS NOT DISTINCT FROM NEW.book_id AND aggregate_row.last_sequence>=(to_jsonb(NEW)->>'aggregate_sequence')::bigint) THEN RAISE EXCEPTION 'outbox event aggregate sequence mismatch' USING ERRCODE='23514'; END IF;
  RETURN NEW;
END $$;


--
-- Name: validate_planning_object_hierarchy(); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.validate_planning_object_hierarchy() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $$
DECLARE parent_level text; card_level text;
BEGIN
  IF NEW.level='story' THEN RETURN NEW; END IF;
  SELECT level INTO parent_level FROM new_design.planning_objects WHERE id=NEW.parent_object_id AND book_id=NEW.book_id;
  IF parent_level IS NULL OR (NEW.level='volume' AND parent_level<>'story') OR (NEW.level='chapter' AND parent_level<>'volume') OR (NEW.level='scene' AND parent_level<>'chapter') THEN
    RAISE EXCEPTION 'invalid planning hierarchy' USING ERRCODE='23514';
  END IF;
  SELECT type.type_key INTO card_level FROM new_design.books book JOIN new_design.cards card ON card.space_id=book.space_id AND card.id=NEW.card_id JOIN new_design.card_types type ON type.id=card.card_type_id WHERE book.id=NEW.book_id;
  IF card_level IS DISTINCT FROM NEW.level THEN RAISE EXCEPTION 'planning card type mismatch' USING ERRCODE='23514'; END IF;
  RETURN NEW;
END $$;


--
-- Name: validate_planning_version_reference(); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.validate_planning_version_reference() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $$
DECLARE source_space uuid; target_space uuid; type_key_value text;
BEGIN
  SELECT card.space_id,type.type_key INTO source_space,type_key_value
  FROM new_design.cards card
  JOIN new_design.card_types type ON type.id=card.card_type_id
  WHERE card.id=NEW.card_id AND card.status='active' AND card.current_version_id=NEW.card_version_id;
  SELECT space_id INTO target_space FROM new_design.books WHERE id=NEW.book_id AND status='active';
  IF source_space IS NULL OR target_space IS NULL OR source_space IS DISTINCT FROM target_space THEN
    RAISE EXCEPTION 'planning reference must use the current version of an active card from the same book' USING ERRCODE='23514';
  END IF;
  IF NEW.reference_role='viewpoint' AND type_key_value<>'character' THEN
    RAISE EXCEPTION 'viewpoint reference must target a character' USING ERRCODE='23514';
  ELSIF NEW.reference_role='location' AND type_key_value<>'location' THEN
    RAISE EXCEPTION 'location reference must target a location' USING ERRCODE='23514';
  ELSIF NEW.reference_role='participant' AND type_key_value<>'character' THEN
    RAISE EXCEPTION 'participant reference must target a character' USING ERRCODE='23514';
  ELSIF NEW.reference_role='event' AND type_key_value<>'event' THEN
    RAISE EXCEPTION 'event reference must target an event' USING ERRCODE='23514';
  ELSIF NEW.reference_role='foreshadow' AND type_key_value NOT IN ('foreshadow','clue') THEN
    RAISE EXCEPTION 'foreshadow reference must target a clue or foreshadow item' USING ERRCODE='23514';
  ELSIF NEW.reference_role='item' AND type_key_value<>'prop' THEN
    RAISE EXCEPTION 'item reference must target an item' USING ERRCODE='23514';
  ELSIF NEW.reference_role='organization' AND type_key_value<>'organization' THEN
    RAISE EXCEPTION 'organization reference must target an organization' USING ERRCODE='23514';
  END IF;
  IF NEW.reference_role='foreshadow' AND NEW.action_key IS NULL THEN
    RAISE EXCEPTION 'foreshadow reference requires an action' USING ERRCODE='23514';
  ELSIF NEW.reference_role<>'foreshadow' AND NEW.action_key IS NOT NULL THEN
    RAISE EXCEPTION 'only foreshadow references accept an action' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: validate_production_director_chapter_scope(); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.validate_production_director_chapter_scope() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $$
BEGIN
  IF NOT EXISTS(SELECT 1 FROM planning_objects object WHERE object.id=NEW.planning_object_id AND object.book_id=NEW.book_id AND object.card_id=NEW.chapter_card_id AND object.level='chapter') THEN RAISE EXCEPTION 'director target chapter scope mismatch' USING ERRCODE='23514'; END IF;
  IF NEW.current_request_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM chapter_writing_requests request JOIN chapter_documents document ON document.id=request.chapter_document_id WHERE request.id=NEW.current_request_id AND request.book_id=NEW.book_id AND document.chapter_card_id=NEW.chapter_card_id AND request.planning_object_id=NEW.planning_object_id AND request.planning_version_id=NEW.planning_version_id AND request.idempotency_key=NEW.current_request_key::text AND request.controlled_snapshot IS NOT NULL) THEN RAISE EXCEPTION 'director original request scope mismatch' USING ERRCODE='23514'; END IF;
  RETURN NEW;
END $$;


--
-- Name: validate_publication_export_request(); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.validate_publication_export_request() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $$
DECLARE manifest_row publication_export_manifests%ROWTYPE;
BEGIN
  SELECT * INTO manifest_row FROM publication_export_manifests WHERE id=NEW.manifest_id;
  IF NOT FOUND OR manifest_row.book_id IS DISTINCT FROM NEW.book_id THEN RAISE EXCEPTION 'export request and manifest book mismatch' USING ERRCODE='23514'; END IF;
  IF manifest_row.export_mode='formal' AND manifest_row.completion_snapshot_id IS NULL THEN RAISE EXCEPTION 'formal export requires a completion snapshot' USING ERRCODE='23514'; END IF;
  IF EXISTS(SELECT 1 FROM publication_export_manifest_chapters binding JOIN chapter_documents document ON document.id=binding.chapter_document_id LEFT JOIN chapter_stable_checkpoints checkpoint ON checkpoint.id=binding.stable_checkpoint_id WHERE binding.manifest_id=manifest_row.id AND (document.adopted_version_id IS DISTINCT FROM binding.body_version_id OR (manifest_row.export_mode='formal' AND (checkpoint.id IS NULL OR checkpoint.status<>'stable')))) THEN RAISE EXCEPTION 'export manifest source versions changed before submission' USING ERRCODE='40001'; END IF;
  RETURN NEW;
END $$;


--
-- Name: validate_publication_manifest(); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.validate_publication_manifest() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $$
BEGIN
  IF NEW.completion_snapshot_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM book_completion_snapshots snapshot WHERE snapshot.id=NEW.completion_snapshot_id AND snapshot.book_id=NEW.book_id) THEN RAISE EXCEPTION 'completion snapshot and export manifest book mismatch' USING ERRCODE='23514'; END IF;
  IF NEW.export_mode='formal' AND NEW.completion_snapshot_id IS NULL THEN RAISE EXCEPTION 'formal export requires a completion snapshot' USING ERRCODE='23514'; END IF;
  RETURN NEW;
END $$;


--
-- Name: validate_publication_manifest_chapter(); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.validate_publication_manifest_chapter() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $$
BEGIN
  IF NOT EXISTS(SELECT 1 FROM publication_export_manifests manifest JOIN chapter_documents document ON document.book_id=manifest.book_id AND document.id=NEW.chapter_document_id JOIN chapter_body_versions body ON body.id=NEW.body_version_id AND body.chapter_document_id=document.id LEFT JOIN chapter_stable_checkpoints checkpoint ON checkpoint.id=NEW.stable_checkpoint_id AND checkpoint.chapter_document_id=document.id AND checkpoint.body_version_id=body.id WHERE manifest.id=NEW.manifest_id AND body.content_hash=NEW.body_hash AND (NEW.stable_checkpoint_id IS NULL OR checkpoint.id IS NOT NULL)) THEN RAISE EXCEPTION 'export chapter binding is outside the manifest book or hash' USING ERRCODE='23514'; END IF;
  RETURN NEW;
END $$;


--
-- Name: validate_resource_supplement_correction_origin(); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.validate_resource_supplement_correction_origin() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $$
DECLARE origin chapter_resource_supplements%ROWTYPE; child chapter_adoption_sessions%ROWTYPE;
  issue resource_supplement_integrity_issues%ROWTYPE; base chapter_stable_checkpoints%ROWTYPE;
  source jsonb; correction jsonb; actual_prefix jsonb; related jsonb; field jsonb; prefix_order integer;
BEGIN
  -- stable_resource_correction_start_v1: creation only; no candidate or resolution permission.
  SELECT * INTO origin FROM chapter_resource_supplements WHERE session_id=NEW.session_id AND book_id=NEW.book_id;
  SELECT * INTO child FROM chapter_adoption_sessions WHERE id=NEW.session_id AND book_id=NEW.book_id;
  SELECT * INTO issue FROM resource_supplement_integrity_issues WHERE issue_id=NEW.issue_id AND book_id=NEW.book_id;
  SELECT * INTO base FROM chapter_stable_checkpoints WHERE id=origin.base_checkpoint_id AND book_id=NEW.book_id AND status='stable';
  source:=origin.source_snapshot; correction:=source->'correction';
  IF origin.session_id IS NULL OR child.id IS NULL OR issue.issue_id IS NULL OR base.id IS NULL
    OR child.status IS DISTINCT FROM 'adopted_pending_proposals' OR child.adoption_kind IS DISTINCT FROM 'resource_supplement'
    OR base.chapter_document_id IS DISTINCT FROM issue.chapter_document_id OR base.body_version_id IS DISTINCT FROM issue.body_version_id
    OR child.chapter_document_id IS DISTINCT FROM issue.chapter_document_id OR child.body_version_id IS DISTINCT FROM issue.body_version_id
    OR NOT EXISTS(SELECT 1 FROM books WHERE id=NEW.book_id AND status='active')
    OR NOT EXISTS(SELECT 1 FROM chapter_documents WHERE id=issue.chapter_document_id AND book_id=NEW.book_id AND status='active' AND adopted_version_id=issue.body_version_id)
    OR EXISTS(SELECT 1 FROM resource_supplement_integrity_resolutions WHERE issue_id=NEW.issue_id)
    OR EXISTS(SELECT 1 FROM chapter_adoption_sessions WHERE chapter_document_id=issue.chapter_document_id AND id<>child.id
      AND status IN ('reviewing','adopted_pending_proposals','pending_review','partially_confirmed','settling','failed'))
    OR source->>'contract' IS DISTINCT FROM 'stable_resource_correction_preview_v1'
    OR origin.original_receipt->>'contract' IS DISTINCT FROM 'stable_resource_correction_start_v1'
    OR origin.full_input->>'issueId' IS DISTINCT FROM NEW.issue_id::text
    OR origin.original_receipt->>'issueId' IS DISTINCT FROM NEW.issue_id::text
    OR source->'input' IS DISTINCT FROM jsonb_build_object('issueId',NEW.issue_id,'resourceScope',origin.full_input->'resourceScope')
    OR NEW.canonical_input::jsonb IS DISTINCT FROM jsonb_build_object('contract','stable_resource_correction_start_v1','bookId',NEW.book_id,'input',origin.full_input)
    OR encode(sha256(convert_to(NEW.canonical_input,'UTF8')),'hex') IS DISTINCT FROM origin.input_hash::text
    OR NEW.canonical_source::jsonb IS DISTINCT FROM source-'sourceHash'
    OR encode(sha256(convert_to(NEW.canonical_source,'UTF8')),'hex') IS DISTINCT FROM origin.source_hash::text
    OR correction->>'contract' IS DISTINCT FROM 'resource_supplement_correction_basis_v1'
    OR correction->>'bookId' IS DISTINCT FROM NEW.book_id::text OR correction->>'issueId' IS DISTINCT FROM NEW.issue_id::text
    OR correction->>'baseCheckpointId' IS DISTINCT FROM base.id::text
    OR correction->>'chapterDocumentId' IS DISTINCT FROM issue.chapter_document_id::text
    OR correction->>'bodyVersionId' IS DISTINCT FROM issue.body_version_id::text
    OR correction->>'subjectKind' IS DISTINCT FROM issue.subject_kind OR correction->>'subjectId' IS DISTINCT FROM issue.subject_id::text
    OR correction->>'stateKey' IS DISTINCT FROM issue.state_key
    OR correction->'issue' IS DISTINCT FROM to_jsonb(issue)||jsonb_build_object('current_checkpoint',to_jsonb(base))
    OR correction->'chapterEndBasis' IS DISTINCT FROM source->'basis'
    OR correction->'originalRecordedBefore' IS DISTINCT FROM issue.impact->'recordedBefore'
    OR correction->'originalRecordedAfter' IS DISTINCT FROM issue.impact->'recordedAfter'
    OR origin.original_receipt->>'sourceRoute' IS DISTINCT FROM '/new-design/books/'||NEW.book_id||'/writing?chapterDocument='||issue.chapter_document_id||'&session='||NEW.session_id||'&resourceIssue='||NEW.issue_id
    THEN RAISE EXCEPTION 'correction original input, issue or current body mismatch' USING ERRCODE='23514'; END IF;
  SELECT jsonb_build_object('change',to_jsonb(change),'proposal',to_jsonb(proposal),'settlement',to_jsonb(settlement),
    'anchor',to_jsonb(anchor),'document',to_jsonb(document),'body',to_jsonb(body),'checkpoint',to_jsonb(checkpoint),
    'checkpoint_commit',to_jsonb(checkpoint_commit),'checkpoint_session',to_jsonb(checkpoint_session)),document.logical_order
    INTO actual_prefix,prefix_order FROM state_changes change
    JOIN chapter_documents document ON document.id=change.chapter_document_id AND document.book_id=change.book_id AND document.status='active' AND document.adopted_version_id=change.body_version_id
    LEFT JOIN state_change_proposals proposal ON proposal.id=change.proposal_id
    LEFT JOIN chapter_settlements settlement ON settlement.id=change.settlement_id
    LEFT JOIN chapter_text_anchors anchor ON anchor.id=change.text_anchor_id
    LEFT JOIN chapter_body_versions body ON body.id=change.body_version_id AND body.chapter_document_id=document.id
    LEFT JOIN chapter_stable_checkpoints checkpoint ON checkpoint.book_id=change.book_id AND checkpoint.chapter_document_id=document.id AND checkpoint.body_version_id=change.body_version_id AND checkpoint.status='stable'
    LEFT JOIN chapter_settlements checkpoint_commit ON checkpoint_commit.id=checkpoint.settlement_id
    LEFT JOIN chapter_adoption_sessions checkpoint_session ON checkpoint_session.id=checkpoint.session_id
    WHERE change.book_id=NEW.book_id AND change.subject_kind=issue.subject_kind AND change.subject_id=issue.subject_id AND change.state_key=issue.state_key AND change.status='active'
      AND document.logical_order<base.chapter_order AND coalesce(change.effective_story_order,document.logical_order)<base.chapter_order
    ORDER BY coalesce(change.effective_story_order,document.logical_order) DESC,document.logical_order DESC,change.sequence DESC LIMIT 1;
  IF actual_prefix IS NULL OR correction->'prefixSource' IS DISTINCT FROM actual_prefix
    OR correction->'beforeValue' IS DISTINCT FROM actual_prefix->'change'->'after_json'
    OR actual_prefix->'proposal'->>'status' IS DISTINCT FROM 'confirmed'
    OR actual_prefix->'proposal'->>'book_id' IS DISTINCT FROM NEW.book_id::text
    OR actual_prefix->'proposal'->>'chapter_document_id' IS DISTINCT FROM actual_prefix->'change'->>'chapter_document_id'
    OR actual_prefix->'proposal'->>'body_version_id' IS DISTINCT FROM actual_prefix->'change'->>'body_version_id'
    OR actual_prefix->'proposal'->>'subject_kind' IS DISTINCT FROM issue.subject_kind
    OR actual_prefix->'proposal'->>'subject_id' IS DISTINCT FROM issue.subject_id::text
    OR actual_prefix->'proposal'->>'state_key' IS DISTINCT FROM issue.state_key
    OR actual_prefix->'proposal'->>'confirmed_state_change_id' IS DISTINCT FROM actual_prefix->'change'->>'id'
    OR actual_prefix->'proposal'->'before_json' IS DISTINCT FROM actual_prefix->'change'->'before_json'
    OR actual_prefix->'proposal'->'after_json' IS DISTINCT FROM actual_prefix->'change'->'after_json'
    OR actual_prefix->'settlement'->>'status' IS DISTINCT FROM 'committed'
    OR actual_prefix->'settlement'->>'book_id' IS DISTINCT FROM NEW.book_id::text
    OR actual_prefix->'settlement'->>'chapter_document_id' IS DISTINCT FROM actual_prefix->'change'->>'chapter_document_id'
    OR actual_prefix->'settlement'->>'body_version_id' IS DISTINCT FROM actual_prefix->'change'->>'body_version_id'
    OR actual_prefix->'body'->'archived_at' IS DISTINCT FROM 'null'::jsonb
    OR encode(sha256(convert_to(actual_prefix->'body'->>'content','UTF8')),'hex') IS DISTINCT FROM actual_prefix->'body'->>'content_hash'
    OR actual_prefix->'checkpoint_commit'->>'status' IS DISTINCT FROM 'committed'
    OR actual_prefix->'checkpoint_commit'->>'book_id' IS DISTINCT FROM NEW.book_id::text
    OR actual_prefix->'checkpoint_commit'->>'chapter_document_id' IS DISTINCT FROM actual_prefix->'change'->>'chapter_document_id'
    OR actual_prefix->'checkpoint_commit'->>'body_version_id' IS DISTINCT FROM actual_prefix->'change'->>'body_version_id'
    OR actual_prefix->'checkpoint_session'->>'status' IS DISTINCT FROM 'stable'
    OR actual_prefix->'checkpoint_session'->>'book_id' IS DISTINCT FROM NEW.book_id::text
    OR actual_prefix->'checkpoint_session'->>'chapter_document_id' IS DISTINCT FROM actual_prefix->'change'->>'chapter_document_id'
    OR actual_prefix->'checkpoint_session'->>'body_version_id' IS DISTINCT FROM actual_prefix->'change'->>'body_version_id'
    OR actual_prefix->'checkpoint_session'->>'settlement_id' IS DISTINCT FROM actual_prefix->'checkpoint_commit'->>'id'
    OR NOT coalesce((actual_prefix->'checkpoint'->'summary'->'confirmed'->'states') ? (actual_prefix->'change'->>'id'),false)
    OR (SELECT count(*) FROM jsonb_array_elements_text(actual_prefix->'checkpoint'->'summary'->'confirmed'->'states'))
      IS DISTINCT FROM (SELECT count(DISTINCT value) FROM jsonb_array_elements_text(actual_prefix->'checkpoint'->'summary'->'confirmed'->'states'))
    OR actual_prefix->'change'->'text_anchor_id'<>'null'::jsonb AND (actual_prefix->'anchor'->>'status' IS DISTINCT FROM 'active'
      OR actual_prefix->'anchor'->>'book_id' IS DISTINCT FROM NEW.book_id::text
      OR actual_prefix->'anchor'->>'chapter_document_id' IS DISTINCT FROM actual_prefix->'change'->>'chapter_document_id'
      OR actual_prefix->'anchor'->>'body_version_id' IS DISTINCT FROM actual_prefix->'change'->>'body_version_id')
    OR EXISTS(SELECT 1 FROM resource_supplement_integrity_issues earlier JOIN chapter_documents document ON document.id=earlier.chapter_document_id
      WHERE earlier.book_id=NEW.book_id AND earlier.subject_kind=issue.subject_kind AND earlier.subject_id=issue.subject_id AND document.logical_order<=prefix_order
        AND NOT EXISTS(SELECT 1 FROM resource_supplement_integrity_resolutions WHERE issue_id=earlier.issue_id))
    THEN RAISE EXCEPTION 'correction must retain the actual valid latest chapter-before proof' USING ERRCODE='23514'; END IF;
  SELECT coalesce(jsonb_agg(to_jsonb(actual) ORDER BY document.logical_order,actual.issue_id),'[]'::jsonb) INTO related
    FROM resource_supplement_integrity_issues actual JOIN chapter_documents document ON document.id=actual.chapter_document_id AND document.book_id=actual.book_id
    WHERE actual.book_id=NEW.book_id AND document.logical_order<=base.chapter_order AND NOT EXISTS(
      SELECT 1 FROM resource_supplement_integrity_resolutions WHERE issue_id=actual.issue_id)
    AND ((actual.subject_kind='card' AND (origin.full_input->'resourceScope'->'resourceIds') ? actual.subject_id::text)
      OR (actual.subject_kind='relation' AND (origin.full_input->'resourceScope'->'relationIds') ? actual.subject_id::text));
  IF related IS DISTINCT FROM source->'relatedIssues' OR NOT related @> jsonb_build_array(to_jsonb(issue))
    OR EXISTS(SELECT 1 FROM jsonb_array_elements(related) item WHERE item->>'chapter_document_id' IS DISTINCT FROM issue.chapter_document_id::text
      OR item->>'body_version_id' IS DISTINCT FROM issue.body_version_id::text OR item->>'subject_kind' IS DISTINCT FROM issue.subject_kind
      OR item->>'subject_id' IS DISTINCT FROM issue.subject_id::text OR item->>'state_key' IS DISTINCT FROM issue.state_key)
    OR origin.original_receipt->'relatedIssueIds' IS DISTINCT FROM (SELECT jsonb_agg(item->'issue_id') FROM jsonb_array_elements(related) item)
    THEN RAISE EXCEPTION 'correction must retain every selected actual related issue' USING ERRCODE='23514'; END IF;
  SELECT item INTO field FROM jsonb_array_elements(source->'catalog'->'subjects') subject,
    jsonb_array_elements(subject->'fields') item WHERE subject->>'subjectKind'=issue.subject_kind AND subject->>'id'=issue.subject_id::text AND item->>'key'=issue.state_key;
  IF field IS NULL OR field->'baseline'->'known' IS DISTINCT FROM 'true'::jsonb OR field->'baseline'->'stale' IS DISTINCT FROM 'false'::jsonb
    OR field->'baseline'->'value' IS DISTINCT FROM correction->'beforeValue'
    OR field->'baseline'->>'sourceKind' IS DISTINCT FROM 'state_change'
    OR field->'baseline'->>'sourceId' IS DISTINCT FROM actual_prefix->'change'->>'id'
    OR NOT EXISTS(SELECT 1 FROM chapter_adoption_preparations WHERE id=child.preparation_id AND dependency_snapshot->>'correctionIssueId'=issue.issue_id::text
      AND dependency_snapshot->'correctionIssueIds'=origin.original_receipt->'relatedIssueIds' AND dependency_snapshot->>'correctionSourceHash'=correction->>'sourceHash')
    THEN RAISE EXCEPTION 'correction editor baseline must remain bound to actual chapter-before evidence' USING ERRCODE='23514'; END IF;
  RETURN NEW;
END $$;


--
-- Name: validate_resource_supplement_formal_commit(); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.validate_resource_supplement_formal_commit() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $$
BEGIN
  -- resource_supplement_formal_commit_v1: full actual source proof, never a flag.
  PERFORM assert_resource_supplement_formal_commit_source(NEW);
  RETURN NEW;
END $$;


--
-- Name: validate_resource_supplement_impact_review(); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.validate_resource_supplement_impact_review() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $$
DECLARE session chapter_adoption_sessions%ROWTYPE; base chapter_stable_checkpoints%ROWTYPE;
  snapshot jsonb; actual jsonb; origin chapter_resource_supplements%ROWTYPE;
  conflicts jsonb; acknowledged jsonb; field_values jsonb:='{}'::jsonb; field_key text;
  expected_chain jsonb:='[]'::jsonb; before_value jsonb; reason text; effective numeric;
BEGIN
  -- resource_supplement_impact_review_v1: awareness never resolves a conflict.
  IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'impact review history is immutable' USING ERRCODE='23514'; END IF;
  SELECT * INTO session FROM chapter_adoption_sessions WHERE id=NEW.session_id AND book_id=NEW.book_id;
  SELECT * INTO origin FROM chapter_resource_supplements WHERE session_id=session.id AND book_id=NEW.book_id;
  SELECT * INTO base FROM chapter_stable_checkpoints WHERE id=origin.base_checkpoint_id AND book_id=NEW.book_id;
  IF origin.source_snapshot->>'contract'='stable_resource_correction_preview_v1' THEN
    PERFORM assert_resource_correction_candidate_source(saved) FROM resource_supplement_correction_origins saved WHERE saved.session_id=NEW.session_id AND saved.book_id=NEW.book_id;
    IF NOT FOUND OR jsonb_array_length(NEW.impact_snapshot->'changes')<>1 OR EXISTS(SELECT 1 FROM jsonb_array_elements(NEW.impact_snapshot->'changes') item WHERE item->>'subjectKind' IS DISTINCT FROM origin.source_snapshot#>>'{correction,subjectKind}' OR item->>'subjectId' IS DISTINCT FROM origin.source_snapshot#>>'{correction,subjectId}' OR item->>'stateKey' IS DISTINCT FROM origin.source_snapshot#>>'{correction,stateKey}' OR item->'before' IS DISTINCT FROM origin.source_snapshot#>'{correction,beforeValue}') THEN RAISE EXCEPTION 'corrective review must bind its single actual issue source' USING ERRCODE='23514'; END IF;
  END IF;
  IF session.id IS NULL OR session.adoption_kind<>'resource_supplement' OR session.revision<>NEW.session_revision
    OR session.status NOT IN ('pending_review','partially_confirmed','adopted_pending_proposals','failed')
    OR base.id IS NULL OR base.status<>'stable'
    OR NOT EXISTS(SELECT 1 FROM books WHERE id=NEW.book_id AND status='active')
    OR NOT EXISTS(SELECT 1 FROM chapter_documents WHERE id=session.chapter_document_id AND book_id=NEW.book_id AND status='active' AND adopted_version_id=session.body_version_id)
    OR NEW.canonical_input::jsonb IS DISTINCT FROM jsonb_build_object('contract','resource_supplement_impact_review_v1','bookId',NEW.book_id,'sessionId',NEW.session_id,'input',NEW.full_input)
    OR encode(sha256(convert_to(NEW.canonical_input,'UTF8')),'hex') IS DISTINCT FROM NEW.input_hash::text
    OR NEW.canonical_impact::jsonb IS DISTINCT FROM NEW.impact_snapshot-'impactHash'
    OR encode(sha256(convert_to(NEW.canonical_impact,'UTF8')),'hex') IS DISTINCT FROM NEW.impact_hash::text
    OR NEW.impact_snapshot->>'contract' IS DISTINCT FROM 'resource_supplement_settlement_impact_v1'
    OR NEW.impact_snapshot->>'bookId' IS DISTINCT FROM NEW.book_id::text
    OR NEW.impact_snapshot->>'sessionId' IS DISTINCT FROM NEW.session_id::text
    OR NEW.impact_snapshot->>'baseCheckpointId' IS DISTINCT FROM base.id::text
    OR NEW.impact_snapshot->>'bodyVersionId' IS DISTINCT FROM session.body_version_id::text
    OR NEW.impact_snapshot->>'sessionRevision' IS DISTINCT FROM NEW.session_revision::text
    OR NEW.impact_snapshot->>'sourceHash' IS DISTINCT FROM origin.source_hash::text
    -- pg returns session timestamps as JS Dates (millisecond ISO), whereas
    -- to_jsonb uses PostgreSQL timezone formatting and microsecond precision.
    OR (NEW.impact_snapshot#>'{inputSnapshot,session}')-ARRAY['body_hash','created_at','updated_at'] IS DISTINCT FROM to_jsonb(session)-ARRAY['created_at','updated_at']
    OR (NEW.impact_snapshot#>>'{inputSnapshot,session,created_at}')::timestamptz IS DISTINCT FROM date_trunc('milliseconds',session.created_at)
    OR (NEW.impact_snapshot#>>'{inputSnapshot,session,updated_at}')::timestamptz IS DISTINCT FROM date_trunc('milliseconds',session.updated_at)
    OR NEW.impact_snapshot#>'{inputSnapshot,source}' IS DISTINCT FROM origin.source_snapshot
    OR NEW.impact_snapshot->>'impactHash' IS DISTINCT FROM NEW.impact_hash::text
    OR jsonb_typeof(NEW.impact_snapshot->'changes') IS DISTINCT FROM 'array'
    OR jsonb_typeof(NEW.impact_snapshot->'stateChain') IS DISTINCT FROM 'array'
    OR jsonb_typeof(NEW.impact_snapshot#>'{downstreamSource,chapters}') IS DISTINCT FROM 'array'
    OR jsonb_typeof(NEW.impact_snapshot#>'{downstreamSource,states}') IS DISTINCT FROM 'array'
    OR jsonb_typeof(NEW.impact_snapshot#>'{downstreamSource,planningReferences}') IS DISTINCT FROM 'array'
    OR jsonb_typeof(NEW.full_input->'acknowledgedConflictStateChangeIds') IS DISTINCT FROM 'array'
    OR NEW.full_input->>'requestKey' IS DISTINCT FROM NEW.request_key::text
    OR NEW.full_input->>'expectedSessionRevision' IS DISTINCT FROM NEW.session_revision::text
    OR NEW.full_input->>'expectedImpactHash' IS DISTINCT FROM NEW.impact_hash::text
    OR NEW.original_receipt->>'contract' IS DISTINCT FROM 'resource_supplement_impact_review_v1'
    OR NEW.original_receipt->>'reviewId' IS DISTINCT FROM NEW.review_id::text
    OR NEW.original_receipt->>'bookId' IS DISTINCT FROM NEW.book_id::text
    OR NEW.original_receipt->>'sessionId' IS DISTINCT FROM NEW.session_id::text
    OR NEW.original_receipt->>'chapterDocumentId' IS DISTINCT FROM session.chapter_document_id::text
    OR NEW.original_receipt->>'bodyVersionId' IS DISTINCT FROM session.body_version_id::text
    OR NEW.original_receipt->>'baseCheckpointId' IS DISTINCT FROM base.id::text
    OR NEW.original_receipt->>'sessionRevision' IS DISTINCT FROM NEW.session_revision::text
    OR NEW.original_receipt->>'inputHash' IS DISTINCT FROM NEW.input_hash::text
    OR NEW.original_receipt->'input' IS DISTINCT FROM NEW.full_input
    OR NEW.original_receipt->'impact' IS DISTINCT FROM NEW.impact_snapshot
    OR NEW.original_receipt->'repeated' IS DISTINCT FROM 'false'::jsonb
    OR NEW.original_receipt->>'sourceRoute' IS DISTINCT FROM '/new-design/books/'||NEW.book_id||'/writing?chapterDocument='||session.chapter_document_id||'&session='||session.id
    THEN RAISE EXCEPTION 'impact review origin or complete receipt mismatch' USING ERRCODE='23514'; END IF;
  IF EXISTS(SELECT 1 FROM chapter_settlement_items WHERE session_id=session.id AND decision NOT IN ('confirm','reject'))
    OR (SELECT count(*) FROM chapter_settlement_items WHERE session_id=session.id AND decision='confirm')<>jsonb_array_length(NEW.impact_snapshot->'changes')
    OR (SELECT count(DISTINCT value->>'itemId') FROM jsonb_array_elements(NEW.impact_snapshot->'changes'))<>jsonb_array_length(NEW.impact_snapshot->'changes')
    THEN RAISE EXCEPTION 'impact review candidate set incomplete' USING ERRCODE='23514'; END IF;
  FOR snapshot IN SELECT value FROM jsonb_array_elements(NEW.impact_snapshot->'changes') LOOP
    IF NOT EXISTS(SELECT 1 FROM chapter_settlement_items item JOIN state_change_proposals proposal ON proposal.id=item.state_proposal_id
      WHERE item.id=(snapshot->>'itemId')::uuid AND item.session_id=session.id AND item.decision='confirm'
        AND proposal.id=(snapshot->>'proposalId')::uuid AND proposal.book_id=NEW.book_id AND proposal.status='proposed' AND proposal.before_known
        AND proposal.subject_kind=snapshot->>'subjectKind' AND proposal.subject_id=(snapshot->>'subjectId')::uuid AND proposal.state_key=snapshot->>'stateKey'
        AND proposal.before_json IS NOT DISTINCT FROM snapshot->'before' AND proposal.after_json IS NOT DISTINCT FROM snapshot->'after')
      THEN RAISE EXCEPTION 'impact review confirmed proposal mismatch' USING ERRCODE='23514'; END IF;
    field_key=jsonb_build_array(snapshot->>'subjectKind',snapshot->>'subjectId',snapshot->>'stateKey')::text;
    field_values=jsonb_set(field_values,ARRAY[field_key],snapshot->'after');
  END LOOP;
  SELECT coalesce(jsonb_agg(to_jsonb(reference)||jsonb_build_object('source_version',to_jsonb(card_version)) ORDER BY reference.id),'[]'::jsonb) INTO actual
    FROM planning_version_references reference LEFT JOIN card_versions card_version ON card_version.id=reference.card_version_id AND card_version.card_id=reference.card_id
    WHERE reference.book_id=NEW.book_id AND reference.planning_version_id IN (
      SELECT (value#>>'{adopted_plan,id}')::uuid FROM jsonb_array_elements(NEW.impact_snapshot#>'{downstreamSource,chapters}')
      UNION SELECT (value#>>'{body,planning_version_id}')::uuid FROM jsonb_array_elements(NEW.impact_snapshot#>'{downstreamSource,chapters}'));
  IF actual IS DISTINCT FROM NEW.impact_snapshot#>'{downstreamSource,planningReferences}' THEN
    RAISE EXCEPTION 'impact review exact planning references changed' USING ERRCODE='23514'; END IF;
  -- Same authority rule as the preview: keep all rows, use the final row per
  -- chapter/field; preserve that field's first position in the ordered chain.
  FOR snapshot IN
    WITH ordered AS (SELECT value,ordinality,
      row_number() OVER(PARTITION BY value#>>'{change,chapter_document_id}',value#>>'{change,subject_kind}',value#>>'{change,subject_id}',value#>>'{change,state_key}' ORDER BY ordinality DESC) last_position,
      min(ordinality) OVER(PARTITION BY value#>>'{change,chapter_document_id}',value#>>'{change,subject_kind}',value#>>'{change,subject_id}',value#>>'{change,state_key}') first_position
      FROM jsonb_array_elements(NEW.impact_snapshot#>'{downstreamSource,states}') WITH ORDINALITY)
    SELECT value FROM ordered WHERE last_position=1 ORDER BY first_position
  LOOP
    field_key=jsonb_build_array(snapshot#>>'{change,subject_kind}',snapshot#>>'{change,subject_id}',snapshot#>>'{change,state_key}')::text;
    before_value=field_values->field_key;
    effective=(snapshot#>>'{change,effective_story_order}')::numeric;
    reason=CASE WHEN effective IS NOT NULL AND effective<=base.chapter_order THEN 'backdated_source'
      WHEN before_value IS NOT DISTINCT FROM snapshot#>'{change,before_json}' THEN 'compatible' ELSE 'before_conflict' END;
    expected_chain=expected_chain||jsonb_build_array(jsonb_build_object('chapterDocumentId',snapshot#>>'{change,chapter_document_id}',
      'bodyVersionId',snapshot#>>'{change,body_version_id}','chapterOrder',snapshot->'chapter_order','stateChangeId',snapshot#>>'{change,id}',
      'subjectKind',snapshot#>>'{change,subject_kind}','subjectId',snapshot#>>'{change,subject_id}','stateKey',snapshot#>>'{change,state_key}',
      'expectedBefore',before_value,'recordedBefore',snapshot#>'{change,before_json}','recordedAfter',snapshot#>'{change,after_json}',
      'effectiveStoryOrder',effective,'reason',reason));
    field_values=jsonb_set(field_values,ARRAY[field_key],snapshot#>'{change,after_json}');
  END LOOP;
  IF expected_chain IS DISTINCT FROM NEW.impact_snapshot->'stateChain' THEN
    RAISE EXCEPTION 'impact review actual state chain mismatch' USING ERRCODE='23514'; END IF;
  IF (SELECT count(*) FROM chapter_documents WHERE book_id=NEW.book_id AND status='active' AND logical_order>base.chapter_order)
    <>jsonb_array_length(NEW.impact_snapshot#>'{downstreamSource,chapters}')
    OR (SELECT count(DISTINCT value#>>'{document,id}') FROM jsonb_array_elements(NEW.impact_snapshot#>'{downstreamSource,chapters}'))<>jsonb_array_length(NEW.impact_snapshot#>'{downstreamSource,chapters}') THEN
    RAISE EXCEPTION 'impact review downstream chapter set incomplete' USING ERRCODE='23514'; END IF;
  FOR snapshot IN SELECT value FROM jsonb_array_elements(NEW.impact_snapshot#>'{downstreamSource,chapters}') LOOP
    SELECT jsonb_build_object('document',to_jsonb(document),'body',to_jsonb(body),'planning_object',to_jsonb(object),
      'adopted_plan',to_jsonb(plan),'body_plan',to_jsonb(body_plan),'checkpoint',to_jsonb(checkpoint)) INTO actual
      FROM chapter_documents document
      LEFT JOIN chapter_body_versions body ON body.id=document.adopted_version_id AND body.chapter_document_id=document.id AND body.archived_at IS NULL
      LEFT JOIN planning_objects object ON object.book_id=document.book_id AND object.card_id=document.chapter_card_id AND object.level='chapter' AND object.status='active'
      LEFT JOIN planning_versions plan ON plan.id=object.adopted_version_id AND plan.object_id=object.id
      LEFT JOIN planning_versions body_plan ON body_plan.id=body.planning_version_id AND body_plan.book_id=document.book_id
      LEFT JOIN chapter_stable_checkpoints checkpoint ON checkpoint.chapter_document_id=document.id AND checkpoint.book_id=document.book_id AND checkpoint.body_version_id=body.id AND checkpoint.status='stable'
      WHERE document.id=(snapshot#>>'{document,id}')::uuid AND document.book_id=NEW.book_id AND document.status='active' AND document.logical_order>base.chapter_order;
    IF actual IS DISTINCT FROM snapshot THEN RAISE EXCEPTION 'impact review downstream source changed' USING ERRCODE='23514'; END IF;
  END LOOP;
  IF (SELECT count(*) FROM state_changes change
      JOIN chapter_documents document ON document.id=change.chapter_document_id AND document.book_id=change.book_id AND document.status='active' AND document.adopted_version_id=change.body_version_id
      WHERE change.book_id=NEW.book_id AND change.status='active' AND document.logical_order>base.chapter_order
        AND EXISTS(SELECT 1 FROM jsonb_array_elements(NEW.impact_snapshot->'changes') selection
          WHERE selection->>'subjectKind'=change.subject_kind AND (selection->>'subjectId')::uuid=change.subject_id AND selection->>'stateKey'=change.state_key))
    <>jsonb_array_length(NEW.impact_snapshot#>'{downstreamSource,states}')
    OR (SELECT count(DISTINCT value#>>'{change,id}') FROM jsonb_array_elements(NEW.impact_snapshot#>'{downstreamSource,states}'))<>jsonb_array_length(NEW.impact_snapshot#>'{downstreamSource,states}')
    THEN RAISE EXCEPTION 'impact review downstream state set incomplete' USING ERRCODE='23514'; END IF;
  FOR snapshot IN SELECT value FROM jsonb_array_elements(NEW.impact_snapshot#>'{downstreamSource,states}') LOOP
    SELECT jsonb_build_object('change',to_jsonb(change),'proposal',to_jsonb(proposal),'settlement',to_jsonb(settlement),
      'anchor',to_jsonb(anchor),'checkpoint',to_jsonb(checkpoint),'checkpoint_commit',to_jsonb(checkpoint_commit),
      'checkpoint_session',to_jsonb(checkpoint_session),'chapter_order',document.logical_order) INTO actual
      FROM state_changes change
      JOIN chapter_documents document ON document.id=change.chapter_document_id AND document.book_id=change.book_id AND document.status='active' AND document.adopted_version_id=change.body_version_id
      LEFT JOIN state_change_proposals proposal ON proposal.id=change.proposal_id
      LEFT JOIN chapter_settlements settlement ON settlement.id=change.settlement_id
      LEFT JOIN chapter_text_anchors anchor ON anchor.id=change.text_anchor_id
      LEFT JOIN chapter_stable_checkpoints checkpoint ON checkpoint.chapter_document_id=document.id AND checkpoint.book_id=change.book_id AND checkpoint.body_version_id=change.body_version_id AND checkpoint.status='stable'
      LEFT JOIN chapter_settlements checkpoint_commit ON checkpoint_commit.id=checkpoint.settlement_id AND checkpoint_commit.book_id=change.book_id AND checkpoint_commit.chapter_document_id=document.id AND checkpoint_commit.body_version_id=change.body_version_id
      LEFT JOIN chapter_adoption_sessions checkpoint_session ON checkpoint_session.id=checkpoint.session_id AND checkpoint_session.book_id=change.book_id AND checkpoint_session.chapter_document_id=document.id AND checkpoint_session.body_version_id=change.body_version_id AND checkpoint_session.settlement_id=checkpoint.settlement_id
      WHERE change.id=(snapshot#>>'{change,id}')::uuid AND change.book_id=NEW.book_id AND change.status='active' AND document.logical_order>base.chapter_order;
    IF actual IS DISTINCT FROM snapshot THEN RAISE EXCEPTION 'impact review downstream state source changed' USING ERRCODE='23514'; END IF;
  END LOOP;
  SELECT coalesce(jsonb_agg(value->>'stateChangeId' ORDER BY value->>'stateChangeId'),'[]'::jsonb) INTO conflicts
    FROM jsonb_array_elements(NEW.impact_snapshot->'stateChain') WHERE value->>'reason'<>'compatible';
  SELECT coalesce(jsonb_agg(value ORDER BY value),'[]'::jsonb) INTO acknowledged FROM jsonb_array_elements_text(NEW.full_input->'acknowledgedConflictStateChangeIds');
  IF acknowledged IS DISTINCT FROM conflicts THEN RAISE EXCEPTION 'impact review conflicts not explicitly acknowledged' USING ERRCODE='23514'; END IF;
  RETURN NEW;
END $$;


--
-- Name: validate_resource_supplement_integrity_issue(); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.validate_resource_supplement_integrity_issue() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $$
DECLARE review resource_supplement_impact_reviews%ROWTYPE; actual jsonb;
BEGIN
  SELECT review_row.* INTO review FROM resource_supplement_integrity_journals journal JOIN resource_supplement_impact_reviews review_row ON review_row.review_id=journal.review_id WHERE journal.settlement_id=NEW.settlement_id AND journal.book_id=NEW.book_id;
  SELECT value INTO actual FROM jsonb_array_elements(review.impact_snapshot->'stateChain') WHERE value->>'stateChangeId'=NEW.state_change_id::text;
  IF review.review_id IS NULL OR actual IS NULL OR actual IS DISTINCT FROM NEW.impact OR actual->>'reason' NOT IN ('before_conflict','backdated_source')
    OR actual->>'chapterDocumentId' IS DISTINCT FROM NEW.chapter_document_id::text OR actual->>'bodyVersionId' IS DISTINCT FROM NEW.body_version_id::text
    OR actual->>'subjectKind' IS DISTINCT FROM NEW.subject_kind OR actual->>'subjectId' IS DISTINCT FROM NEW.subject_id::text OR actual->>'stateKey' IS DISTINCT FROM NEW.state_key
    OR NEW.source_route IS DISTINCT FROM '/new-design/books/'||NEW.book_id||'/writing?chapterDocument='||NEW.chapter_document_id||'&resourceIssue='||NEW.issue_id
    OR NOT EXISTS(SELECT 1 FROM state_changes change JOIN chapter_documents document ON document.id=change.chapter_document_id AND document.book_id=change.book_id
      WHERE change.id=NEW.state_change_id AND change.book_id=NEW.book_id AND change.status='active' AND document.status='active' AND document.adopted_version_id=change.body_version_id
        AND change.chapter_document_id=NEW.chapter_document_id AND change.body_version_id=NEW.body_version_id AND change.subject_kind=NEW.subject_kind AND change.subject_id=NEW.subject_id AND change.state_key=NEW.state_key
        AND change.before_json IS NOT DISTINCT FROM actual->'recordedBefore' AND change.after_json IS NOT DISTINCT FROM actual->'recordedAfter')
    THEN RAISE EXCEPTION 'integrity issue actual conflicting source mismatch' USING ERRCODE='23514'; END IF;
  RETURN NEW;
END $$;


--
-- Name: validate_resource_supplement_integrity_journal(); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.validate_resource_supplement_integrity_journal() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $$
DECLARE review resource_supplement_impact_reviews%ROWTYPE; checkpoint chapter_stable_checkpoints%ROWTYPE;
  child chapter_adoption_sessions%ROWTYPE; snapshot jsonb;
BEGIN
  -- resource_supplement_integrity_v1
  SELECT * INTO review FROM resource_supplement_impact_reviews WHERE review_id=NEW.review_id AND book_id=NEW.book_id;
  SELECT * INTO checkpoint FROM chapter_stable_checkpoints WHERE id=NEW.checkpoint_id AND book_id=NEW.book_id AND settlement_id=NEW.settlement_id AND status='stable';
  SELECT * INTO child FROM chapter_adoption_sessions WHERE id=checkpoint.session_id AND book_id=NEW.book_id AND settlement_id=NEW.settlement_id AND status='stable' AND adoption_kind='resource_supplement';
  IF review.review_id IS NULL OR checkpoint.id IS NULL OR child.id IS NULL OR review.session_id IS DISTINCT FROM child.id
    OR checkpoint.previous_checkpoint_id IS DISTINCT FROM child.supplement_base_checkpoint_id
    OR checkpoint.summary->>'supplementReviewId' IS DISTINCT FROM NEW.review_id::text
    OR checkpoint.summary->>'supplementImpactHash' IS DISTINCT FROM review.impact_hash::text
    OR NEW.merged_write->>'sessionId' IS DISTINCT FROM child.id::text
    OR NEW.merged_write->>'settlementId' IS DISTINCT FROM NEW.settlement_id::text
    OR NEW.merged_write->>'checkpointId' IS DISTINCT FROM NEW.checkpoint_id::text
    OR NEW.merged_write->>'baseCheckpointId' IS DISTINCT FROM child.supplement_base_checkpoint_id::text
    OR NEW.merged_write->>'bodyVersionId' IS DISTINCT FROM child.body_version_id::text
    OR NEW.merged_write->>'reviewId' IS DISTINCT FROM NEW.review_id::text
    OR NEW.merged_write->>'impactHash' IS DISTINCT FROM review.impact_hash::text
    OR NEW.merged_write->'confirmed' IS DISTINCT FROM checkpoint.summary->'confirmed'
    OR NEW.canonical_merged::jsonb IS DISTINCT FROM NEW.merged_write
    OR encode(sha256(convert_to(NEW.canonical_merged,'UTF8')),'hex') IS DISTINCT FROM NEW.merged_hash::text
    OR NOT EXISTS(SELECT 1 FROM chapter_settlements WHERE id=NEW.settlement_id AND book_id=NEW.book_id AND status='committed' AND supplement_base_checkpoint_id=child.supplement_base_checkpoint_id)
    THEN RAISE EXCEPTION 'integrity journal merged source mismatch' USING ERRCODE='23514'; END IF;
  IF jsonb_typeof(NEW.merged_write->'newStateChangeIds') IS DISTINCT FROM 'array'
    OR (SELECT coalesce(jsonb_agg(id::text ORDER BY id),'[]'::jsonb) FROM state_changes WHERE settlement_id=NEW.settlement_id AND status='active')
      IS DISTINCT FROM (SELECT coalesce(jsonb_agg(value ORDER BY value),'[]'::jsonb) FROM jsonb_array_elements_text(NEW.merged_write->'newStateChangeIds'))
    THEN RAISE EXCEPTION 'integrity journal new states incomplete' USING ERRCODE='23514'; END IF;
  RETURN NEW;
END $$;


--
-- Name: validate_resource_supplement_origin(); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.validate_resource_supplement_origin() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $$
DECLARE child chapter_adoption_sessions%ROWTYPE; base chapter_stable_checkpoints%ROWTYPE;
BEGIN
  IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'supplement original receipt is immutable' USING ERRCODE='23514'; END IF;
  SELECT * INTO child FROM chapter_adoption_sessions WHERE id=NEW.session_id;
  SELECT * INTO base FROM chapter_stable_checkpoints WHERE id=NEW.base_checkpoint_id;
  IF child.adoption_kind IS DISTINCT FROM 'resource_supplement' OR child.supplement_base_checkpoint_id IS DISTINCT FROM base.id
    OR child.book_id IS DISTINCT FROM NEW.book_id OR base.book_id IS DISTINCT FROM NEW.book_id OR base.status IS DISTINCT FROM 'stable'
    OR NEW.source_snapshot->'basis'->'original'->'checkpoint' IS DISTINCT FROM to_jsonb(base)
    OR NEW.source_snapshot->>'sourceHash' IS DISTINCT FROM NEW.source_hash::text
    OR NEW.full_input->>'requestKey' IS DISTINCT FROM NEW.request_key
    OR NEW.full_input->>'checkpointId' IS DISTINCT FROM base.id::text
    OR NEW.full_input->>'expectedSourceHash' IS DISTINCT FROM NEW.source_hash::text
    OR NEW.original_receipt->>'sessionId' IS DISTINCT FROM child.id::text
    OR NEW.original_receipt->>'bookId' IS DISTINCT FROM NEW.book_id::text
    OR NEW.original_receipt->>'baseCheckpointId' IS DISTINCT FROM base.id::text
    OR NEW.original_receipt->>'bodyVersionId' IS DISTINCT FROM child.body_version_id::text
    OR NEW.original_receipt->>'preparationId' IS DISTINCT FROM child.preparation_id::text
    OR NEW.original_receipt->>'requestKey' IS DISTINCT FROM NEW.request_key
    OR NEW.original_receipt->'input' IS DISTINCT FROM NEW.full_input
    OR NEW.original_receipt->>'inputHash' IS DISTINCT FROM NEW.input_hash::text THEN
    RAISE EXCEPTION 'supplement full original input and source receipt mismatch' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: validate_resource_supplement_settlement(); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.validate_resource_supplement_settlement() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $$
BEGIN
  IF TG_OP='UPDATE' AND NEW.supplement_base_checkpoint_id IS DISTINCT FROM OLD.supplement_base_checkpoint_id THEN
    RAISE EXCEPTION 'supplement settlement origin is immutable' USING ERRCODE='23514';
  END IF;
  IF NEW.supplement_base_checkpoint_id IS NULL THEN RETURN NEW; END IF;
  IF NOT EXISTS(SELECT 1 FROM chapter_adoption_sessions child JOIN chapter_resource_supplements origin ON origin.session_id=child.id
    WHERE child.supplement_base_checkpoint_id=NEW.supplement_base_checkpoint_id AND child.book_id=NEW.book_id
      AND child.chapter_document_id=NEW.chapter_document_id AND child.body_version_id=NEW.body_version_id
      AND child.adoption_kind='resource_supplement') THEN
    RAISE EXCEPTION 'supplement settlement requires its owning supplement session' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: validate_runtime_health_snapshot(); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.validate_runtime_health_snapshot() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $$
BEGIN
  IF NOT EXISTS(SELECT 1 FROM runtime_installations WHERE installation_id=NEW.installation_id AND runtime_id=NEW.runtime_id AND active_data_generation=NEW.data_generation) THEN RAISE EXCEPTION 'runtime health snapshot does not match the active installation pointer' USING ERRCODE='23514'; END IF;
  RETURN NEW;
END $$;


--
-- Name: validate_runtime_upgrade_plan(); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.validate_runtime_upgrade_plan() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $$
BEGIN
  IF NOT EXISTS(SELECT 1 FROM transfer_operations WHERE id=NEW.backup_operation_id AND operation_kind='full_backup' AND status IN ('ready','archived')) THEN RAISE EXCEPTION 'runtime upgrade requires a ready full backup' USING ERRCODE='23514'; END IF;
  IF NOT EXISTS(SELECT 1 FROM transfer_operations WHERE id=NEW.compatibility_operation_id AND operation_kind='full_restore' AND execution_mode='dry_run' AND status='ready') THEN RAISE EXCEPTION 'runtime upgrade requires a ready compatibility dry-run' USING ERRCODE='23514'; END IF;
  IF NEW.source_postgres_major=NEW.target_postgres_major AND NEW.strategy<>'same_major_staged' THEN RAISE EXCEPTION 'same major upgrade must use staged strategy' USING ERRCODE='23514'; END IF;
  IF NEW.source_postgres_major<>NEW.target_postgres_major AND NEW.strategy='same_major_staged' THEN RAISE EXCEPTION 'cross major upgrade requires pg_upgrade or logical restore' USING ERRCODE='23514'; END IF;
  RETURN NEW;
END $$;


--
-- Name: validate_transfer_active_evidence(); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.validate_transfer_active_evidence() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $$
DECLARE owning_operation uuid;
BEGIN
  IF TG_TABLE_NAME='transfer_archive_entries' THEN SELECT operation_id INTO owning_operation FROM transfer_artifacts WHERE id=NEW.artifact_id;
  ELSE owning_operation:=NEW.operation_id;
  END IF;
  IF NOT EXISTS(SELECT 1 FROM transfer_operations WHERE id=owning_operation AND status IN ('running','verifying')) THEN RAISE EXCEPTION 'transfer evidence can only be appended while the operation is active' USING ERRCODE='23514'; END IF;
  RETURN NEW;
END $$;


--
-- Name: validate_transfer_artifact_insert(); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.validate_transfer_artifact_insert() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $$
BEGIN
  IF NOT EXISTS(SELECT 1 FROM transfer_operations operation WHERE operation.id=NEW.operation_id AND (operation.status IN ('running','verifying') OR (operation.status='queued' AND operation.execution_mode='dry_run' AND operation.source_artifact_id=NEW.id AND NEW.artifact_kind='package' AND NEW.status='pending'))) THEN RAISE EXCEPTION 'transfer artifact is outside the active or initial dry-run scope' USING ERRCODE='23514'; END IF;
  RETURN NEW;
END $$;


--
-- Name: validate_transfer_import_source(); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.validate_transfer_import_source() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $$
BEGIN
  IF NOT EXISTS(
    SELECT 1 FROM transfer_operations target
    JOIN transfer_operations source ON source.id=target.source_operation_id AND source.status='ready' AND source.execution_mode='dry_run'
    JOIN transfer_artifacts artifact ON artifact.id=NEW.source_artifact_id AND artifact.operation_id=source.id AND artifact.status='ready'
    JOIN transfer_manifests manifest ON manifest.id=NEW.source_manifest_id AND manifest.operation_id=source.id AND source.ready_manifest_id=manifest.id
    WHERE target.id=NEW.operation_id AND target.execution_mode='apply' AND target.source_artifact_id=artifact.id
  ) THEN RAISE EXCEPTION 'import source must match the ready dry-run operation' USING ERRCODE='23514'; END IF;
  RETURN NEW;
END $$;


--
-- Name: validate_transfer_operation_scope(); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.validate_transfer_operation_scope() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $$
BEGIN
  IF NEW.book_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM books WHERE id=NEW.book_id AND space_id=NEW.space_id) THEN RAISE EXCEPTION 'transfer operation book and space mismatch' USING ERRCODE='23514'; END IF;
  IF NEW.operation_kind='book_export' AND NEW.book_id IS NULL THEN RAISE EXCEPTION 'book export requires a book' USING ERRCODE='23514'; END IF;
  IF NEW.execution_mode='apply' AND NOT EXISTS(SELECT 1 FROM transfer_operations source WHERE source.id=NEW.source_operation_id AND source.status='ready' AND source.execution_mode='dry_run' AND source.operation_kind=NEW.operation_kind AND source.profile_key=NEW.profile_key AND source.source_artifact_id=NEW.source_artifact_id) THEN RAISE EXCEPTION 'apply operation requires a compatible ready dry-run source' USING ERRCODE='23514'; END IF;
  RETURN NEW;
END $$;


--
-- Name: validate_transfer_restore_drill(); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.validate_transfer_restore_drill() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $$
BEGIN
  IF NOT EXISTS(SELECT 1 FROM transfer_operations WHERE id=NEW.backup_operation_id AND operation_kind='full_backup' AND status IN ('ready','archived')) OR NOT EXISTS(SELECT 1 FROM transfer_operations WHERE id=NEW.drill_operation_id AND operation_kind='full_restore' AND execution_mode='dry_run' AND ((status='ready' AND NEW.outcome='passed') OR (status='failed' AND NEW.outcome IN ('failed','unavailable')) OR (status='cancelled' AND NEW.outcome='cancelled'))) THEN RAISE EXCEPTION 'restore drill scope mismatch' USING ERRCODE='23514'; END IF;
  RETURN NEW;
END $$;


--
-- Name: validate_visual_preview_source(); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.validate_visual_preview_source() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $$
DECLARE source_asset assets%ROWTYPE;
BEGIN
 IF NEW.visual_source IS NULL THEN RETURN NEW; END IF;
 SELECT * INTO source_asset FROM assets WHERE id=(NEW.visual_source->>'assetId')::uuid AND book_id=NEW.book_id AND asset_kind IN ('cover','illustration');
 IF NOT FOUND OR source_asset.status<>'active' OR source_asset.revision::text IS DISTINCT FROM NEW.visual_source->>'revision' OR source_asset.current_version_id::text IS DISTINCT FROM NEW.visual_source->>'fromVersionId' OR NOT EXISTS(
  SELECT 1 FROM dependency_resources resource WHERE resource.id=NEW.old_resource_id AND resource.book_id=NEW.book_id AND resource.resource_kind='asset_version' AND resource.stable_object_id=source_asset.id
 ) THEN RAISE EXCEPTION 'visual preview source scope mismatch' USING ERRCODE='23514'; END IF;
 IF (NEW.visual_source->>'toVersionId' IS NULL)<>(NEW.new_resource_id IS NULL) OR (NEW.new_resource_id IS NOT NULL AND NOT EXISTS(
  SELECT 1 FROM dependency_resources resource WHERE resource.id=NEW.new_resource_id AND resource.book_id=NEW.book_id AND resource.resource_kind='asset_version' AND resource.stable_object_id=source_asset.id AND resource.exact_version_id=(NEW.visual_source->>'toVersionId')::uuid
 )) THEN RAISE EXCEPTION 'visual preview target scope mismatch' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $$;


--
-- Name: validate_visual_source_receipt(); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.validate_visual_source_receipt() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $$
BEGIN
 IF NEW.visual_receipt IS NOT NULL AND (NEW.visual_receipt->>'bookId' IS DISTINCT FROM NEW.book_id::text OR NEW.visual_receipt->>'requestKey' IS DISTINCT FROM NEW.idempotency_key OR NEW.visual_receipt->>'assetId' IS DISTINCT FROM NEW.asset_id::text) THEN
  RAISE EXCEPTION 'visual source receipt identity mismatch' USING ERRCODE='23514';
 END IF;
 IF NEW.visual_receipt IS NOT NULL THEN
  IF TG_TABLE_NAME='asset_events' THEN
   IF NEW.visual_receipt->>'versionId' IS DISTINCT FROM NEW.asset_version_id::text OR (
    (NEW.visual_receipt->>'operation'='upload' AND NEW.action IN ('create','add_version')) OR
    (NEW.visual_receipt->>'operation'='description' AND NEW.action='add_version') OR
    (NEW.visual_receipt->>'operation'='adopt' AND NEW.action IN ('adopt','readopt','rollback')) OR
    (NEW.visual_receipt->>'operation'='archive' AND NEW.action='archive')
   ) IS NOT TRUE THEN RAISE EXCEPTION 'visual event operation or version mismatch' USING ERRCODE='23514'; END IF;
  ELSIF TG_TABLE_NAME='asset_mounts' THEN
   IF NEW.visual_receipt->>'versionId' IS DISTINCT FROM NEW.asset_version_id::text OR NEW.visual_receipt->>'mountId' IS DISTINCT FROM NEW.id::text OR NEW.visual_receipt->>'operation' IS DISTINCT FROM 'mount' THEN
    RAISE EXCEPTION 'visual mount operation or version mismatch' USING ERRCODE='23514';
   END IF;
  END IF;
 END IF;
 RETURN NEW;
END $$;


--
-- Name: validate_world_quality_material(); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.validate_world_quality_material() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $$ DECLARE actual_book uuid; BEGIN
 IF NEW.subject_kind='card' THEN SELECT book.id INTO actual_book FROM card_versions version JOIN cards card ON card.id=version.card_id JOIN books book ON book.space_id=card.space_id WHERE version.id=NEW.card_version_id AND card.id=NEW.subject_id;
 ELSE SELECT book.id INTO actual_book FROM card_relation_versions version JOIN card_relations relation ON relation.id=version.card_relation_id JOIN books book ON book.space_id=relation.space_id WHERE version.id=NEW.relation_version_id AND relation.id=NEW.subject_id; END IF;
 IF actual_book IS NULL OR NOT EXISTS(SELECT 1 FROM quality_audit_reports WHERE id=NEW.report_id AND book_id=actual_book) THEN RAISE EXCEPTION 'world quality source belongs to another book' USING ERRCODE='23514'; END IF;RETURN NEW;
END $$;


--
-- Name: world_quality_evidence_binding_guard(); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.world_quality_evidence_binding_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $$ BEGIN
 IF NEW.evidence_kind IN('card_field','relation_field') AND NOT EXISTS(
 SELECT 1 FROM quality_issue_versions version JOIN quality_issues issue ON issue.id=version.issue_id JOIN quality_report_material_versions binding ON binding.report_id=issue.report_id
 WHERE version.id=NEW.issue_version_id AND binding.subject_kind=NEW.material_kind AND binding.subject_id=NEW.material_id
 AND binding.card_version_id IS NOT DISTINCT FROM NEW.card_version_id AND binding.relation_version_id IS NOT DISTINCT FROM NEW.relation_version_id
 AND EXISTS(SELECT 1 FROM world_consistency_requests request JOIN quality_audit_reports report ON report.task_id=request.ai_task_id AND report.attempt_id=request.attempt_id AND report.book_id=request.book_id CROSS JOIN LATERAL jsonb_array_elements(request.generated_output->'findings') finding CROSS JOIN LATERAL jsonb_array_elements(finding->'evidence') evidence
  WHERE report.id=issue.report_id AND finding->>'stableKey'=issue.stable_key AND evidence->>'kind'=NEW.material_kind AND evidence->>'id'=NEW.material_id::text AND evidence->>'versionId'=COALESCE(NEW.card_version_id,NEW.relation_version_id)::text AND evidence->>'fieldKey'=NEW.field_key AND evidence->>'specVersionId' IS NOT DISTINCT FROM NEW.field_spec_version_id::text AND evidence->>'specHash'=NEW.field_spec_hash AND evidence->>'valueHash'=NEW.observed_value_hash))
 THEN RAISE EXCEPTION 'world issue evidence must bind exact original report material' USING ERRCODE='23514'; END IF;RETURN NEW;
END $$;


--
-- Name: world_package_sync_commands; Type: VIEW; Schema: new_design; Owner: -
--

CREATE VIEW new_design.world_package_sync_commands AS
 SELECT (jsonb_populate_record(NULL::new_design_compat.world_package_sync_commands, card."values")).id AS id,
    (jsonb_populate_record(NULL::new_design_compat.world_package_sync_commands, card."values")).book_id AS book_id,
    (jsonb_populate_record(NULL::new_design_compat.world_package_sync_commands, card."values")).installation_id AS installation_id,
    (jsonb_populate_record(NULL::new_design_compat.world_package_sync_commands, card."values")).request_key AS request_key,
    (jsonb_populate_record(NULL::new_design_compat.world_package_sync_commands, card."values")).operation AS operation,
    (jsonb_populate_record(NULL::new_design_compat.world_package_sync_commands, card."values")).sequence AS sequence,
    (jsonb_populate_record(NULL::new_design_compat.world_package_sync_commands, card."values")).input_hash AS input_hash,
    (jsonb_populate_record(NULL::new_design_compat.world_package_sync_commands, card."values")).input AS input,
    (jsonb_populate_record(NULL::new_design_compat.world_package_sync_commands, card."values")).receipt AS receipt,
    (jsonb_populate_record(NULL::new_design_compat.world_package_sync_commands, card."values")).created_at AS created_at
   FROM (new_design.cards card
     JOIN new_design.card_types type ON ((type.id = card.card_type_id)))
  WHERE ((type.type_key = 'legacy.world_package_sync_commands'::text) AND (card.status = 'active'::text));


--
-- Name: world_sync_selected_input(new_design.world_package_sync_commands); Type: FUNCTION; Schema: new_design; Owner: -
--

CREATE FUNCTION new_design.world_sync_selected_input(command new_design.world_package_sync_commands) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'new_design', 'ag_catalog', 'public'
    AS $$
DECLARE selected jsonb;
BEGIN
 IF command.operation='publish' THEN
  SELECT candidate.snapshot->'input' INTO selected FROM world_package_push_candidates candidate
   JOIN world_package_versions package ON package.id=(command.receipt->>'publishedPackageId')::uuid
   WHERE candidate.id=(command.input->>'candidateId')::uuid AND candidate.installation_id=command.installation_id AND candidate.book_id=command.book_id
    AND package.request_key=(command.input->>'publicRequestKey')::uuid;
 ELSE selected:=command.input; END IF;
 RETURN selected;
END $$;


