    (jsonb_populate_record(NULL::new_design_compat.ai_approval_decisions, card."values")).decided_by_kind AS decided_by_kind,
    (jsonb_populate_record(NULL::new_design_compat.ai_approval_decisions, card."values")).decided_by AS decided_by,
    (jsonb_populate_record(NULL::new_design_compat.ai_approval_decisions, card."values")).policy_version AS policy_version,
    (jsonb_populate_record(NULL::new_design_compat.ai_approval_decisions, card."values")).reason AS reason,
