    (jsonb_populate_record(NULL::new_design_compat.ai_approval_requests, card."values")).requested_by_kind AS requested_by_kind,
    (jsonb_populate_record(NULL::new_design_compat.ai_approval_requests, card."values")).requested_by AS requested_by,
