    relation_type_id uuid NOT NULL,
    source_card_id uuid NOT NULL,
    target_card_id uuid NOT NULL,
    status text DEFAULT 'active'::text NOT NULL,
    valid_from text,
    valid_to text,
    properties jsonb DEFAULT '{}'::jsonb NOT NULL,
    revision integer DEFAULT 1 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    current_version_id uuid,
    created_by text DEFAULT 'migration'::text NOT NULL,
    CONSTRAINT card_relations_check CHECK ((source_card_id <> target_card_id)),
    CONSTRAINT card_relations_revision_check CHECK ((revision > 0)),
    CONSTRAINT card_relations_status_check CHECK ((status = ANY (ARRAY['active'::text, 'inactive'::text, 'archived'::text])))
);


--
-- Name: card_reverse_references; Type: VIEW; Schema: new_design; Owner: -
--

CREATE VIEW new_design.card_reverse_references AS
 SELECT id AS card_id,
    ( SELECT count(*) AS count
           FROM new_design.card_mounts mount
          WHERE ((mount.card_id = card.id) AND (mount.status = 'active'::text))) AS active_mount_count,
    ( SELECT count(*) AS count
           FROM new_design.card_relations relation
          WHERE (((relation.source_card_id = card.id) OR (relation.target_card_id = card.id)) AND (relation.status = 'active'::text))) AS active_relation_count
   FROM new_design.cards card;


