    (jsonb_populate_record(NULL::new_design_compat.publication_export_manifest_chapters, card."values")).updated_at_snapshot AS updated_at_snapshot
   FROM (new_design.cards card
     JOIN new_design.card_types type ON ((type.id = card.card_type_id)))
