    CONSTRAINT runtime_health_snapshots_free_disk_bytes_check CHECK ((free_disk_bytes >= 0)),
    CONSTRAINT runtime_health_snapshots_migration_count_check CHECK (((migration_count >= 0) AND (migration_count <= 10000))),
