    (jsonb_populate_record(NULL::new_design_compat.semantic_retrieval_policies, card."values")).max_timeout_ms AS max_timeout_ms,
    (jsonb_populate_record(NULL::new_design_compat.semantic_retrieval_policies, card."values")).max_query_chars AS max_query_chars,
    (jsonb_populate_record(NULL::new_design_compat.semantic_retrieval_policies, card."values")).default_vector_weight AS default_vector_weight,
    (jsonb_populate_record(NULL::new_design_compat.semantic_retrieval_policies, card."values")).default_fts_weight AS default_fts_weight,
    (jsonb_populate_record(NULL::new_design_compat.semantic_retrieval_policies, card."values")).default_trigram_weight AS default_trigram_weight,
    (jsonb_populate_record(NULL::new_design_compat.semantic_retrieval_policies, card."values")).updated_at AS updated_at
   FROM (new_design.cards card
