    (jsonb_populate_record(NULL::new_design_compat.transfer_import_sources, card."values")).source_operation_key AS source_operation_key,
    (jsonb_populate_record(NULL::new_design_compat.transfer_import_sources, card."values")).imported_by AS imported_by,
    (jsonb_populate_record(NULL::new_design_compat.transfer_import_sources, card."values")).created_at AS created_at
   FROM (new_design.cards card
